def shutdown(server, application, graceful=True, ioloop=None):
    ioloop = ioloop or IOLoop.current()
    if not getattr(server, '_stopping', False):
        server._stopping = True
        if graceful:
            ioloop.add_timeout(ioloop.time() + graceful, ioloop.stop)
        else:
            ioloop.stop()

