class KeywordManager:
    def __init__(self):
        self.keywords = {}
        self.active_keyword = None
    def add_keyword(self, keyword, comment):
        """
        Add a new keyword with an associated comment.
        If the keyword already exists, update its comment.
        """
        if keyword in self.keywords:
            self.keywords[keyword] = comment
        else:
            self.keywords[keyword] = comment
    def mark_active(self, keyword):
        """
        Mark a keyword as active.
        """
        if keyword in self.keywords:
            self.active_keyword = keyword
        else:
            print(f"Keyword '{keyword}' does not exist.")
    def generate_report(self):
        """
        Generate a report of all keywords and their associated comments.
        """
        report = "Keyword Report:\n"
        for keyword, comment in self.keywords.items():
            active_indicator = " (Active)" if keyword == self.active_keyword else ""
            report += f"{keyword}: {comment}{active_indicator}\n"
        return report
