from scrapy import Selector
def extract_description_text(response, element_type):
    if element_type not in ["td", "p"]:
        raise ValueError("Invalid element_type. It must be 'td' or 'p'.")
    selector = Selector(text=response.body)
    if element_type == "td":
        extracted_text = map(unicode.strip, selector.xpath('//div[@class="description"]//td//text()[normalize-space()]').extract())
    else:  # element_type is "p"
        extracted_text = map(unicode.strip, selector.xpath('//div[@class="description"]//p//text()[normalize-space()]').extract())
    return extracted_text

import re
def extract_info(code_snippet):
    info_dict = {}

    # Extract resource name
    resource_name_match = re.search(r'resource_name:\s*(\w+)', code_snippet)
    if resource_name_match:
        info_dict["ResourceName"] = resource_name_match.group(1)

    # Extract version from comments
    version_match = re.search(r'Release\s+(\d+\.\d+\.\d+)', code_snippet)
    if version_match:
        info_dict["Version"] = version_match.group(1)
    else:
        info_dict["Version"] = "Not specified"

    return info_dict
