def detect_deadlock(allocated, max_demand, available):
    n = len(allocated)  # Number of processes
    m = len(available)  # Number of resource types
    # Initialize work and finish arrays
    work = available[:]
    finish = [False] * n
    # Find a process that can be executed
    while True:
        found = False
        for i in range(n):
            if not finish[i] and all(need <= work for need, work in zip(max_demand[i], work)):
                # Process can be executed
                found = True
                finish[i] = True
                work = [work[j] + allocated[i][j] for j in range(m)]
                break
        if not found:
            break
    return all(finish)

class Solution:
    def isSubtree(self, s: TreeNode, t: TreeNode) -> bool:
        def is_same_tree(s: TreeNode, t: TreeNode) -> bool:
            if not s and not t:
                return True
            if not s or not t:
                return False
            return s.val == t.val and is_same_tree(s.left, t.left) and is_same_tree(s.right, t.right)
        if not s:
            return False
        return is_same_tree(s, t) or self.isSubtree(s.left, t) or self.isSubtree(s.right, t)

