def convert_pg_array(pg_array):
    """
    Convert a PostgreSQL array-string to a Python list.
    PostgreSQL <9.0 used comma-separated strings as the array datatype. This function will convert those to a list. If pg_array is not a string, it will not be modified.
    """
    if not isinstance(pg_array, (str, unicode)):
        return pg_array
    # Only for one-dimensional arrays
    return list(map(str.strip, pg_array.strip("{}").split(",")))

