from typing import TypeVar, List, Set, Dict, Union
_T1 = TypeVar("_T1")
_T2 = TypeVar("_T2")
class NonEmptyList:
    def __init__(self, *args: _T1) -> None:
        if not args:
            raise ValueError("NonEmptyList must contain at least one element")
        self._data = list(args)
    def __getitem__(self, index: int) -> _T1:
        return self._data[index]
    def __setitem__(self, index: int, value: _T1) -> None:
        self._data[index] = value
    def __delitem__(self, index: int) -> None:
        del self._data[index]
    def __len__(self) -> int:
        return len(self._data)
    def append(self, value: _T1) -> None:
        self._data.append(value)
    def extend(self, values: List[_T1]) -> None:
        self._data.extend(values)
    def remove(self, value: _T1) -> None:
        self._data.remove(value)
    def to_set(self) -> Set[_T1]:
        return set(self._data)
    def to_dict(self) -> Dict[_T1, _T2]:
        if len(self._data) % 2 != 0:
            raise ValueError("NonEmptyDict must contain an even number of elements")
        return dict(zip(self._data[::2], self._data[1::2]))

def validate_config(config):
    if not isinstance(config, dict):
        return False

    if 'database' not in config or not isinstance(config['database'], dict):
        return False

    database = config['database']
    if 'name' not in database or not isinstance(database['name'], str) or not database['name']:
        return False

    if 'collections' not in database or not isinstance(database['collections'], dict):
        return False

    collections = database['collections']
    if 'posts' not in collections or not isinstance(collections['posts'], dict):
        return False

    posts = collections['posts']
    if 'data_relation' not in posts or not isinstance(posts['data_relation'], dict):
        return False

    data_relation = posts['data_relation']
    if not all(key in data_relation for key in ['resource', 'field', 'embeddable']):
        return False

    if not isinstance(data_relation['resource'], str) or not isinstance(data_relation['field'], str) or not isinstance(data_relation['embeddable'], bool):
        return False

    return True

