import heapq
def find_path():
    start = maze_map.get_start()
    end = maze_map.get_end()

    open_set = [(0, start, [])]  # (f, (x, y), path)
    closed_set = set()

    while open_set:
        _, (x, y), path = heapq.heappop(open_set)

        if (x, y) == end:
            return path + [(x, y)]

        if (x, y) in closed_set:
            continue

        closed_set.add((x, y))

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            new_x, new_y = x + dx, y + dy
            if maze_map.is_valid(new_x, new_y):
                new_path = path + [(x, y)]
                g = len(new_path)
                h = maze_map.heuristic(new_x, new_y)
                f = g + h
                heapq.heappush(open_set, (f, (new_x, new_y), new_path))

    return []  # No path found

import torch
def custom_mean(tensor, dim=None, keepdim=False):
    if dim is None:
        # mean all dim
        return torch.mean(tensor)
    else:
        if isinstance(dim, int):
            dim = [dim]
        dim = sorted(dim)
        for d in dim:
            tensor = tensor.mean(dim=d, keepdim=True)
        if not keepdim:
            for i, d in enumerate(dim):
                tensor.squeeze_(d - i)
        return tensor

