import re
class TextGenerator:
    def generate_text(
        self, inputs, max_length=100, stop_string=None, output_regex=None
    ):
        dummy_text = "dummy text, 123. Easy peasy lemon squeezy."
        if isinstance(inputs, str):
            text = dummy_text
        elif isinstance(inputs, list):
            text = [f"{i}_{dummy_text}" for i, _ in enumerate(inputs)]
        else:
            raise ValueError("inputs has unexpected type %s" % type(inputs))
        text = self.postprocess_output(text, max_length, stop_string, output_regex)
        return text
    def postprocess_output(self, text, max_length, stop_string, output_regex):
        if isinstance(text, list):
            text = " ".join(text)
        if stop_string and stop_string in text:
            text = text[:text.index(stop_string) + len(stop_string)]
        if output_regex:
            text = re.sub(output_regex, '', text)
        if max_length and len(text) > max_length:
            text = text[:max_length]
        return text

