from typing import Type
class Node:
    def __init__(self, data: Type) -> None:
        self.data = data
        self.next = None
class GenericStack:
    def __init__(self) -> None:
        self.top = None
        self.size = 0
    def is_empty(self) -> bool:
        return self.size == 0
    def push(self, data: Type) -> None:
        new_node = Node(data)
        new_node.next = self.top
        self.top = new_node
        self.size += 1
    def pop(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")
        data = self.top.data
        self.top = self.top.next
        self.size -= 1
        return data
    def peek(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.top.data
    def get_size(self) -> int:
        return self.size

from pint import UnitRegistry
class Float:
    def __init__(self, setter=False, values=None, unit=None, mapping=None):
        self.setter = setter
        self.values = values if values else []
        self.unit = unit
        self.mapping = mapping if mapping else {}
    def pre_set(self, _, value):
        if self.setter:
            if self.unit:
                return self.convert_to_unit(value)
            return value
        else:
            raise ValueError("Setter is not enabled")
    def post_get(self, _, value):
        if self.mapping:
            return self.mapping.get(value, None)
        return value
    def convert_to_unit(self, value):
        if self.unit:
            ureg = UnitRegistry()
            return ureg(value).to(self.unit).magnitude
        return value
# Test cases
