public class CumulativeMinMax {
    public static int[][] cumMinMaxCompare(String op, int[][][] x, int[][][] cummaxOutput, int axis, String dataType) {
        int[][] result = new int[x.length][x[0].length];
        if (op.equals("min")) {
            for (int i = 0; i < x.length; i++) {
                for (int j = 0; j < x[0].length; j++) {
                    int minVal = Integer.MAX_VALUE;
                    for (int k = 0; k < x[0][0].length; k++) {
                        if (dataType.equals("int32")) {
                            minVal = Math.min(minVal, x[i][j][k]);
                        } else if (dataType.equals("int64")) {
                            minVal = (int) Math.min(minVal, (long) x[i][j][k]);
                        }
                    }
                    result[i][j] = minVal;
                }
            }
        } else if (op.equals("max")) {
            for (int i = 0; i < x.length; i++) {
                for (int j = 0; j < x[0].length; j++) {
                    int maxVal = Integer.MIN_VALUE;
                    for (int k = 0; k < x[0][0].length; k++) {
                        if (dataType.equals("int32")) {
                            maxVal = Math.max(maxVal, x[i][j][k]);
                        } else if (dataType.equals("int64")) {
                            maxVal = (int) Math.max(maxVal, (long) x[i][j][k]);
                        }
                    }
                    result[i][j] = maxVal;
                }
            }
        }
        return result;
