from abc import ABC, abstractmethod
class AbstractRow(ABC):
    pass
class JoinedRow(AbstractRow):
    def __init__(self, left: Dict[str, Any], right: Dict[str, Any], _id: int):
        self.left = left
        self.right = right
        self._id = _id
class RightJoin(LeftJoin):
    def _produce(self) -> Iterator[AbstractRow]:
        for right_row, joined_rows in self.grouped:
            matched = False
            for joined_row in joined_rows:
                left_row = joined_row.left
                if self.predicate(left_row, right_row):
                    matched = True
                    yield JoinedRow(left_row, right_row, _id=-1)
            if not matched:
