def process_doe_params(doe_size=10, obj_wgt=None):
    # Rule 1: If doe_size is not provided, default to 10
    if doe_size is None:
        doe_size = 10
    # Rule 2: If obj_wgt is not provided, default to None
    if obj_wgt is None:
        obj_wgt = None
    # Rule 3: If obj_wgt is a single float, convert it to a list containing that single float
    elif isinstance(obj_wgt, float):
        obj_wgt = [obj_wgt]
    # Rule 4: If obj_wgt is an iterable, validate its length
    elif hasattr(obj_wgt, '__iter__'):
        if len(obj_wgt) != doe_size:
            raise ValueError("Length of obj_wgt must be the same as the number of stochastic input variables")
    else:
        raise ValueError("Invalid obj_wgt format")
    return doe_size, obj_wgt

import aiohttp
from typing import Optional, Dict, Union
async def get(url: str, proxy: Optional[str] = None, headers: Optional[Dict[str, str]] = None, byte: Optional[bytes] = None, timeout: int = 15) -> Union[bytes, None]:
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url, proxy=proxy, headers=headers, data=byte, timeout=timeout) as response:
                if response.status == 200:
                    return await response.read()
                else:
                    return None
    except aiohttp.ClientError:
        return None

