class TaskManager(Cog):
    def __init__(self, debug_mode: bool = False) -> None:
        super().__init__("task_manager")
        self.debug_mode = debug_mode
        self.tasks = []
    def add_task(self, task: str) -> None:
        self.tasks.append({"task": task, "completed": False})
        if self.debug_mode:
            log.debug(f"Task added: {task}")
    def complete_task(self, task_index: int) -> None:
        if 0 <= task_index < len(self.tasks):
            self.tasks[task_index]["completed"] = True
            if self.debug_mode:
                log.debug(f"Task completed: {self.tasks[task_index]['task']}")
        else:
            if self.debug_mode:
                log.debug(f"Invalid task index: {task_index}")
    def list_tasks(self) -> List[str]:
        task_list = [f"{i+1}. [{task['completed'] and 'X' or ' '}] {task['task']}" for i, task in enumerate(self.tasks)]
        if self.debug_mode:
            log.debug(f"Tasks listed: {task_list}")
        return task_list

from datetime import datetime
def generate_date_query(start_date: str = None, end_date: str = None, date: str = None) -> dict:
    if start_date and end_date:
        start_date_obj = datetime.strptime(start_date, "%d/%m/%Y")
        end_date_obj = datetime.strptime(end_date, "%d/%m/%Y")
        assert (start_date_obj < end_date_obj), "The first date must be lower than the second."
        return {POST_PUB_DATE: {
            "$gte": start_date_obj,
            "$lt": end_date_obj
        }}
    elif date:
        post_pub_date = datetime.strptime(date, "%d/%m/%Y")
        return {POST_PUB_DATE: post_pub_date}
    else:
        raise ValueError("At least one of start_date, end_date, or date must be provided.")

