        self.pcp_mla_mask = None
        self.swa_mask = None
    def get_attn_mask(self, max_seq_len: int, dtype: torch.dtype):
        if self.attn_mask_cache is None or max_seq_len > self._seq_len_cached:
            self.attn_mask_cache = _generate_attn_mask(max_seq_len, dtype)
            self._seq_len_cached = max_seq_len
        assert self.attn_mask_cache is not None, "Something is wrong in generate_attn_mask."
        if self.attn_mask_cache.dtype != dtype:
            self.attn_mask_cache = self.attn_mask_cache.to(dtype)
        return self.attn_mask_cache[:max_seq_len, :max_seq_len].contiguous().to(self.device, non_blocking=True)
    def get_splitfuse_attn_mask(self) -> torch.Tensor:
        if self.chunked_prefill_attn_mask is None:
            self.chunked_prefill_attn_mask = (
                torch.triu(torch.ones(2048, 2048), diagonal=1).to(torch.int8).to(self.device)
            )
        return self.chunked_prefill_attn_mask
    def get_mla_mask(self, dtype: torch.dtype) -> torch.Tensor:
        if self.mla_mask is None or self.mla_mask.dtype != dtype:
            if dtype == torch.float16:
                mask_value = torch.finfo(torch.float32).min
            else:
                mask_value = 1
            prefill_mask = torch.triu(torch.ones(512, 512, device=self.device, dtype=dtype), 1)
            self.mla_mask = torch.where(prefill_mask == 1, mask_value, 0).to(dtype)
        return self.mla_mask
    def get_pcp_mla_mask(self, dtype: torch.dtype):
        if self.pcp_mla_mask is None or self.pcp_mla_mask.dtype != dtype:
            self.pcp_mla_mask = torch.triu(torch.ones(512, 512, device=self.device, dtype=dtype), 1)
        return self.pcp_mla_mask
    def get_swa_mask(self, dtype: torch.dtype, sliding_window):
        if self.swa_mask is None or self.swa_mask.dtype != dtype:
            if sliding_window is not None:
                mask = torch.ones(2048, 2048, dtype=torch.bool)
                triu_mask = torch.triu(mask, diagonal=1).to(self.device)
                tril_mask = torch.tril(mask, -sliding_window).to(self.device)
                self.swa_mask = triu_mask + tril_mask
        return self.swa_mask
    def get_attention_mask(self, model_config: ModelConfig):
        if model_config.runner_type == "pooling":
            return self.get_attn_mask(2048, torch.bool)
        return self.get_splitfuse_attn_mask()
    def get_final_mla_mask(self, model_config: ModelConfig):
        if get_pcp_group().world_size > 1:
            return self.get_pcp_mla_mask(model_config.dtype)
        # Prefill stages use 512x512 mask with appropriate dtype
        return self.get_mla_mask(model_config.dtype)

import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider
logger = logging.getLogger(__name__)
class EpikDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "epik"
    PROVIDER_NAME = "Epik"
    PROVIDER_DESCRIPTION = "Epik Domains DNS API"
    REQUIRED_CREDENTIALS = ["api_key"]

    BASE_URL = "https://usersapiv2.epik.com/v2"

    def _request(self, method: str, path: str, params: Optional[Dict] = None, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        url = f"{self.BASE_URL}{path}"
        if params is None:
            params = {}
        params['SIGNATURE'] = self.credentials['api_key']
        try:
            resp = requests.request(method=method, url=url, params=params, json=data, timeout=30)
            if resp.status_code >= 400:
                return False, resp.reason
            body = resp.json()
            if body.get('code') != 200 and body.get('status') != 'SUCCESS':
                return False, body.get('message', 'Unknown error')
            return True, body
        except requests.RequestException as e:
            return False, str(e)

    def create_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        host = self.get_relative_record_name(record_name, domain)
        data = {'HOST': host, 'TYPE': 'TXT', 'DATA': record_value, 'TTL': ttl, 'AUX': 0}
        success, result = self._request('POST', f'/domains/{domain}/records', data=data)
        if not success:
            return False, f"Failed to create record: {result}"
        return True, "Record created successfully"

    def delete_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        success, result = self._request('GET', f'/domains/{domain}/records')
        if not success:
            return False, f"Failed to list records: {result}"
        host = self.get_relative_record_name(record_name, domain)
        records = result.get('data', {}).get('records', [])
        for rec in records:
            if rec.get('TYPE') == 'TXT' and rec.get('HOST') == host:
                self._request('DELETE', f'/domains/{domain}/records/{rec["ID"]}')
        return True, "Record deleted successfully"

    def test_connection(self) -> Tuple[bool, str]:
        success, result = self._request('GET', '/domains')
        if success:
            return True, "Connected successfully"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'api_key', 'label': 'API Key (Signature)', 'type': 'password', 'required': True,
             'help': 'Epik > Account > API Signature'},
        ]

import os
import re
import sys
#/* Define block */
verbosity = False
#/* Usage method */
def print_usage(name):
    """ Simple method to output usage when needed """
    sys.stderr.write("\nUsage: %s [-/-h/-help] [-v/-verbose]\n" % name);
    sys.stderr.write("Enter purpose here.\n");
    sys.stderr.write("-/-h/-help        :show this information\n");
    sys.stderr.write("-v/-verbose       :run more verbosely\n");
    sys.stderr.write("\n\n");
#/* Main */
def main():
    global verbosity
    filename = None
    i = 1
    while i < len(sys.argv):
        if sys.argv[i] == '-' or sys.argv[i] == '-h' or sys.argv[i] == '-help':
            print_usage(sys.argv[0]);
            sys.exit(0);
        elif sys.argv[i] == '-v' or sys.argv[i] == '-verbose':
            verbosity = True
        elif sys.argv[i] == '-f' or sys.argv[i] == '-file':
            i += 1
            if i < len(sys.argv):
                filename = sys.argv[i]
        else:
            sys.stderr.write("\nWhoops - Unrecognized argument: %s\n" % sys.argv[i]);
            print_usage(sys.argv[0]);
            sys.exit(10);
        i += 1
    # Process from file or stdin
    if filename is not None:
        infile = open(filename, 'r')
    else:
        infile = sys.stdin
    section = 0
    subsection = 0
    line = infile.readline()
    while len(line) > 0:
        newline = line
        m = re.search('^###(.*)', line)
        if m is not None:
            subsection += 1
            newline = ('%d.%d' % (section, subsection)) + m.group(1) + '\n'
        else:
            m = re.search('^##(.*)', line)
            if m is not None:
                section += 1
                subsection = 0
                newline = ('%d.%d' % (section, subsection)) + m.group(1) + '\n'
            else:
                m = re.search('^#(.*)', line)
                if m is not None:
                    newline = m.group(1) + '\n'
        m = re.search('^\*\*\*', line)
        m2 = re.search('^~~~', line)
        if m is not None or m2 is not None:
            newline = ('----------------------------------------'
                       '----------------------------------------\n')
        m = re.search('\.png\)', line)
        if m is not None:
            newline = ''
        sys.stdout.write(newline)
        line = infile.readline()
if __name__ == "__main__":
    main()

import random
import itertools
import numpy as np
import torch
def build_iterations(train_dl=None, val_dl=None, test_dl=None, iterator_type="cyclic"):
    def _cyclic_iter(dl):
        while True:
            for x in dl:
                yield x

    def _get_iterator(dataloader, iter_type=iterator_type):
        """Return dataset iterator."""
        if iter_type == "single":
            return iter(dataloader)
        elif iter_type == "cyclic":
            return iter(_cyclic_iter(dataloader))
        else:
            raise NotImplementedError("unexpected iterator type")
    if train_dl is not None:
        train_data_iterator = _get_iterator(train_dl)
    else:
        train_data_iterator = None
    if val_dl is not None:
        valid_data_iterator = _get_iterator(val_dl)
    else:
        valid_data_iterator = None
    if test_dl is not None:
        test_data_iterator = _get_iterator(test_dl)
    else:
        test_data_iterator = None
    return train_data_iterator, valid_data_iterator, test_data_iterator
def get_seed_worker(seed):
    """Deterministic dataloader"""
    def seed_worker(worker_id):
        worker_seed = seed
        np.random.seed(worker_seed)
        torch.manual_seed(worker_seed)
        random.seed(worker_seed)
    return seed_worker

from typing import Optional, Tuple
from primus.core.projection.base_module_profiler import BaseModuleProfiler
from primus.core.projection.profiler_spec import ModuleProfilerSpec
from primus.core.projection.training_config import TrainingConfig
from .utils import benchmark_layer
class DenseMLPProfiler(BaseModuleProfiler):
    def __init__(self, config, sub_profilers=None):
        super().__init__(config, sub_profilers)
        self.module = None  # Will be set during benchmarking
        self._cached_results = None  # Cache for (forward_time, backward_time, activation_memory)
        self._cache_key = None  # Cache key (batch_size, seq_len)
    def set_module(self, module):
        """Set the actual Dense MLP module for benchmarking."""
        self.module = module
        # Invalidate cache when module changes
        self._cached_results = None
        self._cache_key = None
    def estimated_num_params(self, rank: Optional[int] = None) -> int:
        # For SwiGLU: 3 projections (gate, up, down)
        # For standard FFN: 2 projections (up, down)
        num_ffn_projections = 3 if self.config.model_config.swiglu else 2
        return (
            self.config.model_config.hidden_size
            * self.config.model_config.ffn_hidden_size
            * num_ffn_projections
        )
    def estimated_activation_memory(self, batch_size: int, seq_len: int) -> int:
        num_tokens = (
            batch_size
            * seq_len
            // self.config.model_parallel_config.tensor_model_parallel_size
            // self.config.model_parallel_config.context_model_parallel_size
        )
        # Memory after first projection(s)
        if self.config.model_config.swiglu:
            # Need to store both gate and up projections for backward
            intermediate_memory = 2 * num_tokens * self.config.model_config.ffn_hidden_size * 2  # bf16
        else:
            intermediate_memory = num_tokens * self.config.model_config.ffn_hidden_size * 2  # bf16
        # After activation
        activation_memory = num_tokens * self.config.model_config.ffn_hidden_size * 2  # bf16
        output_memory = num_tokens * self.config.model_config.hidden_size * 2  # bf16
        # Peak memory is input + intermediate (both needed for backward)
        return intermediate_memory + activation_memory + output_memory
    def _get_benchmark_results(self, batch_size: int, seq_len: int) -> Tuple[float, float, int]:
        """Get or compute benchmark results (cached)."""
        cache_key = (batch_size, seq_len)
        if self._cached_results is None or self._cache_key != cache_key:
            self._cached_results = benchmark_layer(
                self.module,
                [(seq_len, batch_size, self.config.model_config.hidden_size)],
            )
            self._cache_key = cache_key
        return self._cached_results
    def measured_forward_time(self, batch_size: int, seq_len: int) -> float:
        forward_time, _, _ = self._get_benchmark_results(batch_size, seq_len)
        return forward_time
    def measured_backward_time(self, batch_size: int, seq_len: int) -> float:
        _, backward_time, _ = self._get_benchmark_results(batch_size, seq_len)
        return backward_time
    def measured_activation_memory(self, batch_size: int, seq_len: int) -> int:
        _, _, activation_memory = self._get_benchmark_results(batch_size, seq_len)
        return activation_memory
def get_dense_mlp_profiler_spec(config: TrainingConfig) -> ModuleProfilerSpec:
    return ModuleProfilerSpec(
        profiler=DenseMLPProfiler,
        config=config,
        sub_profiler_specs=None,
    )

