class RequestException(IOError):
    """There was an ambiguous exception that occurred while handling your
    request.
    """
    def __init__(self, *args, **kwargs):
        """Initialize RequestException with `request` and `response` objects."""
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = self.response.request
        super().__init__(*args, **kwargs)
class InvalidJSONError(RequestException):
    """A JSON error occurred."""
class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Couldn't decode the text into json"""
    def __init__(self, *args, **kwargs):
        """
        Construct the JSONDecodeError instance first with all
        args. Then use it's args to construct the IOError so that
        the json specific args aren't used as IOError specific args
        and the error message from JSONDecodeError is preserved.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)
class HTTPError(RequestException):
    """An HTTP error occurred."""
class ConnectionError(RequestException):
    """A Connection error occurred."""
class ProxyError(ConnectionError):
    """A proxy error occurred."""
class SSLError(ConnectionError):
    """An SSL error occurred."""
class Timeout(RequestException):
    """The request timed out.
    Catching this error will catch both
    :exc:`~requests.exceptions.ConnectTimeout` and
    :exc:`~requests.exceptions.ReadTimeout` errors.
    """
class ConnectTimeout(ConnectionError, Timeout):
    """The request timed out while trying to connect to the remote server.
    Requests that produced this error are safe to retry.
    """
class ReadTimeout(Timeout):
    """The server did not send any data in the allotted amount of time."""
class URLRequired(RequestException):
    """A valid URL is required to make a request."""
class TooManyRedirects(RequestException):
    """Too many redirects."""
class MissingSchema(RequestException, ValueError):
    """The URL scheme (e.g. http or https) is missing."""
class InvalidSchema(RequestException, ValueError):
    """The URL scheme provided is either invalid or unsupported."""
class InvalidURL(RequestException, ValueError):
    """The URL provided was somehow invalid."""
class InvalidHeader(RequestException, ValueError):
    """The header value provided was somehow invalid."""
class InvalidProxyURL(InvalidURL):
    """The proxy URL provided is invalid."""
class ChunkedEncodingError(RequestException):
    """The server declared chunked encoding but sent an invalid chunk."""
class ContentDecodingError(RequestException, BaseHTTPError):
    """Failed to decode response content."""
class StreamConsumedError(RequestException, TypeError):
    """The content for this response was already consumed."""
class RetryError(RequestException):
    """Custom retries logic failed"""
class UnrewindableBodyError(RequestException):
    """Requests encountered an error when trying to rewind a body."""
# Warnings
class RequestsWarning(Warning):
    """Base warning for Requests."""
class FileModeWarning(RequestsWarning, DeprecationWarning):
    """A file was opened in text mode, but Requests determined its binary length."""
class RequestsDependencyWarning(RequestsWarning):
    """An imported dependency doesn't match the expected version range."""

from abc import ABC, abstractmethod
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes
class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        self._mapping: dict[ToolTypes, type[StatGptTool]] = {}
    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must be a subclass of {StatGptTool}")
        if tool_type in self._mapping:
            raise ValueError(
                f"Cant register {factory} factory:"
                f" {tool_type=} already registered with {self._mapping[tool_type]}"
            )
        self._mapping[tool_type] = factory
    def __delitem__(self, tool_type: ToolTypes, /):
        del self._mapping[tool_type]
    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        if key not in self._mapping:
            raise KeyError(
                f"Factory has not been registered for {key} agent."
                f" Please ensure that the factory is imported in the global space."
                f"\nAvailable agents: {list(self._mapping.keys())}"
            )
        return self._mapping[key]
    def __iter__(self):
        return iter(self._mapping)
    def __len__(self):
        return len(self._mapping)
_TOOL_IMPLEMENTATIONS = ToolRegistry()
class ToolArgs(BaseModel):
    # injected tool argument. set in the code, not by the LLM.
    # LLM can't set this field because it's not added to the tool schema shown to LLM.
    # `inputs` is used to pass execution context from Supreme Agent to the tool.
    inputs: Annotated[dict, InjectedToolArg] = Field()
ToolConfigType = TypeVar('ToolConfigType', bound=BaseToolConfig)
class StatGptTool(BaseTool, ABC, Generic[ToolConfigType]):
    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    tool_type: ToolTypes  # Set dynamically in __init_subclass__
    def __init_subclass__(cls, **kwargs):
        tool_type = kwargs.pop('tool_type', None)
        super().__init_subclass__(**kwargs)
        if StatGptTool in cls.__bases__:
            # we want to register tool instance (like DataQueryTool),
            # not generic itself (like StatGptTool[DataQueryToolConfig])
            return
        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must specify a 'tool_type' parameter")
        if not isinstance(tool_type, ToolTypes):
            raise ValueError(f"{tool_type=} must be an instance of {ToolTypes}")
        cls.tool_type = tool_type
        _TOOL_IMPLEMENTATIONS[tool_type] = cls
    def __init__(self, tool_config: ToolConfigType, channel_config: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._tool_config = tool_config
        self._channel_config = channel_config
    @property
    def stage_name(self) -> str:
        """Return the stage name of calling this tool."""
        if name := self._tool_config.details.stages_config.tool_call_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Calling {tool_name} tool"
    @property
    def result_stage_name(self) -> str:
        """Return the stage name of showing the result of this tool."""
        if name := self._tool_config.details.stages_config.tool_result_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Result from {tool_name} tool"
    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """This method is implemented to satisfy the BaseTool interface.
        But it raises an error since we don't want to use it."""
        raise NotImplementedError("This method should not be called. Use async version instead.")
    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass
    @classmethod
    def get_args_schema(cls, tool_config: ToolConfigType) -> type[ToolArgs]:
        """Return the schema for the arguments that this tool accepts."""
        return ToolArgs
    @staticmethod
    def from_config(tool_config: ToolConfigType, channel_config: ChannelConfig) -> 'StatGptTool':
        cls = _TOOL_IMPLEMENTATIONS[tool_config.type]
        return cls(
            tool_config=tool_config,
            channel_config=channel_config,
            name=tool_config.name,
            description=tool_config.description,
            args_schema=cls.get_args_schema(tool_config),
        )

import re
from pathlib import Path
from typing import Any, Dict, Optional, Tuple
import yaml
class SkillLoader:
    """Load and parse SKILL.md files."""
    FRONTMATTER_PATTERN = re.compile(r"^---\s*\n(.*?)\n---\s*\n(.*)$", re.DOTALL)
    @classmethod
    def load(cls, path: str) -> Dict[str, Any]:
        """Load Skill from file and return as dict."""
        file_path = Path(path)
        if not file_path.exists():
            raise FileNotFoundError(f"Skill file not found: {path}")
        content = file_path.read_text(encoding="utf-8")
        return cls.parse(content, source_path=str(file_path))
    @classmethod
    def parse(cls, content: str, source_path: str = "") -> Dict[str, Any]:
        """Parse SKILL.md content and return as dict."""
        frontmatter, body = cls._split_frontmatter(content)
        if not frontmatter:
            raise ValueError("SKILL.md must have YAML frontmatter")
        meta = yaml.safe_load(frontmatter)
        if not isinstance(meta, dict):
            raise ValueError("Invalid YAML frontmatter")
        if "name" not in meta:
            raise ValueError("Skill must have 'name' field")
        if "description" not in meta:
            raise ValueError("Skill must have 'description' field")
        return {
            "name": meta["name"],
            "description": meta["description"],
            "content": body.strip(),
            "source_path": source_path,
            "allowed_tools": meta.get("allowed-tools", []),
            "tags": meta.get("tags", []),
        }
    @classmethod
    def _split_frontmatter(cls, content: str) -> Tuple[Optional[str], str]:
        """Split frontmatter and body."""
        match = cls.FRONTMATTER_PATTERN.match(content)
        if match:
            return match.group(1), match.group(2)
        return None, content
    @classmethod
    def to_skill_md(cls, skill_dict: Dict[str, Any]) -> str:
        """Convert skill dict to SKILL.md format."""
        frontmatter: dict = {
            "name": skill_dict["name"],
            "description": skill_dict.get("description", ""),
        }
        yaml_str = yaml.dump(frontmatter, allow_unicode=True, sort_keys=False)
        return f"---\n{yaml_str}---\n\n{skill_dict.get('content', '')}"

import sys
import json
import argparse
import requests
import subprocess
import os
from datetime import datetime
API_KEY = os.environ.get("LEETIFY_API_KEY")
if not API_KEY:
    print(json.dumps({"error": "LEETIFY_API_KEY environment variable not set"}))
    sys.exit(1)
API_BASE = "https://api-public.cs-prod.leetify.com"
def api_request(endpoint, params=None):
    headers = {"Authorization": f"Bearer {API_KEY}"}
    url = f"{API_BASE}{endpoint}"
    try:
        response = requests.get(url, params=params, headers=headers)
        if response.status_code == 200:
            return {"success": True, "data": response.json()}
        else:
            return {"success": False, "error": f"{response.status_code} {response.text}"}
    except Exception as e:
        return {"success": False, "error": str(e)}
def get_match_full_stats(steam_id, match_index=0):
    # 1. Get recent matches list
    result = api_request('/v3/profile/matches', {'steam64_id': steam_id, 'limit': match_index + 1})

    if not result['success']:
        print(json.dumps({"error": result.get('error')}))
        return
    matches = result['data']
    # Handle direct list response or wrapped response
    if isinstance(matches, dict) and 'matches' in matches:
        matches = matches['matches']

    if not isinstance(matches, list):
        print(json.dumps({"error": "Unexpected API response format"}))
        return
    if len(matches) <= match_index:
        print(json.dumps({"error": f"Match index {match_index} not found. Total matches: {len(matches)}"}))
        return
    match = matches[match_index]

    # 2. Extract specific player stats
    # The 'stats' array in the match object contains detailed stats for each player in that match
    player_stats = next((s for s in match.get('stats', []) if s['steam64_id'] == steam_id), None)

    if not player_stats:
        print(json.dumps({"error": "Player stats not found in this match"}))
        return
    # 3. Construct the Analysis Payload
    # We combine match metadata (map, score) with the full player stats object

    analysis_payload = {
        "meta": {
            "map": match.get('map_name'),
            "date": match.get('finished_at'),
            "team_scores": match.get('team_scores'),
            "data_source": match.get('data_source'),
            "match_id": match.get('id')
        },
        # This object contains: accuracy, sprays, counter-strafing, utility usage, 
        # trade stats, entry stats, clutch opportunities, etc.
        "stats": player_stats 
    }
    # Output JSON for the LLM to digest
    print(json.dumps(analysis_payload, indent=2, ensure_ascii=False))
if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--username", required=True)
    parser.add_argument("--index", type=int, default=0)
    args = parser.parse_args()

    script_dir = os.path.dirname(os.path.abspath(__file__))
    try:
        # Resolve username to Steam ID
        res = subprocess.check_output(
            ['python3', os.path.join(script_dir, 'steam_ids.py'), 'get', '--username', args.username],
            text=True
        ).strip()

        if "No Steam ID" in res or not res:
            print(json.dumps({"error": f"Steam ID not found for {args.username}"}))
            sys.exit(1)
        steam_id = res
    except Exception as e:
        print(json.dumps({"error": f"Steam ID resolution failed: {str(e)}"}))
        sys.exit(1)

    get_match_full_stats(steam_id, args.index)

