from __future__ import annotations
from fpdf import FPDF
# Layout constants
FALLBACK_VERTICAL_PADDING_MM = 0.0
# Tolerance for coordinate comparisons (same row/column detection)
COORDINATE_EPSILON = 0.01
def calc_cells(usable: float, cell: float, gap: float, max_cells: int | None) -> int:
    count = int((usable + gap) // (cell + gap))
    if max_cells is not None:
        return min(count, int(max_cells))
    return count
def expand_gap_to_fill(usable_w: float, cell_w: float, gap: float, cols: int) -> float:
    if cols <= 1:
        return gap
    gaps = cols - 1
    content_w = cols * cell_w + gaps * gap
    extra = usable_w - content_w
    if extra <= 0:
        return gap
    return gap + (extra / gaps)
def adjust_rows_for_fallback(
    rows: int,
    grid_start_y: float,
    page_h: float,
    margin: float,
    qr_size: float,
    gap: float,
    line_height: float,
    min_lines: int,
) -> int:
    while rows > 0:
        grid_height = rows * qr_size + (rows - 1) * gap
        leftover = page_h - grid_start_y - grid_height - margin
        safe_leftover = max(0.0, leftover - FALLBACK_VERTICAL_PADDING_MM)
        lines = int(safe_leftover // line_height)
        if lines >= min_lines:
            return rows
        rows -= 1
    raise ValueError("page too small for fallback text")
def fallback_lines_per_page(
    rows: int,
    grid_start_y: float,
    page_h: float,
    margin: float,
    qr_size: float,
    gap: float,
    line_height: float,
) -> int:
    grid_height = rows * qr_size + (rows - 1) * gap
    leftover = page_h - grid_start_y - grid_height - margin
    safe_leftover = max(0.0, leftover - FALLBACK_VERTICAL_PADDING_MM)
    return max(1, int(safe_leftover // line_height))
def fallback_lines_per_page_text_only(
    content_start_y: float,
    page_h: float,
    margin: float,
    line_height: float,
) -> int:
    leftover = page_h - content_start_y - margin
    safe_leftover = max(0.0, leftover - FALLBACK_VERTICAL_PADDING_MM)
    return max(1, int(safe_leftover // line_height))
def max_groups_for_width(pdf: FPDF, group_size: int, width_mm: float) -> int:
    group_width = pdf.get_string_width("M" * group_size)
    space_width = pdf.get_string_width(" ")
    if group_width <= 0:
        return 1
    if width_mm <= group_width:
        return 1
    return max(1, int((width_mm + space_width) // (group_width + space_width)))
def groups_from_line_length(line_length: int, group_size: int) -> int:
    if line_length <= group_size:
        return 1
    return max(1, (line_length + 1) // (group_size + 1))
def line_length_from_groups(groups: int, group_size: int) -> int:
    return max(group_size, groups * (group_size + 1) - 1)

import json
from dataclasses import asdict, dataclass
from typing import Any, Dict, List, Union
from uuid import uuid4
@dataclass
class EmbeddingMsg:
    message: Union[str, List[Dict[str, Any]]]
    context_data: Dict[str, Any]
    def __init__(self, message: Union[str, List[Dict[str, Any]]], context_data: Dict[str, Any]):
        self.id = str(uuid4())
        self.message = message
        self.context_data = context_data
    def to_dict(self) -> Dict[str, Any]:
        """Convert embedding message to dictionary format."""
        return asdict(self)
    def to_json(self) -> str:
        """Convert embedding message to JSON string."""
        return json.dumps(self.to_dict())
    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "EmbeddingMsg":
        """Create an embedding message object from dictionary."""
        obj = EmbeddingMsg(
            message=data["message"],
            context_data=data["context_data"],
        )
        obj.id = data.get("id", obj.id)
        return obj
    @classmethod
    def from_json(cls, json_str: str) -> "EmbeddingMsg":
        """Safely create object from JSON string."""
        try:
            data = json.loads(json_str)
            return cls.from_dict(data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")

from pathlib import Path
import click
from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build
TOKEN_FILE = Path.home() / ".simple-google-workspace" / "token.json"
def get_service():
    if not TOKEN_FILE.exists():
        raise click.ClickException("Not authenticated. Run: uv run scripts/auth.py login")
    creds = Credentials.from_authorized_user_file(TOKEN_FILE)
    return build("slides", "v1", credentials=creds)
def get_drive_service():
    creds = Credentials.from_authorized_user_file(TOKEN_FILE)
    return build("drive", "v3", credentials=creds)
@click.group()
def cli():
    """Google Slides commands."""
@cli.command()
@click.argument("query")
def find(query: str):
    """Find presentations by name."""
    drive = get_drive_service()
    results = drive.files().list(
        q=f"name contains '{query}' and mimeType = 'application/vnd.google-apps.presentation'",
        fields="files(id,name)",
    ).execute()
    files = results.get("files", [])
    if not files:
        click.echo("No presentations found.")
        return
    for f in files:
        click.echo(f"[{f['id']}] {f['name']}")
@cli.command()
@click.argument("presentation_id")
def get(presentation_id: str):
    """Get presentation metadata and slide titles."""
    service = get_service()
    presentation = service.presentations().get(presentationId=presentation_id).execute()
    click.echo(f"Title: {presentation.get('title')}")
    click.echo(f"Slides: {len(presentation.get('slides', []))}")
    click.echo("---")
    for i, slide in enumerate(presentation.get("slides", []), 1):
        # Try to get slide title from shapes
        title = "(No title)"
        for element in slide.get("pageElements", []):
            if "shape" in element:
                shape = element["shape"]
                if shape.get("placeholder", {}).get("type") == "TITLE":
                    text_elements = shape.get("text", {}).get("textElements", [])
                    for te in text_elements:
                        if "textRun" in te:
                            title = te["textRun"].get("content", "").strip()
                            break
        click.echo(f"Slide {i}: {title}")
@cli.command()
@click.argument("presentation_id")
def text(presentation_id: str):
    """Extract all text from presentation."""
    service = get_service()
    presentation = service.presentations().get(presentationId=presentation_id).execute()
    click.echo(f"# {presentation.get('title')}\n")
    for i, slide in enumerate(presentation.get("slides", []), 1):
        click.echo(f"## Slide {i}")
        for element in slide.get("pageElements", []):
            if "shape" in element and "text" in element.get("shape", {}):
                for te in element["shape"]["text"].get("textElements", []):
                    if "textRun" in te:
                        content = te["textRun"].get("content", "").strip()
                        if content:
                            click.echo(content)
        click.echo()
@cli.command()
@click.argument("title")
def create(title: str):
    """Create a new presentation."""
    service = get_service()
    presentation = service.presentations().create(body={"title": title}).execute()
    click.echo(f"Created: {presentation.get('title')}")
    click.echo(f"ID: {presentation.get('presentationId')}")
    click.echo(f"Link: https://docs.google.com/presentation/d/{presentation.get('presentationId')}")
if __name__ == "__main__":
    cli()

