# State definitions
class State:
    CONNECTION_WORKING = "CONNECTION_WORKING"


class StateMachineTick:
    def __init__(self, start_state=None, transition=None, end_state=None, is_terminal=None):
        self.start_state = start_state
        self.transition = transition
        self.end_state = end_state
        self.is_terminal = is_terminal

    # Check if all required fields are present
    def is_complete(self):
        return all([self.start_state, self.transition, self.end_state, self.is_terminal])

    # Check if start and end states are the same (steady state)
    def is_steady(self):
        return self.start_state == self.end_state

    # Factory method to create a completed tick
    @classmethod
    def create_completed(cls, start_state, transition, end_state, is_terminal):
        return cls(start_state, transition, end_state, is_terminal)


