# Import necessary modules
import shutil
from pathlib import Path

def copy_folder_to_folder(src: Path, dst: Path, overwrite=False):
    # Ignore compiled Python files and cache directories
    ignore_pyc = shutil.ignore_patterns("*.pyc", "__pycache__")

    # Check if source folder exists and is a directory
    if src.exists() and src.is_dir():
        # Check if destination folder exists and is a directory
        if dst.exists() and dst.is_dir():
            # Iterate through items in source directory
            for item in src.iterdir():
                # Handle files
                if item.is_file():
                    if overwrite or not (dst / item.name).exists():
                        shutil.copy2(item, dst)
                # Handle subdirectories recursively
                elif item.is_dir():
                    new_dst = dst / item.name
                    new_dst.mkdir(exist_ok=True)
                    copy_folder_to_folder(item, new_dst, overwrite)
        else:
            raise ValueError("Destination folder does not exist or is not a directory")
    else:
        raise ValueError("Source folder does not exist or is not a directory")

