import numpy as np
import pandas as pd

def get_all_distances(df):
    # Check if input is a pandas DataFrame
    if not isinstance(df, pd.DataFrame):
        raise TypeError("Input must be a pandas DataFrame")

    # Handle empty or single-row DataFrames
    if df.empty or len(df) == 1:
        return np.array([])

    # Verify all columns are numeric
    if not all(df.dtypes.apply(pd.api.types.is_numeric_dtype)):
        raise ValueError("DataFrame contains non-numeric values")

    # Initialize variables
    num_points = len(df)
    num_features = len(df.columns)
    distances = np.zeros((num_points, num_points))

    # Compute pairwise distances
    for i in range(num_points):
        for j in range(i, num_points):
            if i == j:
                distances[i, j] = 0
            else:
                point1 = df.iloc[i].values
                point2 = df.iloc[j].values
                distances[i, j] = np.linalg.norm(point1 - point2)
                distances[j, i] = distances[i, j]

    return distances

