# Detects deadlock using the Banker's algorithm
def detect_deadlock(allocated, max_demand, available):
    # Number of processes
    n = len(allocated)
    # Number of resource types
    m = len(available)

    # Initialize work and finish arrays
    work = available[:]
    finish = [False] * n

    # Find a process that can be executed
    while True:
        found = False

        for i in range(n):
            # Check if process i can be completed
            if not finish[i] and all(
                need <= work[j] 
                for j, need in enumerate(max_demand[i])
            ):
                # Process can be executed
                found = True
                finish[i] = True
                # Release resources of process i
                work = [
                    work[j] + allocated[i][j] 
                    for j in range(m)
                ]
                break

        if not found:
            break

    # Return True if all processes can complete (no deadlock)
    return all(finish)

