# Function to create JSON schema conditionals
def create_json_schema_conditionals(scheduler_types: dict) -> dict:
    # Initialize conditional properties dictionary
    conditional_properties = {}

    # Iterate through scheduler types and build conditionals
    for scheduler_type, schema_name in scheduler_types.items():
        conditional_properties["if"] = {"properties": {"schedulerType": {"const": scheduler_type.value}}}
        conditional_properties["then"] = {"required": [schema_name]}
        conditional_properties["else"] = {"required": []}

    # Return the final conditional structure
    return {
        "if": {
            "properties": {
                "schedulerType": {
                    "enum": [st.value for st in SchedulerType]
                }
            }
        },
        "then": {
            "properties": {
                schema_name: {
                    "type": "object"
                }
            }
        },
        "else": {}
    }

