# Solution class for checking if a binary tree is symmetric
class Solution:
    def isSymmetric(self, root: TreeNode) -> bool:
        # Helper function to check if two subtrees are mirrors of each other
        def isMirror(left: TreeNode, right: TreeNode) -> bool:
            # Both nodes are None - symmetric
            if not left and not right:
                return True
            # One node is None but not the other - not symmetric
            if not left or not right:
                return False
            # Check values and recursively check subtrees in mirror fashion
            return (left.val == right.val) and \
                   isMirror(left.left, right.right) and \
                   isMirror(left.right, right.left)

        # Empty tree is symmetric
        if not root:
            return True
        # Check if left and right subtrees are mirrors
        return isMirror(root.left, root.right)

