# Import required modules for decimal precision
from decimal import Decimal, getcontext

# Setup the decimal context with given precision
def setup_decimal_context(context):
    context.prec = 7

# Calculate pi using a series expansion
def calculate_pi():
    # Set high precision for accurate calculation
    getcontext().prec = 50

    one = Decimal(1)
    pi = Decimal(0)
    k = 0

    while True:
        # Compute each term in the series
        term = (one / 16 ** k) * (
            (four(1, k) - two(4, k) - one(5, k) - one(6, k))
        )

        # Break if term becomes zero
        if term == 0:
            break

        pi += term
        k += 1

    return +pi

# Helper functions for series terms
def one(j, k):
    return Decimal(4 / (8 * k + j))

def two(j, k):
    return Decimal(2 / (8 * k + j))

def four(j, k):
    return Decimal(1 / (8 * k + j))

