import os

def filter_and_sort_files(folder, prefix=None, suffix=None, sort=False):
    # Define filter condition based on provided parameters
    if prefix is not None and suffix is not None:
        filter_condition = lambda i: i.startswith(prefix) and i.endswith(suffix)
    elif prefix is not None:
        filter_condition = lambda i: i.startswith(prefix)
    elif suffix is not None:
        filter_condition = lambda i: i.endswith(suffix)
    else:
        filter_condition = lambda i: True

    # Filter files in the folder that match the condition
    file_list = [
        i 
        for i in os.listdir(folder) 
        if os.path.isfile(os.path.join(folder, i)) and filter_condition(i)
    ]

    # Sort if requested
    if sort:
        file_list.sort()

    return file_list

import socket

def initialize_server_socket(client_update_port: int) -> str:
    try:
        # Create UDP socket
        update_sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)

        try:
            # Allow socket reuse
            update_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        except:
            pass

        try:
            # Bind to all interfaces on specified port
            update_sock.bind(('0.0.0.0', client_update_port))
            return f"Server initialized and bound to port {client_update_port}"
        except:
            return f"Error: Unable to bind to port {client_update_port} - server initialization failed"

    except Exception as e:
        return f"Error: {e}"

