import re

# Custom exception for duplicate function binding
class FunctionAlreadyBoundError(Exception):
    pass

# Custom exception for malformed SQL queries
class MalformedQueryError(Exception):
    pass

def validate_binding(decorators):
    # Dictionary to track bound functions
    bound_functions = {}

    # Regex pattern for valid SQL statements
    sql_pattern = r'^\s*(SELECT|UPDATE|INSERT|DELETE)\s+.+'

    # Iterate through all decorator-SQL pairs
    for decorator, sql_statement in decorators:
        # Check if function is already bound
        if decorator in bound_functions:
            raise FunctionAlreadyBoundError(
                f"Function '{decorator.__name__}' is already bound to a SQL statement"
            )

        # Validate SQL statement format
        if not re.match(sql_pattern, sql_statement):
            raise MalformedQueryError(
                f"The SQL statement '{sql_statement}' is incorrectly formatted"
            )

        # Record the binding
        bound_functions[decorator] = sql_statement

    # Return success message
    return "All bindings are valid"

