# Import torch library
import torch

def custom_mean(tensor, dim=None, keepdim=False):
    # Handle case when no dimension specified
    if dim is None:
        # Compute mean over all dimensions
        return torch.mean(tensor)
    else:
        # Convert single integer dimension to list
        if isinstance(dim, int):
            dim = [dim]
        # Sort dimensions in ascending order
        dim = sorted(dim)

        # Apply mean sequentially for each dimension
        for d in dim:
            tensor = tensor.mean(dim=d, keepdim=True)

        # Remove squeezed dimensions if needed
        if not keepdim:
            for i, d in enumerate(dim):
                tensor.squeeze_(d - i)

        return tensor

