from datetime import datetime
from zipfile import ZipFile, ZIP_DEFLATED
from io import BytesIO

def generate_and_extract_zip(num_files, content):
    # Set a fixed timestamp and permissions
    now = datetime.fromisoformat('2021-01-01 21:01:12')
    perms = 0o600

    # Generator function to yield file information
    def files():
        for i in range(num_files):
            yield f'file-{i}', now, perms, ZIP_DEFLATED, content

    # Function to extract and print zip contents (not used in return value)
    def extracted():
        with ZipFile(BytesIO(b''.join(stream_zip(files())))) as my_zip:
            for my_info in my_zip.infolist():
                with my_zip.open(my_info.filename) as my_file:
                    print(f"Filename: {my_info.filename}, Last Modified: {my_info.date_time}, Permissions: {my_info.external_attr}")

    # Return the zip file bytes
    return BytesIO(b''.join(stream_zip(files()))).getvalue()

# Helper function to simulate stream_zip
def stream_zip(file_info):
    with ZipFile(BytesIO(), 'w') as my_zip:
        for info in file_info():
            my_zip.writestr(*info)
        return my_zip.fp

