# Generic Stack implementation using linked list
from typing import Type

class Node:
    def __init__(self, data: Type) -> None:
        self.data = data
        self.next = None

class GenericStack:
    def __init__(self) -> None:
        self.top = None
        self.size = 0

    def is_empty(self) -> bool:
        return self.size == 0

    def push(self, data: Type) -> None:
        new_node = Node(data)
        new_node.next = self.top
        self.top = new_node
        self.size += 1

    def pop(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")

        data = self.top.data
        self.top = self.top.next
        self.size -= 1

        return data

    def peek(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")

        return self.top.data

    def get_size(self) -> int:
        return self.size

