from pint import UnitRegistry

# Define Float class
class Float:
    def __init__(self, setter=False, values=None, unit=None, mapping=None):
        self.setter = setter
        self.values = values if values else []
        self.unit = unit
        self.mapping = mapping if mapping else {}

    def pre_set(self, _, value):
        if self.setter:
            if self.unit:
                return self.convert_to_unit(value)
            return value
        else:
            raise ValueError("Setter is not enabled")

    def post_get(self, _, value):
        if self.mapping:
            return self.mapping.get(value, None)
        return value

    def convert_to_unit(self, value):
        if self.unit:
            ureg = UnitRegistry()
            return ureg(value).to(self.unit).magnitude
        return value


