# Calculates cumulative min/max comparison
def cum_min_max_compare(op, x, cummax_output, axis, data_type):
    result = [[0 for _ in range(len(x[0]))] for _ in range(len(x))]

    if op == "min":
        for i in range(len(x)):
            for j in range(len(x[0])):
                min_val = float('inf')
                for k in range(len(x[0][0])):
                    if data_type == "int32":
                        min_val = min(min_val, x[i][j][k])
                    elif data_type == "int64":
                        min_val = min(min_val, x[i][j][k])
                result[i][j] = min_val

    elif op == "max":
        for i in range(len(x)):
            for j in range(len(x[0])):
                max_val = float('-inf')
                for k in range(len(x[0][0])):
                    if data_type == "int32":
                        max_val = max(max_val, x[i][j][k])
                    elif data_type == "int64":
                        max_val = max(max_val, x[i][j][k])
                result[i][j] = max_val

    return result


