# Import necessary types and ABC
from typing import Iterator, Dict, Any, List, Tuple
from abc import ABC, abstractmethod


class AbstractRow(ABC):
    """Abstract base class for rows."""
    pass


class JoinedRow(AbstractRow):
    """Represents a joined row from left and right tables."""

    def __init__(self, left: Dict[str, Any], right: Dict[str, Any], _id: int):
        self.left = left
        self.right = right
        self._id = _id


class RightJoin(LeftJoin):
    """Implements right join logic."""

    def _produce(self) -> Iterator[AbstractRow]:
        # Iterate over grouped right rows and their joined candidates
        for right_row, joined_rows in self.grouped:
            matched = False

            # Check each candidate joined row
            for joined_row in joined_rows:
                left_row = joined_row.left

                # If predicate matches, yield joined row
                if self.predicate(left_row, right_row):
                    matched = True
                    yield JoinedRow(left_row, right_row, _id=-1)

            # If no match found, yield null-padded row for left side
            if not matched:
                yield JoinedRow(dict.fromkeys(left_row), right_row, _id=-1)

