def generate_date_query(start_date: str = None, end_date: str = None, date: str = None) -> dict:
    # Handle case with start and end dates
    if start_date and end_date:
        start_date_obj = datetime.strptime(start_date, "%d/%m/%Y")
        end_date_obj = datetime.strptime(end_date, "%d/%m/%Y")

        # Validate date order
        assert (start_date_obj < end_date_obj), "The first date must be lower than the second."

        return {POST_PUB_DATE: {
            "$gte": start_date_obj,
            "$lt": end_date_obj
        }}

    # Handle case with single date
    elif date:
        post_pub_date = datetime.strptime(date, "%d/%m/%Y")
        return {POST_PUB_DATE: post_pub_date}

    # Error handling for missing arguments
    else:
        raise ValueError("At least one of start_date, end_date, or date must be provided.")

# Type checking decorator implementation
from functools import wraps
from inspect import signature, _empty
from typing import Any, Callable, Type, Union

def type_check(_check_input_type=True, _check_return_type=True):
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            # Check input types if enabled
            if _check_input_type:
                sig = signature(func)
                bound_args = sig.bind(*args, **kwargs)

                for param_name, param_value in bound_args.arguments.items():
                    param_type = sig.parameters[param_name].annotation

                    # Skip parameters without type annotations
                    if param_type != _empty and not isinstance(param_value, param_type):
                        raise TypeError(
                            f"Invalid type for argument '{param_name}'. "
                            f"Expected {param_type}, but received {type(param_value)}"
                        )

            # Execute the original function
            result = func(*args, **kwargs)

            # Check return type if enabled
            if _check_return_type:
                return_type = sig.return_annotation

                # Skip if no return type annotation or if type matches
                if return_type != _empty and not isinstance(result, return_type):
                    raise TypeError(
                        f"Invalid return type. Expected {return_type}, "
                        f"but received {type(result)}"
                    )

            return result

        return wrapper

    return decorator

