from typing import List
from sqlite3 import Connection, Cursor

def close_and_commit(cursors: List[Cursor], conn: Connection) -> None:
    try:
        # Close all cursors
        for cursor in cursors:
            cursor.close()

        # Commit the connection
        conn.commit()

    except Exception as e:
        # Handle any exceptions that may occur during cursor closing or committing
        print(f"An error occurred: {e}")

