class FileEditTool(Tool):
    # Define tool name and description
    name = "file_edit"
    description = (
        "Edit a file by replacing an exact string match with new content. "
        "The old_string must match exactly (including whitespace/indentation). "
        "Provide enough context in old_string to make it unique in the file."
    )

    # Define parameters schema
    parameters = {
        "type": "object",
        "properties": {
            "path": {
                "type": "string",
                "description": "The file path to edit.",
            },
            "old_string": {
                "type": "string",
                "description": "The exact string to find and replace. Must be unique in the file.",
            },
            "new_string": {
                "type": "string",
                "description": "The replacement string.",
            },
        },
        "required": ["path", "old_string", "new_string"],
    }

    # Execute method for asynchronous operation
    async def execute(self, arguments: Dict) -> str:
        # Extract arguments
        path = arguments["path"]
        old_string = arguments["old_string"]
        new_string = arguments["new_string"]

        try:
            # Read file content
            content = await self.run_cmd(cmd=["cat", path])
        except Exception as e:
            return f"Error reading file: {e}"

        # Check if strings are identical
        if old_string == new_string:
            return "Error: old_string and new_string are identical."

        # Count occurrences of old_string
        count = content.count(old_string)

        # Handle cases where old_string is not found or appears multiple times
        if count == 0:
            return "Error: old_string not found in file."
        if count > 1:
            return f"Error: old_string matches {count} locations. Provide more context to make it unique."

        # Perform replacement
        new_content = content.replace(old_string, new_string, 1)

        try:
            # Write updated content back to file
            await self.run_cmd(cmd=["tee", path], stdin=new_content)
            return f"Successfully edited {path}"
        except Exception as e:
            return f"Error writing file: {e}"

