import json
from . import xtbson as bson

def read_from_bson_buffer(buffer):
    # Initialize result list and position pointer
    result = []
    pos = 0

    while 1:
        # Check if there's enough data to read length header
        if pos + 4 < len(buffer):
            dlen_buf = buffer[pos : pos + 4]
        else:
            break

        # Extract data length from buffer
        dlen = ct.cast(dlen_buf, ct.POINTER(ct.c_int32))[0]

        # Process if data length is valid
        if dlen >= 5:
            try:
                data_buf = buffer[pos : pos + dlen]
                pos += dlen
                result.append(bson.decode(data_buf))
            except Exception as e:
                # Skip invalid entries silently
                pass
        else:
            break

    return result

def write_to_bson_buffer(data_list):
    # Encode list of data items into BSON buffer
    buffer = b''
    for data in data_list:
        buffer += bson.encode(data)
    return buffer

