# Imports for enum, torch, and vLLM components
from enum import Enum
import torch
from vllm.config import ParallelConfig
from vllm.logger import logger

# Import backend-related modules
from vllm_ascend.distributed.kv_transfer.kv_pool.ascend_store.backend.backend import Backend
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type


class MmcDirect(Enum):
    """Enumeration for memory copy directions."""
    COPY_L2G = 0  # Local to Global
    COPY_G2L = 1  # Global to Local
    COPY_G2H = 2  # Global to Host
    COPY_H2G = 3  # Host to Global


class MemcacheBackend(Backend):
    """
    Memcache-based backend implementation for distributed KV storage.
    Supports both A2 and other Ascend devices.
    """

    def __init__(self, parallel_config: ParallelConfig):
        # Attempt to import memcache_hybrid module
        try:
            from memcache_hybrid import DistributedObjectStore  # type: ignore
        except ImportError as e:
            raise ImportError(
                "Please install memcache by following the instructions at "
                "https://gitee.com/ascend/memfabric_hybrid "  # noqa: E501
                "to run vLLM with MemcacheConnector."
            ) from e

        # Initialize store based on device type
        try:
            soc_version = get_ascend_device_type()
            if soc_version in {AscendDeviceType.A2}:
                # Special handling for A2: synchronize ranks via all_gather
                import torch
                from vllm.distributed import get_world_group

                tmp_tensor = torch.zeros(1, device="npu")
                world_size = torch.distributed.get_world_size()
                output_tensor_list = [torch.empty_like(tmp_tensor) for _ in range(world_size)]
                torch.distributed.all_gather(
                    output_tensor_list,
                    tmp_tensor,
                    group=get_world_group().device_group
                )

                self.rank = parallel_config.rank
                self.store = DistributedObjectStore()
                res = self.store.init(self.rank)
                assert res == 0, f"Failed to initialize store: error code {res}"
            else:
                # Generic path for other Ascend devices
                self.rank = parallel_config.rank
                self.store = DistributedObjectStore()
                res = self.store.init(self.rank)
                assert res == 0, f"Failed to initialize store: error code {res}"

        except ValueError as e:
            logger.error("Configuration loading failed: %s", e)
            raise
        except Exception as exc:
            logger.error("An error occurred while loading the configuration: %s", exc)
            raise

    def set_device(self):
        """Set the current NPU device based on rank."""
        device = torch.device(f"npu:{self.rank}")
        torch.npu.set_device(device)

    def register_buffer(self, ptrs: list[int], sizes: list[int]):
        """Register buffers with the memcache store."""
        soc_version = get_ascend_device_type()
        if soc_version in {AscendDeviceType.A2}:
            for ptr, size in zip(ptrs, sizes):
                self.store.register_buffer(ptr, size)
        # No-op for non-A2 devices
        else:
            pass

    def exists(self, keys: list[str]) -> list[int]:
        """Check existence of keys in the store."""
        return self.store.batch_is_exist(keys)

    def get(self, key: list[str], addr: list[list[int]], size: list[list[int]]):
        """Retrieve data from the store into local addresses."""
        try:
            res = self.store.batch_get_into_layers(key, addr, size, MmcDirect.COPY_G2L.value)
            for value in res:
                if value != 0:
                    logger.error(f"Failed to get key {key}, res: {res}")
        except Exception as e:
            logger.error(f"Failed to get key {key}. {e}")

    def put(self, key: list[str], addr: list[list[int]], size: list[list[int]]):
        """Store data from local addresses into the store."""
        try:
            res = self.store.batch_put_from_layers(key, addr, size, MmcDirect.COPY_L2G.value)
            for value in res:
                if value != 0:
                    logger.error(f"Failed to put key {key}, res: {res}")
        except Exception as e:
            logger.error(f"Failed to put key {key}, error: {e}")

