# Timer utility module for tracking execution time
import logging
from contextlib import contextmanager
from functools import wraps
from time import time

import torch.distributed

from .misc import SingletonMeta

__all__ = ["Timer", "timer"]

logger = logging.getLogger(__name__)


class Timer(metaclass=SingletonMeta):
    def __init__(self):
        self.timers = {}
        self.start_time = {}

    def start(self, name):
        assert name not in self.start_time, f"Timer {name} already started."
        self.start_time[name] = time()
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            logger.info(f"Timer {name} start")

    def end(self, name):
        assert name in self.start_time, f"Timer {name} not started."
        elapsed_time = time() - self.start_time[name]
        self.add(name, elapsed_time)
        del self.start_time[name]
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            logger.info(f"Timer {name} end (elapsed: {elapsed_time:.1f}s)")

    def reset(self, name=None):
        if name is None:
            self.timers = {}
        elif name in self.timers:
            del self.timers[name]

    def add(self, name, elapsed_time):
        self.timers[name] = self.timers.get(name, 0) + elapsed_time

    def log_dict(self):
        return self.timers

    @contextmanager
    def context(self, name):
        self.start(name)
        try:
            yield
        finally:
            self.end(name)


def timer(name_or_func):
    """
    Can be used either as a decorator or a context manager:

    @timer
    def func():
        ...

    or

    with timer("block_name"):
        ...
    """
    # When used as a context manager
    if isinstance(name_or_func, str):
        name = name_or_func
        return Timer().context(name)

    func = name_or_func

    @wraps(func)
    def wrapper(*args, **kwargs):
        with Timer().context(func.__name__):
            return func(*args, **kwargs)

    return wrapper


@contextmanager
def inverse_timer(name):
    Timer().end(name)
    try:
        yield
    finally:
        Timer().start(name)

import logging
from typing import Any, Dict

from mirobody.pulse.file_parser.handlers.base import BaseFileHandler, FileProcessingContext


class ExcelHandler(BaseFileHandler):
    def __init__(self, excel_processor=None, **kwargs):
        super().__init__(**kwargs)
        self.excel_processor = excel_processor

    def get_type_name(self) -> str:
        return "excel"

    @staticmethod
    def is_excel_file(filename: str, content_type: str) -> bool:
        if not filename:
            return False

        excel_extensions = [".xlsx", ".xls", ".xlsm", ".xlsb"]
        filename_lower = filename.lower()
        has_excel_extension = any(
            filename_lower.endswith(ext) for ext in excel_extensions
        )

        excel_mime_types = [
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "application/vnd.ms-excel",
            "application/vnd.ms-excel.sheet.macroEnabled.12",
            "application/vnd.ms-excel.sheet.binary.macroEnabled.12",
        ]
        has_excel_mime = content_type in excel_mime_types

        return has_excel_extension or has_excel_mime

    async def process(self, ctx: FileProcessingContext) -> Dict[str, Any]:
        # ExcelProcessor takes control of the whole flow usually
        try:
            return await self.excel_processor.process_excel_file(
                file_content=await ctx.file.read(),
                filename=ctx.original_filename or ctx.file.filename,
                content_type=ctx.content_type,
                user_id=ctx.user_id,
                query_user_id=ctx.target_user_id,
                message_id=ctx.message_id,
                progress_callback=ctx.progress_callback,
            )
        except Exception as e:
            logging.error(
                f"Excel file processing failed: {ctx.filename}, error: {e}",
                stack_info=True,
            )
            return {
                "success": False,
                "message": f"Excel file processing failed: {str(e)}",
                "type": "excel",
            }

    async def _process_content(self, *args, **kwargs):
        pass

