def remove_none_from_dict(original: Mapping[str, Optional[Any]]) -> Dict[str, Any]:
    # Create a new dictionary to store non-None values
    new: Dict[str, Any] = {}

    # Iterate through the original dictionary items
    for key, value in original.items():
        # Only add key-value pairs where value is not None
        if value is not None:
            new[key] = value

    # Return the new dictionary without None values
    return new

