class State:
    CONNECTION_ACTIVE = "CONNECTION_ACTIVE"

class StateMachineStep:
    def __init__(self, initial_state=None, action=None, final_state=None, is_final=None):
        self.initial_state = initial_state
        self.action = action
        self.final_state = final_state
        self.is_final = is_final

    def is_full(self):
        return all([self.initial_state, self.action, self.final_state, self.is_final])

    def is_static(self):
        return self.initial_state == self.final_state

    @classmethod
    def generate_finished(cls, initial_state, action, final_state, is_final):
        return cls(initial_state, action, final_state, is_final)

