import shutil
from pathlib import Path

def transfer_directory(src_dir: Path, target_dir: Path, replace_existing=False):
    skip_compiled = shutil.ignore_patterns("*.pyc", "__pycache__")

    if src_dir.exists() and src_dir.is_dir():
        if target_dir.exists() and target_dir.is_dir():
            for element in src_dir.iterdir():
                if element.is_file():
                    if replace_existing or not (target_dir / element.name).exists():
                        shutil.copy2(element, target_dir)
                elif element.is_dir():
                    new_target = target_dir / element.name
                    new_target.mkdir(exist_ok=True)
                    transfer_directory(element, new_target, replace_existing)
        else:
            raise ValueError("Target directory does not exist or is not a directory")
    else:
        raise ValueError("Source directory does not exist or is not a directory")

# Calculate pairwise Euclidean distances for numeric DataFrame
import numpy as np
import pandas as pd

def compute_all_pairwise_distances(dataframe):
    # Validate input type
    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError("Input must be a pandas DataFrame")

    # Handle edge cases: empty or single-row DataFrames
    if dataframe.empty or len(dataframe) == 1:
        return np.array([])

    # Check all columns are numeric
    if not all(dataframe.dtypes.apply(pd.api.types.is_numeric_dtype)):
        raise ValueError("DataFrame contains non-numeric values")

    # Initialize distance matrix
    n_samples = len(dataframe)
    n_features = len(dataframe.columns)
    dist_matrix = np.zeros((n_samples, n_samples))

    # Compute symmetric distance matrix
    for idx_i in range(n_samples):
        for idx_j in range(idx_i, n_samples):
            if idx_i == idx_j:
                dist_matrix[idx_i, idx_j] = 0.0
            else:
                vec_i = dataframe.iloc[idx_i].values
                vec_j = dataframe.iloc[idx_j].values
                dist_val = np.linalg.norm(vec_i - vec_j)
                dist_matrix[idx_i, idx_j] = dist_val
                dist_matrix[idx_j, idx_i] = dist_val

    return dist_matrix

