    Verify that point vector has correct dimensionality matching DataFrame columns
    """
    test_df = pd.DataFrame({'X': [7, 8, 9], 'Y': [10, 11, 12]})

    # Test invalid first argument (should raise TypeError)
    try:
        compute_all_pairwise_distances([5, 6, 7, 8], test_df)
    except TypeError as error:
        assert str(error) == "Input must be a pandas DataFrame"
    else:
        assert False

    # Test non-numeric DataFrame (should raise ValueError)
    try:
        compute_all_pairwise_distances(test_df)
    except ValueError as error:
        assert str(error) == "DataFrame contains non-numeric values"
    else:
        assert False

