# Check if the system is in a safe state to avoid deadlock
def check_safe_state(process_allocations, process_max_requirements, available_resources):
    num_processes = len(process_allocations)  # Count of processes
    num_resource_types = len(available_resources)  # Count of resource types

    # Initialize working copy of available resources and completion status
    current_work = available_resources[:]
    completed = [False] * num_processes

    # Look for a process that can complete with current resources
    while True:
        progress_made = False
        for idx in range(num_processes):
            if not completed[idx] and all(req <= curr for req, curr in zip(process_max_requirements[idx], current_work)):
                # This process can complete
                progress_made = True
                completed[idx] = True
                current_work = [current_work[r] + process_allocations[idx][r] for r in range(num_resource_types)]
                break
        if not progress_made:
            break

    return all(completed)

# Check if tree t is a subtree of tree s
class Solution:
    def isSubtree(self, root_s: TreeNode, root_t: TreeNode) -> bool:
        def check_identical_trees(node1: TreeNode, node2: TreeNode) -> bool:
            if not node1 and not node2:
                return True
            if not node1 or not node2:
                return False
            return (node1.val == node2.val and 
                    check_identical_trees(node1.left, node2.left) and 
                    check_identical_trees(node1.right, node2.right))

        if not root_s:
            return False
        return (check_identical_trees(root_s, root_t) or 
                self.isSubtree(root_s.left, root_t) or 
                self.isSubtree(root_s.right, root_t))

