# Check if a binary tree is symmetric 
class Solution:
    def isSymmetric(self, root: TreeNode) -> bool:
        def checkMirror(node1: TreeNode, node2: TreeNode) -> bool:
            if not node1 and not node2:
                return True
            if not node1 or not node2:
                return False
            return (node1.val == node2.val) and checkMirror(node1.left, node2.right) and checkMirror(node1.right, node2.left)

        if not root:
            return True
        return checkMirror(root.left, root.right)

