def transform_pg_array(pg_array):
    """
    Transform a PostgreSQL array-string into a Python list.
    PostgreSQL versions prior to 9.0 used comma-separated strings for array data types. This function handles conversion of such strings to lists. If pg_array is not a string, it remains unchanged.
    """
    if not isinstance(pg_array, (str, unicode)):
        return pg_array
    # Handles only one-dimensional arrays
    return list(map(str.strip, pg_array.strip("{}").split(",")))

