# Calculate Pi using the Bailey–Borwein–Plouffe formula
from decimal import Decimal, getcontext

def configure_decimal_precision(context):
    context.prec = 7

def compute_pi_value():
    getcontext().prec = 50  # Increase precision for better accuracy
    unit = Decimal(1)
    pi_sum = Decimal(0)
    index = 0
    while True:
        contribution = (unit / 16 ** index) * (
            (value_one(1, index) - value_two(4, index) - value_one(5, index) - value_one(6, index))
        )
        if contribution == 0:
            break
        pi_sum += contribution
        index += 1
    return +pi_sum

def value_one(j, k):
    return Decimal(4 / (8 * k + j))

def value_two(j, k):
    return Decimal(2 / (8 * k + j))

def value_four(j, k):
    return Decimal(1 / (8 * k + j))

# Validate the implementation
configure_decimal_precision(getcontext())
print(compute_pi_value())  # Expected output: 3.141593

