# Encode specified keys in a dictionary using Base64 and return as JSON string
import json
from base64 import b64encode

def transform_and_serialize(data: dict, fields_to_encode: list) -> str:
    modified_data = data.copy()
    for field in fields_to_encode:
        if field in data:
            # Convert value to string, encode to bytes, then Base64 encode, finally decode to string
            encoded_value = b64encode(str(data[field]).encode('utf-8')).decode('utf-8')
            modified_data[field] = encoded_value
    return json.dumps(modified_data)

