# Generate and sort a list of random integers using selection sort
import random

def selection_sort(data, size):
    for i in range(size - 1):
        min_pos = i
        for k in range(i + 1, size):
            if data[k] < data[min_pos]:
                min_pos = k
        data[i], data[min_pos] = data[min_pos], data[i]

def display_array(data, length):
    for idx in range(length):
        print(data[idx], end=" ")
    print()

