# Function to filter and optionally sort files in a directory
import os

def get_filtered_files(directory, start=None, end=None, order=False):
    if start is not None and end is not None:
        condition = lambda filename: filename.startswith(start) and filename.endswith(end)
    elif start is not None:
        condition = lambda filename: filename.startswith(start)
    elif end is not None:
        condition = lambda filename: filename.endswith(end)
    else:
        condition = lambda filename: True

    files = [filename for filename in os.listdir(directory) 
             if os.path.isfile(os.path.join(directory, filename)) and condition(filename)]

    if order:
        files.sort()
    return files

