import socket

def setup_udp_socket(port_number: int) -> str:
    try:
        udp_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        try:
            udp_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        except:
            pass
        try:
            udp_socket.bind(('0.0.0.0', port_number))
            return f"UDP server set up and listening on port {port_number}"
        except:
            return f"Failed: Cannot bind to port {port_number} - socket initialization unsuccessful"
    except Exception as error:
        return f"Exception occurred: {error}"

