        response_headers['Content-Type'] = 'application/json'
        body_content = json.dumps(response_body)
    elif format_type == 'xml':
        response_headers['Content-Type'] = 'application/xml'
        root_element = ET.fromstring(response_body)
        body_content = ET.tostring(root_element, encoding='unicode')

    return (response_headers, body_content)

# A caching mechanism with optional timeout and custom key support
import time
import functools

class CacheManager:
    def __init__(self, expiry=None, exclude=None, hasher=None):
        self.expiry = expiry
        self.exclude = exclude if exclude else []
        self.hasher = hasher
        self.storage = {}

    def __call__(self, function):
        """Main decorator method.
        :arg function function: The function to be decorated.
        """
        @functools.wraps(function)
        def wrapper(*arguments, **keyword_args):
            """Handles caching logic for the wrapped function.
            """
            if self.exclude and arguments in self.exclude:
                return function(*arguments, **keyword_args)

            cache_identifier = arguments if not self.hasher else self.hasher(*arguments, **keyword_args)

            if cache_identifier in self.storage:
                cached_value, stored_time = self.storage[cache_identifier]
                if not self.expiry or time.time() - stored_time < self.expiry:
                    return cached_value

            computed_result = function(*arguments, **keyword_args)
            self.storage[cache_identifier] = (computed_result, time.time())
            return computed_result

        return wrapper

