# Program to find min, max, and average of user inputs
import sys

def process_input():
    minimum_value = float('inf')
    maximum_value = float('-inf')
    cumulative_sum = 0
    count = 0

    try:
        while True:
            user_input = input()
            # Check if input is a valid integer (positive or negative)
            if not user_input.isdigit() and not (user_input[0] == '-' and user_input[1:].isdigit()):
                break

            number = int(user_input)

            # Update min and max values
            if number < minimum_value:
                minimum_value = number
            if number > maximum_value:
                maximum_value = number

            cumulative_sum += number
            count += 1

        if count > 0:
            print("min: " + str(minimum_value))
            print("avg: " + str(cumulative_sum / count))
            print("max: " + str(maximum_value))
        else:
            print("No valid input provided")

    except EOFError:
        print("Error: Unexpected end of input")

if __name__ == "__main__":
    process_input()

# Custom collection class ensuring at least one element
from typing import TypeVar, List, Set, Dict, Union

_T = TypeVar("_T")
_U = TypeVar("_U")

class AtLeastOneList:
    def __init__(self, *items: _T) -> None:
        if not items:
            raise ValueError("AtLeastOneList must contain at least one item")
        self._elements = list(items)

    def __getitem__(self, position: int) -> _T:
        return self._elements[position]

    def __setitem__(self, position: int, new_value: _T) -> None:
        self._elements[position] = new_value

    def __delitem__(self, position: int) -> None:
        del self._elements[position]

    def __len__(self) -> int:
        return len(self._elements)

    def add(self, item: _T) -> None:
        self._elements.append(item)

    def add_all(self, more_items: List[_T]) -> None:
        self._elements.extend(more_items)

    def delete(self, item: _T) -> None:
        self._elements.remove(item)

    def as_set(self) -> Set[_T]:
        return set(self._elements)

    def as_dict(self) -> Dict[_T, _U]:
        if len(self._elements) % 2 != 0:
            raise ValueError("AtLeastOneDict must have an even number of elements")
        return dict(zip(self._elements[::2], self._elements[1::2]))

