import itertools
import requests
from typing import Iterator, Tuple

# Define a named tuple-like class for word-pronunciation pairs
class WordPronPair(Tuple[str, str]):
    pass

# Generator function to yield Chinese pronunciations from API response
def yield_cmn_pron(response: requests.Response, settings: str) -> Iterator[str]:
    try:
        data = response.json()
        pronunciation_list = data.get("pronunciations", [])
        for pronunciation in pronunciation_list:
            yield pronunciation
    except (requests.RequestException, ValueError, KeyError):
        yield "Error: Failed to retrieve pronunciation"

# Generator function that pairs a given word with its pronunciations
def generate_word_pronunciations(
    term: str, response: requests.Response, settings: str
) -> Iterator[WordPronPair]:
    repeated_words = itertools.repeat(term)
    prons = yield_cmn_pron(response, settings)
    yield from zip(repeated_words, prons)

# Convert cardinalities dictionary to string-keyed format
from typing import Mapping
from tensorflow_federated.python.core.impl.types import placements
import collections.abc

def transform_cardinalities_to_string_keys(
    cardinality_map: Mapping[placements.PlacementLiteral, int]) -> Mapping[str, int]:
  """Validates and converts the input cardinalities mapping to use string keys."""
  if not isinstance(cardinality_map, collections.abc.Mapping):
    raise TypeError('Input `cardinality_map` must be a `Mapping`. Received type: '
                    f'{type(cardinality_map)}.')

  result_dict = {}
  for location, count in cardinality_map.items():
    if not isinstance(location, placements.PlacementLiteral):
      raise TypeError('Keys in `cardinality_map` must be of type `placements.PlacementLiteral`.')
    result_dict[str(location)] = count
  return result_dict

