# Validate SQL bindings for functions
import re

class DuplicateBindingError(Exception):
    pass

class InvalidQueryFormatError(Exception):
    pass

def check_sql_bindings(bindings_list):
    registered_functions = {}
    sql_regex = r'^\s*(SELECT|UPDATE|INSERT|DELETE)\s+.+'

    for func_decorator, query_text in bindings_list:
        if func_decorator in registered_functions:
            raise DuplicateBindingError(f"Function '{func_decorator.__name__}' has already been associated with a SQL query")

        if not re.match(sql_regex, query_text):
            raise InvalidQueryFormatError(f"The SQL query '{query_text}' does not follow the correct syntax")

        registered_functions[func_decorator] = query_text

    return "All SQL bindings passed validation"

