# Custom implementation of mean operation with support for multiple dimensions
import torch

def custom_average(tensor, axis=None, preserve_dims=False):
    if axis is None:
        # Compute mean across all dimensions
        return torch.mean(tensor)
    else:
        # Convert single integer to list
        if isinstance(axis, int):
            axis = [axis]
        # Sort dimensions to process from left to right
        axis = sorted(axis)
        for d in axis:
            tensor = tensor.mean(dim=d, keepdim=True)
        # Remove squeezed dimensions if needed
        if not preserve_dims:
            for i, d in enumerate(axis):
                tensor.squeeze_(d - i)
        return tensor

