# Text generation utility class
import re

class TextCreator:
    def produce_text(
        self, source_data, max_len=100, end_marker=None, pattern_filter=None
    ):
        placeholder = "placeholder content, 456. Simple as pie, easy to handle."
        if isinstance(source_data, str):
            result = placeholder
        elif isinstance(source_data, list):
            result = [f"{idx}_{placeholder}" for idx, _ in enumerate(source_data)]
        else:
            raise TypeError("source_data has unexpected type %s" % type(source_data))
        result = self.finalize_output(result, max_len, end_marker, pattern_filter)
        return result

    def finalize_output(self, content, max_len, end_marker, pattern_filter):
        if isinstance(content, list):
            content = " ".join(content)
        if end_marker and end_marker in content:
            content = content[:content.index(end_marker) + len(end_marker)]
        if pattern_filter:
            content = re.sub(pattern_filter, '', content)
        if max_len and len(content) > max_len:
            content = content[:max_len]
        return content

