# Create and process a ZIP archive with simulated streaming
from datetime import datetime
from zipfile import ZipFile, ZIP_DEFLATED
from io import BytesIO

def create_and_unzip_archive(file_count, data):
    # Set fixed timestamp and file permissions
    timestamp = datetime.fromisoformat('2021-01-01 21:01:12')
    file_permissions = 0o600

    def generate_files():
        for index in range(file_count):
            yield f'file-{index}', timestamp, file_permissions, ZIP_DEFLATED, data

    def process_extracted():
        with ZipFile(BytesIO(b''.join(archive_generator(generate_files())))) as archive:
            for entry_info in archive.infolist():
                with archive.open(entry_info.filename) as file_content:
                    print(f"Filename: {entry_info.filename}, Last Modified: {entry_info.date_time}, Permissions: {entry_info.external_attr}")

    return BytesIO(b''.join(archive_generator(generate_files()))).getvalue()

# Simulated stream_zip function using ZipFile
def archive_generator(file_details):
    with ZipFile(BytesIO(), 'w') as temp_zip:
        for details in file_details():
            temp_zip.writestr(*details)
        return temp_zip.fp

