# Serialize data using specified format (pickle or json)
def serialize_data(obj, serialization_type):
    try:
        if serialization_type == "pickle":
            try:
                from cPickle import loads, dumps  # cpython 2.x
            except ImportError:
                from pickle import loads, dumps  # cpython 3.x, other interpreters
            return dumps(obj)
        elif serialization_type == "json":
            try:
                from django.utils import simplejson as json
            except ImportError:
                import json
            return json.dumps(obj)
        else:
            raise ValueError("Unsupported serialization format provided")
    except ImportError:
        raise ImportError("Required dependency is missing")

# Custom permission class for staff-only write access
from rest_framework import permissions

class StaffOnlyEditPermission(permissions.BasePermission):
    """
    Custom permission to restrict editing to staff members only.
    Non-staff users can only perform read operations.
    """
    def has_permission(self, request, view):
        # Permit read-only operations for all users
        if request.method in permissions.SAFE_METHODS:
            return True

        # Allow modification operations only for staff users
        return request.user and getattr(request.user, 'is_staff', False)

    def has_object_permission(self, request, view, obj):
        # Permit read-only operations for all users
        if request.method in permissions.SAFE_METHODS:
            return True

        # Allow modification operations only for staff users
        return request.user and getattr(request.user, 'is_staff', False)

import re

def check_password_strength(pwd):
    if len(pwd) < 8:
        return "Password is invalid."
    if not re.search(r'[A-Z]', pwd):
        return "Password is invalid."
    if not re.search(r'[a-z]', pwd):
        return "Password is invalid."
    if not re.search(r'\d', pwd):
        return "Password is invalid."
    if not re.search(r'[!@#$%^&*]', pwd):
        return "Password is invalid."
    return "Password is valid."

