# Create authentication blueprint with URL prefix
auth_bp = Blueprint('auth', __name__, url_prefix='/auth')

@auth_bp.route('/register', methods=('GET', 'POST'))
def register():
    # Handle form submission
    if request.method == 'POST':
        username_input = request.form['username']
        password_input = request.form['password']
        validation_error = None

        # Validate input fields
        if not username_input:
            validation_error = 'Username is required.'
        elif not password_input:
            validation_error = 'Password is required.'
        elif User.query.filter_by(username=username_input).first() is not None:
            validation_error = 'User {} is already registered.'.format(username_input)

        # If no errors, create new user
        if validation_error is None:
            hashed_pw = generate_password_hash(password_input)
            new_user = User(username=username_input, password=hashed_pw)
            new_user.save()  # Persist user to database
            return redirect(url_for('auth.login'))

        # Display error message
        flash(validation_error)

    # Render registration form for GET requests
    return render_template('auth/register.html')

