# Generic stack implementation using linked list
from typing import Type

class StackNode:
    def __init__(self, value: Type) -> None:
        self.value = value
        self.next_node = None

class Stack:
    def __init__(self) -> None:
        self.head = None
        self.length = 0

    def is_empty(self) -> bool:
        return self.length == 0

    def push(self, item: Type) -> None:
        new_node = StackNode(item)
        new_node.next_node = self.head
        self.head = new_node
        self.length += 1

    def pop(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")
        removed_data = self.head.value
        self.head = self.head.next_node
        self.length -= 1
        return removed_data

    def peek(self) -> Type:
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.head.value

    def get_length(self) -> int:
        return self.length

# Modified version with Type I clone transformations
from pint import UnitRegistry

class FloatValue:
    def __init__(self, enable_setter=False, data=None, dimension=None, lookup=None):
        self.enable_setter = enable_setter
        self.data = data if data else []
        self.dimension = dimension
        self.lookup = lookup if lookup else {}

    def before_assign(self, _, val):
        if self.enable_setter:
            if self.dimension:
                return self.transform_to_dimension(val)
            return val
        else:
            raise ValueError("Assignment not allowed")

    def after_retrieve(self, _, val):
        if self.lookup:
            return self.lookup.get(val, None)
        return val

    def transform_to_dimension(self, val):
        if self.dimension:
            reg = UnitRegistry()
            return reg(val).to(self.dimension).magnitude
        return val

# Test cases (transformed)
def test_assignment_without_dimension():
    f = FloatValue(enable_setter=True)
    assert f.before_assign(None, 5) == 5

def test_assignment_with_dimension():
    f = FloatValue(enable_setter=True, dimension='mV')
    u = UnitRegistry()
    assert f.before_assign(None, 1.0) == 1.0
    assert f.before_assign(None, u.parse_expression('0.0024 V')) == 2.4

def test_with_lookup_no_dimensions():
    m = FloatValue(lookup={1.0: 'Active', 2.0: 'Inactive'})
    assert m.after_retrieve(None, 'Active') == 1.0

