# Script to fetch data from an API and save the response to a file
import requests
import argparse
import logging
import json
import datetime

def fetch_api_data(endpoint_url, query_params):
    try:
        api_response = requests.get(endpoint_url, params=query_params)
        api_response.raise_for_status()  # Trigger exception for HTTP errors (4xx/5xx)
        return api_response.json()
    except requests.RequestException as error:
        logging.error(f"Error occurred during API request: {error}")
        return None

def save_response_to_file(api_data, destination_file):
    if api_data:
        try:
            with open(destination_file, 'w') as output:
                json.dump(api_data, output, indent=4)
                logging.info(f"Successfully saved API response to {destination_file}")
        except (OSError, IOError) as error:
            logging.error(f"Error writing API response to file: {error}")
    else:
        logging.error("No data received from API to save")

def main():
    parser = argparse.ArgumentParser(description='Fetch and store data from a public API')
    parser.add_argument('endpoint', help='API endpoint URL')
    parser.add_argument('--query', help='Query parameters in key=value format', default='')
    parser.add_argument('target_file', help='Path to the output file')
    arguments = parser.parse_args()

    logging.basicConfig(filename='api_call.log', level=logging.INFO, 
                        format='%(asctime)s - %(levelname)s - %(message)s')

    endpoint_url = arguments.endpoint
    query_params = dict(pair.split('=') for pair in arguments.query.split('&')) if arguments.query else {}
    target_file = arguments.target_file

    logging.info(f"Sending request to {endpoint_url} with parameters: {query_params}")
    api_data = fetch_api_data(endpoint_url, query_params)
    save_response_to_file(api_data, target_file)

if __name__ == "__main__":
    main()

# Decorator to validate function inputs based on shape, scope, and custom constraints
def check_parameters(expected_types=None, module_name=None, validation_func=None):
    def apply_decorator(fn):
        def wrapped_function(*params, **options):
            if expected_types is not None:
                if len(params) != len(expected_types):
                    raise ValueError(f"Expected {len(expected_types)} parameters, received {len(params)}")
                for idx, value in enumerate(params):
                    if not isinstance(value, expected_types[idx]):
                        raise TypeError(f"Parameter at index {idx+1} must be of type {expected_types[idx]}")
            if module_name is not None:
                import inspect
                caller_frame = inspect.currentframe().f_back
                caller_module = inspect.getmodule(caller_frame)
                if caller_module.__name__ != module_name:
                    raise ValueError(f"Function invoked from unauthorized module: {caller_module.__name__}")
            if validation_func is not None:
                if not validation_func(*params, **options):
                    raise ValueError("Validation failed: input arguments violate the specified condition")
            return fn(*params, **options)
        return wrapped_function
    return apply_decorator

