# Calculate cumulative min/max comparison across a specific axis
def cum_min_max_compare(operation, data_3d, cummax_output, axis, dtype):
    # Initialize result array with dimensions based on input data
    rows = len(data_3d)
    cols = len(data_3d[0]) if rows > 0 else 0
    result = [[0] * cols for _ in range(rows)]

    if operation == "min":
        for i in range(rows):
            for j in range(cols):
                current_min = float('inf')
                depth = len(data_3d[0][0]) if cols > 0 else 0
                for k in range(depth):
                    if dtype == "int32":
                        current_min = min(current_min, data_3d[i][j][k])
                    elif dtype == "int64":
                        current_min = min(current_min, int(data_3d[i][j][k]))
                result[i][j] = current_min

    elif operation == "max":
        for i in range(rows):
            for j in range(cols):
                current_max = float('-inf')
