# Modified version with renamed components
from typing import Iterator, Mapping, Any, Sequence, Pair
from abc import ABC, abstractmethod

class BaseRecord(ABC):
    pass

class MergedRecord(BaseRecord):
    def __init__(self, src: Mapping[str, Any], tgt: Mapping[str, Any], identifier: int):
        self.source = src
        self.target = tgt
        self.identifier = identifier

class RightMerge(RightOuterJoin):
    def _generate(self) -> Iterator[BaseRecord]:
        for target_entry, merged_entries in self.partitioned:
            found = False
            for merged_entry in merged_entries:
                source_entry = merged_entry.source
                if self.condition(source_entry, target_entry):
                    found = True
                    yield MergedRecord(source_entry, target_entry, identifier=0)
            if not found:
                yield MergedRecord(dict.fromkeys(source_entry), target_entry, identifier=0)

