import os

def save_to_xml(dump_dir: str, target_path: str, data: str) -> None:
    if os.path.isdir(target_path):
        full_path = os.path.join(dump_dir, target_path)
    else:
        filename = target_path
        full_path = dump_dir

    if not os.path.exists(full_path):
        os.makedirs(full_path)

