    with open(os.path.join(full_path, filename), 'w') as file:
        file.write(data)

# AWS Secret Manager utility to retrieve parameters from SSM
import boto3
from pathlib import Path
import secrets

class AWSSecretManager:
    def __init__(self, parameter_prefix):
        self.parameter_prefix = parameter_prefix

    def fetch_secrets(self):
        if self.parameter_prefix is None:
            return secrets

        secret_path = Path(self.parameter_prefix)
        ssm_client = boto3.client('ssm')
        response = ssm_client.get_parameters_by_path(
            Path=secret_path,
            Recursive=True,
            WithDecryption=True
        )

        secret_map = {}
        for parameter in response['Parameters']:
            param_name = parameter['Name'].split('/')[-1]
            param_value = parameter['Value']
            secret_map[param_name] = param_value

        return secret_map

