import pathlib
import sys
import typing
import shutil

def copy_all(source: pathlib.Path, target: pathlib.Path, logger: typing.TextIO = sys.stdout) -> None:
    if not source.exists():
        print(f"Source directory '{source}' does not exist.", file=logger)
        return
    try:
        target.mkdir(parents=True, exist_ok=True)
    except PermissionError:
        print(f"Permission denied: Unable to create directory '{target}'", file=logger)
        return
    except FileExistsError:
        print(f"Directory '{target}' already exists.", file=logger)
        return
    except Exception as err:
        print(f"Error creating directory '{target}': {err}", file=logger)
        return
    for element in source.iterdir():
        if element.is_dir():
            copy_all(element, target / element.name, logger)
        else:
            try:
                shutil.copy2(element, target / element.name)
                print(f"Copied '{element}' to '{target / element.name}'", file=logger)
            except PermissionError:
                print(f"Permission denied: Unable to copy '{element}' to '{target / element.name}'", file=logger)
            except FileNotFoundError:
                print(f"File '{element}' not found.", file=logger)
            except Exception as err:
                print(f"Error copying '{element}' to '{target / element.name}': {err}", file=logger)

