def handle_doe_configuration(doe_count=10, objective_weight=None):
    # Rule 1: If doe_count is not provided, default to 10
    if doe_count is None:
        doe_count = 10
    # Rule 2: If objective_weight is not provided, default to None
    if objective_weight is None:
        objective_weight = None
    # Rule 3: If objective_weight is a single float, convert it to a list containing that single float
    elif isinstance(objective_weight, float):
        objective_weight = [objective_weight]
    # Rule 4: If objective_weight is an iterable, validate its length
    elif hasattr(objective_weight, '__iter__'):
        if len(objective_weight) != doe_count:
            raise ValueError("Length of objective_weight must match the number of stochastic input variables")
    else:
        raise ValueError("Invalid objective_weight format")
    return doe_count, objective_weight

