# Type checking decorator for function arguments and return values
from functools import wraps
from inspect import signature, _empty
from typing import Any, Callable, Union

def validate_types(enable_input_check=True, enable_output_check=True):
    def type_validator(fn: Callable) -> Callable:
        @wraps(fn)
        def checker(*arguments, **keyword_args) -> Any:
            if enable_input_check:
                func_sig = signature(fn)
                bound_params = func_sig.bind(*arguments, **keyword_args)
                for arg_name, arg_value in bound_params.arguments.items():
                    expected_type = func_sig.parameters[arg_name].annotation
                    if expected_type is not _empty and not isinstance(arg_value, expected_type):
                        raise TypeError(f"Wrong type for parameter '{arg_name}'. Expected {expected_type}, got {type(arg_value)}")

            output = fn(*arguments, **keyword_args)

            if enable_output_check:
                expected_return_type = func_sig.return_annotation
                if expected_return_type is not _empty and not isinstance(output, expected_return_type):
                    raise TypeError(f"Invalid return type. Expected {expected_return_type}, but got {type(output)}")

            return output
        return checker
    return type_validator

