# Track the lifecycle of a task including execution time
from datetime import datetime, timedelta
from typing import Optional

class TaskLifecycle:
    def __init__(self, created_at: datetime, destroyed_at: datetime):
        self.created_at = created_at
        self.started_at: Optional[datetime] = None
        self.finished_at: Optional[datetime] = None
        self.destroyed_at = destroyed_at
        self.total_runtime: Optional[int] = None

    def begin_task(self, start_time: datetime) -> None:
        if start_time < self.created_at or start_time > self.destroyed_at:
            raise ValueError("Invalid start time")
        if self.started_at is not None or self.finished_at is not None:
            raise ValueError("Task already started or finished")
        self.started_at = start_time

    def complete_task(self, end_time: datetime) -> None:
        if end_time < self.created_at or end_time > self.destroyed_at:
            raise ValueError("Invalid end time")
        if self.started_at is None:
            raise ValueError("Task not started")
        if self.finished_at is not None:
            raise ValueError("Task already completed")
        self.finished_at = end_time
        self.total_runtime = int((self.finished_at - self.started_at).total_seconds())

    def get_runtime(self) -> Optional[int]:
        if self.total_runtime is None:
            raise ValueError("Runtime not available yet")
        return self.total_runtime

