# Function to mask sensitive network location info in a URL
from urllib.parse import urlparse, urlunparse

def hide_credentials_in_url(url_string):
    if not url_string:
        return url_string

    parsed = urlparse(url_string)

    # Build the masked netloc part
    host_part = parsed.hostname or ""
    if parsed.port:
        host_part += f":{parsed.port}"

    # Replace username/password with masked version if present
    if parsed.username or parsed.password:
        host_part = f"***:***@{host_part}"

    # Reconstruct URL with masked netloc
    return urlunparse(parsed._replace(netloc=host_part))

