    # Append thread key for reply threading if specified
    target_url = webhook_endpoint
    if thread_identifier:
        target_url = f"{webhook_endpoint}&threadKey={thread_identifier}"

    request_headers = {"Content-Type": "application/json; charset=UTF-8"}
    encoded_payload = json.dumps(payload_data).encode("utf-8")

    request_object = urllib.request.Request(target_url, data=encoded_payload, headers=request_headers)

    try:
        with urllib.request.urlopen(request_object) as server_response:
            decoded_result = json.loads(server_response.read().decode("utf-8"))
            return {"success": True, "response": decoded_result}
    except urllib.error.HTTPError as exception:
        error_content = exception.read().decode("utf-8")
        return {"success": False, "error": f"HTTP {exception.code}: {error_content}"}
    except Exception as exception:
        return {"success": False, "error": str(exception)}

def execute_script():
    if len(sys.argv) < 3:
        print("Usage: python3 send_webhook.py <webhook_url> <message> [--thread_key <key>]")
        sys.exit(1)

    webhook_url = sys.argv[1]
    message_text = sys.argv[2]
    selected_thread = None

    # Handle optional thread key parameter
    if len(sys.argv) >= 5 and sys.argv[3] == "--thread_key":
        selected_thread = sys.argv[4]

    outcome = post_chat_notification(webhook_url, message_text, selected_thread)

    if outcome["success"]:
        print(json.dumps(outcome["response"], indent=2))
    else:
        print(f"Error: {outcome['error']}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    execute_script()

