# Initialize backend stream storage
_stream_pool: Dict[tuple, List[torch.cuda.Stream]] = {}

def obtain_backend_stream(count=1, priority_level=0, tag=""):
    global _stream_pool
    cache_key = (priority_level, tag)
    if cache_key not in _stream_pool or len(_stream_pool[cache_key]) < count:
        _stream_pool[cache_key] = [torch.cuda.Stream(priority=priority_level) for _ in range(count)]
    return _stream_pool[cache_key][:count]

