import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class NamecomDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "namecom"
    PROVIDER_NAME = "Name.com"
    PROVIDER_DESCRIPTION = "Name.com DNS API v4"
    REQUIRED_CREDENTIALS = ["username", "api_token"]

    BASE_URL = "https://api.name.com/v4"

    def _get_auth(self):
        return (self.credentials['username'], self.credentials['api_token'])

    def _request(self, method: str, path: str, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        url = f"{self.BASE_URL}{path}"
        try:
            resp = requests.request(method=method, url=url, auth=self._get_auth(),
                                    json=data, timeout=30, headers={'Content-Type': 'application/json'})
            if resp.status_code >= 400:
                try:
                    error_msg = resp.json().get('message', resp.reason)
                except Exception:
                    error_msg = resp.reason
                return False, error_msg
            return True, resp.json() if resp.text else None
        except requests.RequestException as e:
            return False, str(e)

    def _find_domain(self, domain: str) -> Optional[str]:
        domain_parts = domain.split('.')
        for i in range(len(domain_parts) - 1):
            name = '.'.join(domain_parts[i:])
            success, result = self._request('GET', f'/domains/{name}')
            if success:
                return name
        return None

    def create_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        dom = self._find_domain(domain)
        if not dom:
            return False, f"Could not find domain {domain}"
        fqdn = record_name if record_name.endswith('.') else record_name + '.'
        data = {'host': self.get_relative_record_name(record_name, dom), 'type': 'TXT',
                'answer': record_value, 'ttl': ttl, 'fqdn': fqdn}
        success, result = self._request('POST', f'/domains/{dom}/records', data)
        if not success:
            return False, f"Failed to create record: {result}"
        return True, "Record created successfully"

    def delete_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        dom = self._find_domain(domain)
        if not dom:
            return False, f"Could not find domain {domain}"
        success, result = self._request('GET', f'/domains/{dom}/records')
        if not success:
            return False, f"Failed to list records: {result}"
        host = self.get_relative_record_name(record_name, dom)
        for rec in result.get('records', []):
            if rec.get('type') == 'TXT' and rec.get('host') == host:
                self._request('DELETE', f'/domains/{dom}/records/{rec["id"]}')
        return True, "Record deleted successfully"

    def test_connection(self) -> Tuple[bool, str]:
        success, result = self._request('GET', '/domains')
        if success:
            domains = result.get('domains', [])
            return True, f"Connected. Found {len(domains)} domain(s)"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'username', 'label': 'Username', 'type': 'text', 'required': True},
            {'name': 'api_token', 'label': 'API Token', 'type': 'password', 'required': True,
             'help': 'name.com > Account > API Token'},
        ]

import torch
from vllm.distributed import get_pcp_group
from vllm_ascend.platform import ModelConfig
from vllm_ascend.utils import singleton

def _create_attention_mask(max_length, data_type):
    # Build lower triangular mask
    attention_flag = torch.ones((max_length, max_length), dtype=torch.bool).tril_()
    # Invert to mark positions that should be masked
    attention_flag = ~attention_flag
    # Set mask values based on data type: -inf for fp16, 0 otherwise
    mask_value = float("-inf") if data_type == torch.float16 else 0
    attn_mask = torch.zeros(size=(max_length, max_length), dtype=data_type).masked_fill_(attention_flag, mask_value)
    return attn_mask

@singleton
class AttentionMaskGenerator:
    def __init__(self, device: torch.device):
        self.mask_cache = None
        self._cached_length = 0
        self.device = device
        self.mla_pattern = None
        self.prefill_mask = None
        self.pcp_mla_pattern = None
        self.swa_pattern = None

    def get_mask(self, max_length: int, data_type: torch.dtype):
        if self.mask_cache is None or max_length > self._cached_length:
            self.mask_cache = _create_attention_mask(max_length, data_type)
            self._cached_length = max_length
        assert self.mask_cache is not None, "Attention mask generation failed."
        if self.mask_cache.dtype != data_type:
            self.mask_cache = self.mask_cache.to(data_type)
        return self.mask_cache[:max_length, :max_length].contiguous().to(self.device, non_blocking=True)

    def get_split_prefill_mask(self) -> torch.Tensor:
        if self.prefill_mask is None:
            self.prefill_mask = (
                torch.triu(torch.ones(2048, 2048), diagonal=1).to(torch.int8).to(self.device)
            )
        return self.prefill_mask

    def get_mla_pattern(self, data_type: torch.dtype) -> torch.Tensor:
        if self.mla_pattern is None or self.mla_pattern.dtype != data_type:
            if data_type == torch.float16:
                fill_value = torch.finfo(torch.float32).min
            else:
                fill_value = 0
            prefill_pattern = torch.triu(torch.ones(512, 512, device=self.device, dtype=data_type), 1)
            self.mla_pattern = torch.where(prefill_pattern == 1, fill_value, 0).to(data_type)
        return self.mla_pattern

    def get_pcp_mla_pattern(self, data_type: torch.dtype):
        if self.pcp_mla_pattern is None or self.pcp_mla_pattern.dtype != data_type:
            self.pcp_mla_pattern = torch.triu(torch.ones(512, 512, device=self.device, dtype=data_type), 1)
        return self.pcp_mla_pattern

    def get_sliding_window_pattern(self, data_type: torch.dtype, window_size):
        if self.swa_pattern is None or self.swa_pattern.dtype != data_type:
            if window_size is not None:
                base_mask = torch.ones(2048, 2048, dtype=torch.bool)
                upper_tri = torch.triu(base_mask, diagonal=1).to(self.device)
                lower_tri = torch.tril(base_mask, -window_size).to(self.device)
                self.swa_pattern = (upper_tri + lower_tri).to(data_type)
        return self.swa_pattern

    def build_attention_mask(self, model_config: ModelConfig):
        if model_config.runner_type == "pooling":
            return self.get_mask(2048, torch.bool)
        return self.get_split_prefill_mask()

    def build_final_mla_pattern(self, model_config: ModelConfig):
        if get_pcp_group().world_size > 1:
            return self.get_pcp_mla_pattern(model_config.dtype)
        # Prefill uses 512x512 pattern with correct dtype
        return self.get_mla_pattern(model_config.dtype)

# Convert GPA values to corresponding letter grades
def convert_to_letter_grades(gpa_list):
    """Converts a list of GPA scores into letter grades based on the teacher's grading scale."""
    result = []

    for gpa in gpa_list:
        if gpa == 4.0:
            result.append('A+')
        elif gpa > 3.7:
            result.append('A')
        elif gpa > 3.3:
            result.append('A-')
        elif gpa > 3.0:
            result.append('B+')
        elif gpa > 2.7:
            result.append('B')
        elif gpa > 2.3:
            result.append('B-')
        elif gpa > 2.0:
            result.append('C+')
        elif gpa > 1.7:
            result.append('C')
        elif gpa > 1.3:
            result.append('C-')
        elif gpa > 1.0:
            result.append('D+')
        elif gpa > 0.7:
            result.append('D')
        elif gpa > 0.0:
            result.append('D-')
        else:
            result.append('E')

    return result

