# Modified version with renamed variables and restructured logic
import random
import itertools
import numpy as np
import torch

def create_data_iterators(train_loader=None, val_loader=None, test_loader=None, mode="cyclic"):
    def _infinite_cycle(loader):
        while True:
            for batch in loader:
                yield batch

    def _create_iterator(data_loader, iterator_mode=mode):
        """Generate appropriate iterator based on mode."""
        if iterator_mode == "single":
            return iter(data_loader)
        elif iterator_mode == "cyclic":
            return iter(_infinite_cycle(data_loader))
        else:
            raise ValueError("Unsupported iterator mode")

    # Create iterators for each dataset if provided
    train_iter = _create_iterator(train_loader) if train_loader is not None else None
    val_iter = _create_iterator(val_loader) if val_loader is not None else None
    test_iter = _create_iterator(test_loader) if test_loader is not None else None

    return train_iter, val_iter, test_iter

def setup_deterministic_seed(seed_value):
    """Configure deterministic behavior for data loading."""
    def worker_init_fn(worker_id):
        worker_seed = seed_value
        np.random.seed(worker_seed)
        torch.manual_seed(worker_seed)
        random.seed(worker_seed)
    return worker_init_fn

# Dense MLP Profiler implementation for performance benchmarking
from typing import Optional, Tuple
from primus.core.projection.base_module_profiler import BaseModuleProfiler
from primus.core.projection.profiler_spec import ModuleProfilerSpec
from primus.core.projection.training_config import TrainingConfig
from .utils import benchmark_layer

class DenseMLPProfiler(BaseModuleProfiler):
    def __init__(self, settings, child_profilers=None):
        super().__init__(settings, child_profilers)
        self.module = None  # Will be assigned during benchmarking phase
        self._stored_results = None  # Cache for (forward_duration, backward_duration, activation_bytes)
        self._cache_identifier = None  # Cache identifier (batch_size, sequence_length)

    def assign_module(self, model):
        """Assign the actual Dense MLP module for performance profiling."""
        self.module = model
        # Clear cache when module configuration changes
        self._stored_results = None
        self._cache_identifier = None

    def estimated_parameter_count(self, rank: Optional[int] = None) -> int:
        # For SwiGLU: 3 linear transformations (gate, up, down)
        # For standard FFN: 2 linear transformations (up, down)
        ffn_projection_count = 3 if self.config.model_config.swiglu else 2
        return (
            self.config.model_config.hidden_dimension
            * self.config.model_config.ffn_intermediate_size
            * ffn_projection_count
        )

    def estimated_activation_memory_usage(self, batch_size: int, sequence_length: int) -> int:
        total_tokens = (
            batch_size
            * sequence_length
            // self.config.model_parallel_config.tensor_model_parallel_degree
            // self.config.model_parallel_config.context_model_parallel_degree
        )
        # Memory requirements after first projection(s)
        if self.config.model_config.swiglu:
            # Store both gate and up projections for gradient computation
            intermediate_storage = 2 * total_tokens * self.config.model_config.ffn_intermediate_size * 2  # bf16
        else:
            intermediate_storage = total_tokens * self.config.model_config.ffn_intermediate_size * 2  # bf16

        # After activation function
        post_activation_memory = total_tokens * self.config.model_config.ffn_intermediate_size * 2  # bf16
        output_storage = total_tokens * self.config.model_config.hidden_dimension * 2  # bf16

        # Peak memory usage is sum of input + intermediate (both required for backward pass)
        return intermediate_storage + post_activation_memory + output_storage

    def _retrieve_benchmark_data(self, batch_size: int, sequence_length: int) -> Tuple[float, float, int]:
        """Fetch or compute benchmark data using caching mechanism."""
        cache_id = (batch_size, sequence_length)
        if self._stored_results is None or self._cache_identifier != cache_id:
            self._stored_results = benchmark_layer(
                self.module,
                [(sequence_length, batch_size, self.config.model_config.hidden_dimension)],
            )
            self._cache_identifier = cache_id
        return self._stored_results

    def measured_forward_duration(self, batch_size: int, sequence_length: int) -> float:
        forward_duration, _, _ = self._retrieve_benchmark_data(batch_size, sequence_length)
        return forward_duration

    def measured_backward_duration(self, batch_size: int, sequence_length: int) -> float:
        _, backward_duration, _ = self._retrieve_benchmark_data(batch_size, sequence_length)
        return backward_duration

    def measured_activation_memory(self, batch_size: int, sequence_length: int) -> int:
        _, _, activation_bytes = self._retrieve_benchmark_data(batch_size, sequence_length)
        return activation_bytes

def create_dense_mlp_profiler_spec(settings: TrainingConfig) -> ModuleProfilerSpec:
    return ModuleProfilerSpec(
        profiler=DenseMLPProfiler,
        config=settings,
        sub_profiler_specs=None,
    )

