# Tool for writing content to a file, creating directories as needed
import os
from typing import Dict
from agent.tool_base import Tool

class FileWriteTool(Tool):
    name = "file_write"
    description = "Writes provided content to a specified file path, automatically creating parent directories if they don't exist."
    parameters = {
        "type": "object",
        "properties": {
            "filepath": {
                "type": "string",
                "description": "The destination file path where content should be written.",
            },
            "text": {
                "type": "string",
                "description": "The textual content to be written into the file.",
            },
        },
        "required": ["filepath", "text"],
    }

    async def execute(self, params: Dict) -> str:
        filepath = params["filepath"]
        text = params["text"]
        try:
            # Extract directory part of the path and create it if necessary
            folder_path = os.path.dirname(filepath)
            if folder_path:
                await self.run_cmd(cmd=["mkdir", "-p", folder_path])

            # Write content using tee command
            await self.run_cmd(cmd=["tee", filepath], stdin=text)
            return f"Successfully wrote to {filepath}"
        except Exception as error:
            return f"Error writing file: {error}"

# Garbage collection monitoring utility 
import gc
import weakref
from typing import Any
from statgpt.common.config import multiline_logger as logger

class GCInspector:
    """Monitor specific objects and observe their lifecycle."""
    def __init__(self):
        self.monitored_refs = {}

    def monitor(self, item: Any, label: str):
        """Monitor an object using a weak reference."""
        def cleanup(ref):
            item_class = type(item).__name__
            logger.info(f"GC: Item '{label}' (class={item_class}) has been freed")

        item_class = type(item).__name__
        weak_ptr = weakref.ref(item, cleanup)
        self.monitored_refs[label] = weak_ptr
        logger.info(f"GC: Now monitoring item '{label}' (class={item_class}, id={id(item)})")

    def status_check(self):
        """Determine which monitored items are still active."""
        active = []
        inactive = []
        for label, weak_ptr in self.monitored_refs.items():
            if weak_ptr() is not None:
                item = weak_ptr()
                active.append((label, type(item).__name__, id(item)))
            else:
                inactive.append(label)

        if active:
            logger.info("GC: Active items:")
            for label, item_class, item_id in active:
                logger.info(f"  - {label} (class={item_class}, id={item_id})")

        if inactive:
            logger.info(f"GC: Freed items: {inactive}")

        return active, inactive

    def trace_references(self, item_label: str, max_count: int = 5):
        """Identify what's referencing a monitored object."""
        weak_ptr = self.monitored_refs.get(item_label)
        if weak_ptr is None:
            return f"Item '{item_label}' is not being monitored"

        item = weak_ptr()
        if item is None:
            return f"Item '{item_label}' has already been garbage collected"

        references = gc.get_referrers(item)
        logger.info(f"GC: Item '{item_label}' is referenced by {len(references)} sources:")
        for idx, ref in enumerate(references[:max_count]):
            ref_type = type(ref).__name__
            if ref_type == 'frame':
                continue  # Omit frame objects

            logger.info(f"  [{idx}] Type: {ref_type}")

            # Attempt to gather additional details
            if hasattr(ref, '__qualname__'):
                logger.info(f"      Name: {ref.__qualname__}")
            if hasattr(ref, '__class__'):
                logger.info(f"      Class: {ref.__class__.__name__}")
            if isinstance(ref, dict):
                sample_keys = list(ref.keys())[:3]
                logger.info(f"      Sample keys: {sample_keys}")

        return f"Discovered {len(references)} references for '{item_label}'"

# Global instance for GC inspection
gc_inspector = GCInspector()

def report_gc_metrics():
    """Output garbage collection statistics."""
    metrics = gc.get_stats()
    for index, generation in enumerate(metrics):
        logger.info(
            f"GC Generation {index}: cycles={generation['collections']}, "
            f"freed={generation['collected']}, unreachable={generation['uncollectable']}"
        )

    # Trigger collection and display results
    logger.info("GC: Initiating collection...")
    freed = gc.collect()
    logger.info(f"GC: Freed {freed} objects")

    # Inspect any uncollectable objects
    if gc.garbage:
        logger.warning(f"GC: Detected {len(gc.garbage)} unreachable objects!")
        for obj in gc.garbage[:5]:
            logger.warning(f"  - Class: {type(obj).__name__}, Identity: {id(obj)}")

