# Convert GPA values to corresponding letter grades
def convert_to_letter_grades(gpa_list):
    """Converts a list of GPA scores into letter grades based on a predefined scale.

    Args:
        gpa_list: A list of numeric GPA values

    Returns:
        A list of letter grade strings corresponding to each GPA
    """
    result = []
    for score in gpa_list:
        if score == 4.0:
            result.append('A+')
        elif score > 3.7:
            result.append('A')
        elif score > 3.3:
            result.append('A-')
        elif score > 3.0:
            result.append('B+')
        elif score > 2.7:
            result.append('B')
        elif score > 2.3:
            result.append('B-')
        elif score > 2.0:
            result.append('C+')
        elif score > 1.7:
            result.append('C')
        elif score > 1.3:
            result.append('C-')
        elif score > 1.0:
            result.append('D+')
        elif score > 0.7:
            result.append('D')
        elif score > 0.0:
            result.append('D-')
        else:
            result.append('E')
    return result

