# Custom exception classes for requests library
from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """An ambiguous exception occurred during request handling."""
    def __init__(self, *args, **kwargs):
        """Initialize with optional `request` and `response` objects."""
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = self.response.request
        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """An error occurred while processing JSON."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Failed to decode text into JSON format."""
    def __init__(self, *args, **kwargs):
        """
        Initialize JSONDecodeError by first constructing with all args,
        then using its args to initialize IOError to preserve JSON-specific
        error messages.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """An HTTP protocol error occurred."""

class ConnectionError(RequestException):
    """A network connection error occurred."""

class ProxyError(ConnectionError):
    """An error occurred while using a proxy."""

class SSLError(ConnectionError):
    """An SSL/TLS certificate error occurred."""

class Timeout(RequestException):
    """The request operation exceeded the time limit.
    This exception covers both connection and read timeout scenarios.
    """
    pass

class ConnectTimeout(ConnectionError, Timeout):
    """Connection establishment timed out. The request can be safely retried."""

class ReadTimeout(Timeout):
    """Server failed to send data within the allocated timeframe."""

class URLRequired(RequestException):
    """A valid URL must be provided for this operation."""

class TooManyRedirects(RequestException):
    """Maximum number of redirects exceeded."""

class MissingSchema(RequestException, ValueError):
    """URL scheme (e.g., 'http' or 'https') is missing."""

class InvalidSchema(RequestException, ValueError):
    """The specified URL schema is invalid or not supported."""

class InvalidURL(RequestException, ValueError):
    """The provided URL format is invalid."""

class InvalidHeader(RequestException, ValueError):
    """The header value format is invalid."""

class InvalidProxyURL(InvalidURL):
    """The proxy URL provided is malformed."""

class ChunkedEncodingError(RequestException):
    """Server used chunked transfer encoding but sent malformed chunks."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Response content could not be decoded properly."""

class StreamConsumedError(RequestException, TypeError):
    """Attempted to consume response content that was already consumed."""

class RetryError(RequestException):
    """Custom retry mechanism encountered a failure."""

class UnrewindableBodyError(RequestException):
    """Unable to rewind request body after an error condition."""

# Warning classes
class RequestsWarning(Warning):
    """Base warning class for the requests library."""

class FileModeWarning(RequestsWarning, DeprecationWarning):
    """File opened in text mode; binary length was determined by Requests."""

class RequestsDependencyWarning(RequestsWarning):
    """An imported dependency version does not meet requirements."""

# Custom tool registry implementation for managing tool factories
from abc import ABC, abstractmethod
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes

class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        self._registry: dict[ToolTypes, type[StatGptTool]] = {}

    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must be a subclass of {StatGptTool}")
        if tool_type in self._registry:
            raise ValueError(
                f"Cannot register {factory} factory:"
                f" {tool_type=} already registered with {self._registry[tool_type]}"
            )
        self._registry[tool_type] = factory

    def __delitem__(self, tool_type: ToolTypes, /):
        del self._registry[tool_type]

    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        if key not in self._registry:
            raise KeyError(
                f"Factory has not been registered for {key} agent."
                f" Please ensure that the factory is imported in the global space."
                f"\nAvailable agents: {list(self._registry.keys())}"
            )
        return self._registry[key]

    def __iter__(self):
        return iter(self._registry)

    def __len__(self):
        return len(self._registry)

_TOOL_IMPLEMENTATIONS = ToolRegistry()

class ToolArgs(BaseModel):
    # injected tool argument. set in the code, not by the LLM.
    # LLM can't set this field because it's not added to the tool schema shown to LLM.
    # `inputs` is used to pass execution context from Supreme Agent to the tool.
    inputs: Annotated[dict, InjectedToolArg] = Field()

ToolConfigType = TypeVar('ToolConfigType', bound=BaseToolConfig)

class StatGptTool(BaseTool, ABC, Generic[ToolConfigType]):
    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    tool_type: ToolTypes  # Set dynamically in __init_subclass__

    def __init_subclass__(cls, **kwargs):
        tool_type = kwargs.pop('tool_type', None)
        super().__init_subclass__(**kwargs)
        if StatGptTool in cls.__bases__:
            # we want to register tool instance (like DataQueryTool),
            # not generic itself (like StatGptTool[DataQueryToolConfig])
            return
        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must specify a 'tool_type' parameter")
        if not isinstance(tool_type, ToolTypes):
            raise ValueError(f"{tool_type=} must be an instance of {ToolTypes}")
        cls.tool_type = tool_type
        _TOOL_IMPLEMENTATIONS[tool_type] = cls

    def __init__(self, tool_config: ToolConfigType, channel_config: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._tool_config = tool_config
        self._channel_config = channel_config

    @property
    def stage_name(self) -> str:
        """Return the stage name of calling this tool."""
        if name := self._tool_config.details.stages_config.tool_call_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Executing {tool_name} tool"

    @property
    def result_stage_name(self) -> str:
        """Return the stage name of showing the result of this tool."""
        if name := self._tool_config.details.stages_config.tool_result_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Output from {tool_name} tool"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """This method is implemented to satisfy the BaseTool interface.
        But it raises an error since we don't want to use it."""
        raise NotImplementedError("This method should not be called. Use async version instead.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass

    @classmethod
    def get_args_schema(cls, tool_config: ToolConfigType) -> type[ToolArgs]:
        """Return the schema for the arguments that this tool accepts."""
        return ToolArgs

    @staticmethod
    def from_config(tool_config: ToolConfigType, channel_config: ChannelConfig) -> 'StatGptTool':
        cls = _TOOL_IMPLEMENTATIONS[tool_config.type]
        return cls(
            tool_config=tool_config,
            channel_config=channel_config,
            name=tool_config.name,
            description=tool_config.description,
            args_schema=cls.get_args_schema(tool_config),
        )

# Module for loading and parsing skill definition files
import re
from pathlib import Path
from typing import Any, Dict, Optional, Tuple
import yaml

class SkillParser:
    """Handle loading and parsing of skill markdown files."""
    HEADER_PATTERN = re.compile(r"^---\s*\n(.*?)\n---\s*\n(.*)$", re.DOTALL)

    @classmethod
    def load_skill(cls, filepath: str) -> Dict[str, Any]:
        """Read skill file from disk and return structured data."""
        file_path_obj = Path(filepath)
        if not file_path_obj.is_file():
            raise FileNotFoundError(f"Skill file missing: {filepath}")
        raw_text = file_path_obj.read_text(encoding="utf-8")
        return cls.parse_content(raw_text, source=str(file_path_obj))

    @classmethod
    def parse_content(cls, text: str, source: str = "") -> Dict[str, Any]:
        """Parse raw markdown content into a dictionary."""
        header, body = cls._extract_header(text)
        if not header:
            raise ValueError("Skill file must include YAML header")

        metadata = yaml.safe_load(header)
        if not isinstance(metadata, dict):
            raise ValueError("YAML header format is incorrect")

        if "title" not in metadata:
            raise ValueError("'title' field is required in skill definition")
        if "summary" not in metadata:
            raise ValueError("'summary' field is required in skill definition")

        return {
            "title": metadata["title"],
            "summary": metadata["summary"],
            "body": body.strip(),
            "origin": source,
            "tools": metadata.get("tools", []),
            "keywords": metadata.get("keywords", []),
        }

    @classmethod
    def _extract_header(cls, text: str) -> Tuple[Optional[str], str]:
        """Separate header section from main content."""
        match = cls.HEADER_PATTERN.match(text)
        if match:
            return match.group(1), match.group(2)
        return None, text

    @classmethod
    def generate_markdown(cls, skill_data: Dict[str, Any]) -> str:
        """Transform skill dictionary back into markdown format."""
        header_info: dict = {
            "title": skill_data["title"],
            "summary": skill_data.get("summary", ""),
        }
        yaml_output = yaml.dump(header_info, allow_unicode=True, sort_keys=False)
        return f"---\n{yaml_output}---\n\n{skill_data.get('body', '')}"

# CS:GO match analysis tool using Leetify API
import sys
import json
import argparse
import requests
import subprocess
import os
from datetime import datetime

API_KEY = os.environ.get("LEETIFY_API_KEY")
if not API_KEY:
    print(json.dumps({"error": "LEETIFY_API_KEY environment variable not set"}))
    sys.exit(1)

API_BASE_URL = "https://api-public.cs-prod.leetify.com"

def make_api_call(endpoint, query_params=None):
    auth_headers = {"Authorization": f"Bearer {API_KEY}"}
    full_url = f"{API_BASE_URL}{endpoint}"
    try:
        api_response = requests.get(full_url, params=query_params, headers=auth_headers)
        if api_response.status_code == 200:
            return {"success": True, "payload": api_response.json()}
        else:
            return {"success": False, "message": f"{api_response.status_code} {api_response.text}"}
    except Exception as error:
        return {"success": False, "message": str(error)}

def fetch_player_match_details(player_steam_id, match_position=0):
    # Step 1: Retrieve list of recent matches
    result = make_api_call('/v3/profile/matches', {'steam64_id': player_steam_id, 'limit': match_position + 1})

    if not result['success']:
        print(json.dumps({"error": result.get('message')}))
        return

    match_list = result['payload']

    # Handle both direct list and wrapped response formats
    if isinstance(match_list, dict) and 'matches' in match_list:
        match_list = match_list['matches']

    if not isinstance(match_list, list):
        print(json.dumps({"error": "Unexpected API response structure"}))
        return

    if len(match_list) <= match_position:
        print(json.dumps({"error": f"Match index {match_position} unavailable. Total matches: {len(match_list)}"}))
        return

    selected_match = match_list[match_position]

    # Step 2: Locate the specific player's performance data
    # The 'performance' array holds detailed metrics for each participant
    player_performance = next((p for p in selected_match.get('performance', []) if p['steam64_id'] == player_steam_id), None)

    if not player_performance:
        print(json.dumps({"error": "Player statistics missing from this match record"}))
        return

    # Step 3: Assemble the report object
    # Merge match context (map, score, timestamp) with comprehensive player metrics

    report_data = {
        "context": {
            "map_name": selected_match.get('map_name'),
            "timestamp": selected_match.get('finished_at'),
            "final_scores": selected_match.get('team_scores'),
            "source": selected_match.get('data_source'),
            "match_identifier": selected_match.get('id')
        },
        # This includes: shooting precision, spray patterns, utility effectiveness, 
        # kill trades, entry plays, clutch scenarios, etc.
        "metrics": player_performance 
    }

    # Emit JSON for downstream processing
    print(json.dumps(report_data, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    argument_parser = argparse.ArgumentParser()
    argument_parser.add_argument("--player", required=True)
    argument_parser.add_argument("--position", type=int, default=0)
    cli_args = argument_parser.parse_args()

    current_script_path = os.path.dirname(os.path.abspath(__file__))
    try:
        # Convert username to Steam ID
        steam_id_output = subprocess.check_output(
            ['python3', os.path.join(current_script_path, 'steam_ids.py'), 'lookup', '--username', cli_args.player],
            text=True
        ).strip()

        if "No Steam ID" in steam_id_output or not steam_id_output:
            print(json.dumps({"error": f"Unable to locate Steam ID for {cli_args.player}"}))
            sys.exit(1)
        target_steam_id = steam_id_output
    except Exception as ex:
        print(json.dumps({"error": f"Steam ID lookup failure: {str(ex)}"}))
        sys.exit(1)

    fetch_player_match_details(target_steam_id, cli_args.position)

