# Tool for editing files by replacing exact string matches
from typing import Dict
from agent.tool_base import Tool

class FileEditTool(Tool):
    name = "file_edit"
    description = (
        "Modify a file by substituting an exact string with new content. "
        "The search string must match precisely (including whitespace and indentation). "
        "Include sufficient context in the search string to ensure uniqueness within the file."
    )
    parameters = {
        "type": "object",
        "properties": {
            "filepath": {
                "type": "string",
                "description": "The path to the target file.",
            },
            "search_text": {
                "type": "string",
                "description": "The precise string to locate and replace. Must be unique in the file.",
            },
            "replacement_text": {
                "type": "string",
                "description": "The text that will replace the found string.",
            },
        },
        "required": ["filepath", "search_text", "replacement_text"],
    }

    async def execute(self, arguments: Dict) -> str:
        filepath = arguments["filepath"]
        search_text = arguments["search_text"]
        replacement_text = arguments["replacement_text"]

        try:
            file_content = await self.run_cmd(cmd=["cat", filepath])
        except Exception as error:
            return f"Failed to read file: {error}"

        if search_text == replacement_text:
            return "Error: search_text and replacement_text are identical."

        occurrences = file_content.count(search_text)
        if occurrences == 0:
            return "Error: search_text not found in file."
        if occurrences > 1:
            return f"Error: search_text appears in {occurrences} locations. Provide more context to make it unique."

        updated_content = file_content.replace(search_text, replacement_text, 1)

        try:
            await self.run_cmd(cmd=["tee", filepath], stdin=updated_content)
            return f"Successfully modified {filepath}"
        except Exception as error:
            return f"Failed to write to file: {error}"

