        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

    def execute_post_request(self, action, parameters={}, request_body={}):
        response = self.json(action, parameters, request_body)
        if response == '':
            raise Exception("%s: empty response" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

# Process BSON data and Feather files
import os, sys
import ctypes as ct
import json
from . import xtbson as bson

def parse_bson_from_bytes(data_stream):
    output = []
    index = 0
    while True:
        if index + 4 < len(data_stream):
            size_bytes = data_stream[index : index + 4]
        else:
            break
        size = ct.cast(size_bytes, ct.POINTER(ct.c_int32))[0]
        if size >= 5:
            try:
                chunk = data_stream[index : index + size]
                index += size
                output.append(bson.decode(chunk))
            except Exception as err:
                continue
        else:
            break
    return output

def serialize_to_bson_bytes(records):
    stream = b''
    for record in records:
        stream += bson.encode(record)
    return stream

