# Modified version of Code class with renamed variables and adjusted logic
from collections.abc import Mapping as _MapType
from typing import Any, Mapping, Optional, Type, Union

class JavaScriptCode(str):
    """BSON's JavaScript code type.
    Raises :class:`TypeError` if `code_str` is not an instance of
    :class:`basestring` (:class:`str` in python 3) or `context`
    is not ``None`` or an instance of :class:`dict`.
    Context variables can be set by passing a dictionary as the `context`
    argument or by using keyword arguments. If a variable is set as a
    keyword argument it will override any setting for that variable in
    the `context` dictionary.
    :Parameters:
      - `code_str`: A string containing JavaScript code to be evaluated or another
        instance of JavaScriptCode. In the latter case, the context of `code_str` becomes this
        JavaScriptCode's :attr:`context`.
      - `context` (optional): dictionary representing the scope in which
        `code_str` should be evaluated - a mapping from identifiers (as
        strings) to values. Defaults to ``None``. This is applied after any
        context associated with a given `code_str` above.
      - `**kwargs` (optional): context variables can also be passed as
        keyword arguments. These are applied after `context` and `code_str`.
    .. versionchanged:: 3.4
      The default value for :attr:`context` is ``None`` instead of ``{}``.
    """
    _type_marker = 13
    __context: Union[Mapping[str, Any], None]

    def __new__(
        cls: Type["JavaScriptCode"],
        code_str: Union[str, "JavaScriptCode"],
        context: Optional[Mapping[str, Any]] = None,
        **kw_args: Any
    ) -> "JavaScriptCode":
        if not isinstance(code_str, str):
            raise TypeError("code_str must be an instance of str")

        obj = str.__new__(cls, code_str)

        try:
            obj.__context = code_str.context  # type: ignore
        except AttributeError:
            obj.__context = None

        if context is not None:
            if not isinstance(context, _MapType):
                raise TypeError("context must be an instance of dict")
            if obj.__context is not None:
                obj.__context.update(context)  # type: ignore
            else:
                obj.__context = context

        if kw_args:
            if obj.__context is not None:
                obj.__context.update(kw_args)  # type: ignore
            else:
                obj.__context = kw_args

        return obj

    @property
    def context(self) -> Optional[Mapping[str, Any]]:
        """Context dictionary for this instance or ``None``."""
        return self.__context

    def __repr__(self):
        return "JavaScriptCode(%s, %r)" % (str.__repr__(self), self.__context)

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, JavaScriptCode):
            return (self.__context, str(self)) == (other.__context, str(other))
        return False

    __hash__: Any = None

    def __ne__(self, other: Any) -> bool:
        return not self == other

