# Type I clone: Renamed variables, changed literals, reordered statements
import sys as _sys

if _sys.version_info >= (3, 11):
    from importlib.resources import as_file as _as_file, files as _files

    _CERT_CTX = None
    _CERT_PATH = None

    def locate() -> str:
        # Delay extraction until needed, then cache the result
        global _CERT_CTX
        global _CERT_PATH

        if _CERT_PATH is None:
            # Slight trickiness: importlib.resources API returns a context manager
            # that provides the path on entry and handles cleanup on exit.
            # In typical cases (non-temporary files), __exit__ does nothing.
            # We must keep the context manager alive to prevent premature cleanup.
            _CERT_CTX = _as_file(_files("pip._vendor.certifi").joinpath("cacert.pem"))
            _CERT_PATH = str(_CERT_CTX.__enter__())

        return _CERT_PATH

    def read_contents() -> str:
        return _files("pip._vendor.certifi").joinpath("cacert.pem").read_text(encoding="ascii")

elif _sys.version_info >= (3, 7):
    from importlib.resources import path as _get_path, read_text as _read_text

    _CERT_CTX = None
    _CERT_PATH = None

    def locate() -> str:
        # Delay extraction until needed, then cache the result
        global _CERT_CTX
        global _CERT_PATH

        if _CERT_PATH is None:
            # Similar trickiness with context manager as above
            _CERT_CTX = _get_path("pip._vendor.certifi", "cacert.pem")
            _CERT_PATH = str(_CERT_CTX.__enter__())

        return _CERT_PATH

    def read_contents() -> str:
        return _read_text("pip._vendor.certifi", "cacert.pem", encoding="ascii")

else:
    import os as _os
    import types as _types
    from typing import Union as _Union

    Package = _Union[_types.ModuleType, str]
    Resource = _Union[str, "_os.PathLike"]

    # Fallback for older Python versions without importlib.resources
    def _read_text(
        package: Package,
        resource: Resource,
        encoding: str = 'utf-8',
        errors: str = 'strict'
    ) -> str:
        with open(locate(), encoding=encoding) as data:
            return data.read()

    # Assume filesystem-based location for older versions
    def locate() -> str:
        dir_path = _os.path.dirname(__file__)
        return _os.path.join(dir_path, "cacert.pem")

    def read_contents() -> str:
        return _read_text("pip._vendor.certifi", "cacert.pem", encoding="ascii")

# Utility module for handling embedding messages in JSON format
import json
from dataclasses import asdict, dataclass
from typing import Any, Dict, List, Union
from uuid import uuid4

@dataclass
class EmbeddingMessage:
    message: Union[str, List[Dict[str, Any]]]
    context_data: Dict[str, Any]

    def __init__(self, message: Union[str, List[Dict[str, Any]]], context_data: Dict[str, Any]):
        self.unique_id = str(uuid4())
        self.message = message
        self.context_data = context_data

    def to_dictionary(self) -> Dict[str, Any]:
        """Transform the embedding message into a dictionary representation."""
        return asdict(self)

    def to_json_string(self) -> str:
        """Serialize the embedding message to a JSON string."""
        return json.dumps(self.to_dictionary())

    @classmethod
    def create_from_dict(cls, input_data: Dict[str, Any]) -> "EmbeddingMessage":
        """Instantiate an embedding message from a dictionary."""
        instance = cls(
            message=input_data["message"],
            context_data=input_data["context_data"],
        )
        instance.unique_id = input_data.get("unique_id", instance.unique_id)
        return instance

    @classmethod
    def create_from_json(cls, json_text: str) -> "EmbeddingMessage":
        """Safely construct an object from a JSON string."""
        try:
            parsed_data = json.loads(json_text)
            return cls.create_from_dict(parsed_data)
        except json.JSONDecodeError as error:
            raise ValueError(f"Malformed JSON input: {error}")

# Google Slides CLI tool for managing presentations
from pathlib import Path
import click
from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build

TOKEN_PATH = Path.home() / ".simple-google-workspace" / "token.json"

def obtain_slides_service():
    if not TOKEN_PATH.is_file():
        raise click.ClickException("Not authenticated. Run: uv run scripts/auth.py login")
    credentials = Credentials.from_authorized_user_file(TOKEN_PATH)
    return build("slides", "v1", credentials=credentials)

def obtain_drive_service():
    credentials = Credentials.from_authorized_user_file(TOKEN_PATH)
    return build("drive", "v3", credentials=credentials)

@click.group()
def main_group():
    """Google Slides commands."""

@main_group.command()
@click.argument("search_term")
def search(search_term: str):
    """Search presentations by name."""
    drive = obtain_drive_service()
    query = f"name contains '{search_term}' and mimeType = 'application/vnd.google-apps.presentation'"
    results = drive.files().list(q=query, fields="files(id,name)").execute()
    items = results.get("files", [])
    if not items:
        click.echo("No presentations found.")
        return
    for item in items:
        click.echo(f"[{item['id']}] {item['name']}")

@main_group.command()
@click.argument("presentation_identifier")
def show(presentation_identifier: str):
    """Display presentation metadata and slide titles."""
    service = obtain_slides_service()
    presentation = service.presentations().get(presentationId=presentation_identifier).execute()
    click.echo(f"Title: {presentation.get('title')}")
    click.echo(f"Slides: {len(presentation.get('slides', []))}")
    click.echo("---")
    for index, slide in enumerate(presentation.get("slides", []), start=1):
        # Attempt to retrieve slide title from shapes
        slide_title = "(No title)"
        for obj in slide.get("pageElements", []):
            if "shape" in obj:
                shape_obj = obj["shape"]
                if shape_obj.get("placeholder", {}).get("type") == "TITLE":
                    text_parts = shape_obj.get("text", {}).get("textElements", [])
                    for part in text_parts:
                        if "textRun" in part:
                            slide_title = part["textRun"].get("content", "").strip()
                            break
        click.echo(f"Slide {index}: {slide_title}")

@main_group.command()
@click.argument("presentation_identifier")
def extract(presentation_identifier: str):
    """Extract all text content from presentation."""
    service = obtain_slides_service()
    presentation = service.presentations().get(presentationId=presentation_identifier).execute()
    click.echo(f"# {presentation.get('title')}\n")
    for idx, slide in enumerate(presentation.get("slides", []), start=1):
        click.echo(f"## Slide {idx}")
        for element in slide.get("pageElements", []):
            if "shape" in element and "text" in element.get("shape", {}):
                for te in element["shape"]["text"].get("textElements", []):
                    if "textRun" in te:
                        text_content = te["textRun"].get("content", "").strip()
                        if text_content:
                            click.echo(text_content)
        click.echo()

@main_group.command()
@click.argument("new_title")
def new(new_title: str):
    """Create a new presentation."""
    service = obtain_slides_service()
    presentation = service.presentations().create(body={"title": new_title}).execute()
    click.echo(f"Created: {presentation.get('title')}")
    click.echo(f"ID: {presentation.get('presentationId')}")
    click.echo(f"Link: https://docs.google.com/presentation/d/{presentation.get('presentationId')}")

if __name__ == "__main__":
    main_group()

# Extract pair address from a new pool transaction 
pair_addr = None
def fetch_pool_pair_address(context, signature):
    try:
        sig_obj = Signature.from_string(signature)
        tx_data = context.get_transaction(sig_obj, encoding="jsonParsed", max_supported_transaction_version=0).value.transaction.transaction.message.instructions
        for instruction in tx_data:
            if "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8" in str(instruction.program_id):
                pair_addr = str(instruction.accounts[4])
        return pair_addr
    except:
        return pair_addr

