# Helper functions to convert Narwhals frames to Polars frames
from typing import Any, overload
import narwhals as nw
import polars as pl
from narwhals.typing import DataFrameT, Frame, FrameT, LazyFrameT

def convert_to_eager_polars(frame: Frame) -> pl.DataFrame:
    """Convert a Narwhals frame to an eager Polars DataFrame."""
    return frame.lazy().collect().to_polars()

def convert_lazy_to_polars(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals lazy frame to a Polars lazy frame.
    If the Narwhals LazyFrame is already backed by Polars, this is a no-op."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()
    return frame.collect().to_polars().lazy()

@overload
def adapt_to_polars_implementation(frame: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars_implementation(frame: LazyFrameT) -> LazyFrameT: ...
def adapt_to_polars_implementation(frame: FrameT) -> FrameT:
    if frame.implementation == nw.Implementation.POLARS:
        return frame
    elif isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())
    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()
    else:
        raise ValueError(f"Unsupported frame type: {type(frame)}")

__all__ = ["convert_to_eager_polars"]

