import sys, json, argparse
from pathlib import Path
from typing import Set, List, Dict
from config_handler import ConfigHandler
from markdown_utils import get_backlinks_recursive, extract_hashtags

def safe_read(filepath):
    try:
        return Path(filepath).read_text(encoding='utf-8')
    except Exception:
        return ""

def save_json(path, content):
    Path(path).write_text(json.dumps(content, indent=2), encoding='utf-8')

def find_notes_by_tags(
    target_tags: Set[str],
    notes_folder: Path,
    reference_file: Path,
    limit: int = 5
) -> List[str]:
    """
    Identify notes sharing common tags with the reference.
    Returns list of paths: ['/path/to/note1.md']
    """
    matches = []
    for file_path in notes_folder.rglob("*.md"):
        if file_path.resolve() == reference_file.resolve():
            continue
        try:
            content = file_path.read_text(encoding='utf-8')
            note_tags = extract_hashtags(content)
            common_count = len(target_tags & note_tags)
            if common_count > 0:
                matches.append({
                    'file': str(file_path.resolve()),
                    'score': common_count
                })
        except Exception:
            continue
    # Sort by relevance (highest overlap first), then limit results
    matches.sort(key=lambda x: x['score'], reverse=True)
    return [m['file'] for m in matches[:limit]]

def process_links(args):
    # Load settings
    settings = ConfigHandler.load()
    if args.notes_dir:
        notes_dir = Path(args.notes_dir).expanduser()
    else:
        notes_dir_str = settings.get('notes_dir')
        if not notes_dir_str:
             print("Error: notes_dir not configured.", file=sys.stderr)
             sys.exit(1)
        notes_dir = Path(notes_dir_str).expanduser()

    recursion_depth = settings.get('recursion_depth', 2)
    max_results = settings.get('max_results', 10)

    source_file = Path(args.input).expanduser().resolve()
    if not source_file.exists():
        print(f"Error: Source note not found: {source_file}", file=sys.stderr)
        sys.exit(1)

    text_content = safe_read(source_file)

    # Gather linked documents via backlinks
    referenced_files = set()
    if notes_dir.exists():
        # get_backlinks_recursive returns dict {path: {depth, body}}
        raw_refs = get_backlinks_recursive(source_file, notes_dir, recursion_depth, max_results)
        for path in raw_refs.keys():
             referenced_files.add(str(path))
        print(f"Parsed {len(referenced_files)} linked files (depth={recursion_depth}, limit={max_results})", file=sys.stderr)
    else:
        print(f"Warning: Notes directory missing: {notes_dir}", file=sys.stderr)

    # Find notes with matching hashtags
    tag_matches = []
    if notes_dir.exists():
        source_tags = extract_hashtags(text_content)
        if source_tags:
            tag_matches = find_notes_by_tags(source_tags, notes_dir, source_file, limit=5)
            print(f"Discovered {len(tag_matches)} hashtag-matched files (seed tags: {sorted(source_tags)})", file=sys.stderr)

    # Merge all references, excluding the source note
    combined_paths = set(referenced_files)
    for f in tag_matches:
        combined_paths.add(f)

    # Remove source note explicitly if present
    if str(source_file) in combined_paths:
        combined_paths.remove(str(source_file))

    # Export as JSON array
    result_list = list(combined_paths)
    save_json(args.output, result_list)
    print(f'Saved {len(result_list)} entries to {args.output}', file=sys.stderr)

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True, help='Source note location')
    parser.add_argument('--output', required=True, help='Destination JSON file')
    parser.add_argument('--notes-dir', help='Custom notes directory path')
    arguments = parser.parse_args()
    process_links(arguments)

