# Guardian validation wrapper for AI-generated content
from .p0_kernel_core import validate_with_understanding

def check_candidate(context: dict, proposal: dict) -> dict:
    """Assess a proposed action or message against safety guidelines.
    context: operational metadata such as:
      {
        "channel": "moltx|clawchat|internal",
        "task": "post|reply|tool_call|memory_write",
        "user_intent": "description of user goal",
        "risk_tolerance": "low|medium|high"
      }
    proposal: {
      "content": "text of reply or description of intended action",
      "metadata": {... optional ...}
    }
    """
    text = proposal.get("content", "")
    assessment = validate_with_understanding(text, context)
    return assessment

def security_guard(fn):
    """Decorator to wrap a generation function with security checks.
    Example:
    @security_guard
    def produce_response(context, *args, **kwargs):
        return llm_call(...)
    """
    def protected(context, *args, **kwargs):
        raw_output = fn(context, *args, **kwargs)
        evaluation = check_candidate(context, {"content": raw_output})
        decision = evaluation.get("action", "permit")
        if decision == "permit":
            return raw_output
        if decision == "alert":
            explanation = evaluation.get("comprehension") or "Security system flagged this content as potentially hazardous."
            return f"{raw_output}\n\n[LYGO Security Alert]: {explanation}"
        if decision == "quarantine":
            return "[BLOCKED BY LYGO SECURITY: content failed Micro-Kernel validation]"
        # fallback / escalation path
        return "[LYGO SECURITY REQUIRES HUMAN REVIEW BEFORE TRANSMISSION]"
    return protected

