# Utility functions for handling key-value caches in transformer models
import gzip, pickle
from typing import Tuple
import torch

# Type alias for KV cache: tuple of (key_tensor, value_tensor) per layer
KVCache = Tuple[Tuple[torch.Tensor, torch.Tensor], ...]

def move_kv_to_cpu(past_key_values: KVCache) -> KVCache:
    """Convert all K and V tensors in the cache to CPU."""
    result = []
    for key_tensor, value_tensor in past_key_values:
        result.append((key_tensor.detach().cpu(), value_tensor.detach().cpu()))
    return tuple(result)

def move_kv_to_device(past_key_values: KVCache, target_device: str) -> KVCache:
    """Move all K and V tensors in the cache to specified device."""
    result = []
    for key_tensor, value_tensor in past_key_values:
        result.append((key_tensor.to(target_device), value_tensor.to(target_device)))
    return tuple(result)

# --------- Serialization functions ---------
def store_kv_pickle(filepath: str, kv_cache: KVCache) -> None:
    """Save KV cache to a file using standard pickle format."""
    with open(filepath, "wb") as file_handle:
        pickle.dump(kv_cache, file_handle)

def retrieve_kv_pickle(filepath: str) -> KVCache:
    """Load KV cache from a file using standard pickle format."""
    with open(filepath, "rb") as file_handle:
        return pickle.load(file_handle)

def store_kv_gzip(filepath: str, kv_cache: KVCache) -> None:
    """Save KV cache to a gzip-compressed file using pickle."""
    with gzip.open(filepath, "wb") as compressed_file:
        pickle.dump(kv_cache, compressed_file)

def retrieve_kv_gzip(filepath: str) -> KVCache:
    """Load KV cache from a gzip-compressed file using pickle."""
    with gzip.open(filepath, "rb") as compressed_file:
        return pickle.load(compressed_file)

def store_kv_torch(filepath: str, kv_cache: KVCache) -> None:
    """Save KV cache using PyTorch's native save function."""
    torch.save(kv_cache, filepath)

def retrieve_kv_torch(filepath: str) -> KVCache:
    """Load KV cache using PyTorch's native load function."""
    return torch.load(filepath, map_location="cpu")

def store_kv(filepath: str, kv_cache: KVCache, format_type: str = "pickle") -> None:
    """Generic function to save KV cache in various formats."""
    format_type = format_type.lower()
    if format_type == "pickle":
        store_kv_pickle(filepath, kv_cache)
    elif format_type == "gzip":
        store_kv_gzip(filepath, kv_cache)
    elif format_type == "torch":
        store_kv_torch(filepath, kv_cache)
    else:
        raise ValueError(f"Unsupported format: {format_type}")

def retrieve_kv(filepath: str, format_type: str = "pickle") -> KVCache:
    """Generic function to load KV cache in various formats."""
    format_type = format_type.lower()
    if format_type == "pickle":
        return retrieve_kv_pickle(filepath)
    elif format_type == "gzip":
        return retrieve_kv_gzip(filepath)
    elif format_type == "torch":
        return retrieve_kv_torch(filepath)
    else:
        raise ValueError(f"Unsupported format: {format_type}")

# --------- Pruning functionality ---------
def trim_kv_cache(kv_cache: KVCache, num_tokens_to_retain: int) -> KVCache:
    """Retain only the last `num_tokens_to_retain` tokens along the sequence dimension."""
    trimmed = []
    for key_tensor, value_tensor in kv_cache:
        # Slice the sequence length dimension (axis 2) to keep only recent tokens
        trimmed.append((
            key_tensor[:, :, -num_tokens_to_retain:, :],
            value_tensor[:, :, -num_tokens_to_retain:, :]
        ))
    return tuple(trimmed)

