from typing import ClassVar, List, Optional, Dict, Any
from pydantic import BaseModel
from app.ai.context.sections.base import ContextSection, xml_tag, xml_escape

class ToolCallRecord(BaseModel):
    call_index: int
    tool_identifier: str
    parameters: Dict[str, Any]
    time_stamp: str
    result_data: Dict[str, Any] = {}

class WidgetChangeRecord(BaseModel):
    widget_key: int
    time_stamp: str
    payload: Dict[str, Any]

class StepChangeRecord(BaseModel):
    step_key: int
    time_stamp: str
    payload: Dict[str, Any]

class VisualizationChangeRecord(BaseModel):
    viz_key: str
    time_stamp: str
    payload: Dict[str, Any]

class ObservationsSection(ContextSection):
    tag_name: ClassVar[str] = "recent_tool_executions"
    max_records: int = 5
    call_count: int = 0
    tool_results: List[ToolCallRecord] = []
    widget_changes: List[WidgetChangeRecord] = []
    step_changes: List[StepChangeRecord] = []
    visualization_changes: List[VisualizationChangeRecord] = []
    stored_artifacts: Dict[str, Any] = {}

    def render(self) -> str:
        output_lines: List[str] = []

        # Process recent tool observations (last N records)
        for record in self.tool_results[-self.max_records:]:
            record_lines = []
            summary_text = record.result_data.get("summary") if record.result_data else None

            if summary_text:
                record_lines.append(xml_escape(summary_text))

                error_info = record.result_data.get("error")
                if error_info:
                    if isinstance(error_info, dict) and error_info.get("message"):
                        record_lines.append(f"Error: {xml_escape(error_info['message'])}")
                    elif isinstance(error_info, str):
                        record_lines.append(f"Error: {xml_escape(error_info)}")

            content_body = "\n".join(record_lines)
            output_lines.append(
                xml_tag("tool_execution", content_body, {"tool": record.tool_identifier})
            )

        # Widgets summary section (optional)
        if self.widget_changes:
            output_lines.append(
                xml_tag("widgets_created_or_updated", str(len(self.widget_changes)))
            )

        # Visualizations summary section (optional)
        if self.visualization_changes:
            output_lines.append(
                xml_tag("visualizations_created_or_updated", str(len(self.visualization_changes)))
            )

        return xml_tag(self.tag_name, "\n".join(output_lines))

