# Modified version of TextMessage class with renamed variables and restructured logic
import re
from dataclasses import dataclass, field, fields
from datetime import datetime
from typing import Self
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.output.epstein_highlighter import highlighter
from epstein_files.output.highlight_config import get_style_for_name
from epstein_files.output.rich import TEXT_LINK
from epstein_files.people.names import (ANTHONY_SCARAMUCCI, JEFFREY_EPSTEIN, STEVE_BANNON,
     UNKNOWN, Name, extract_last_name)
from epstein_files.util.constant.strings import TIMESTAMP_DIM
from epstein_files.util.helpers.data_helpers import AMERICAN_DATE_FORMAT
from epstein_files.util.logging import logger

# List of known Epstein-related identifiers
KNOWN_EPSTEIN_SENDERS = ['e:', 'e:redacted@example.invalid']
REGEX_PHONE_PATTERN = re.compile(r'^[\d+]+.*')
POSSIBLE_MARKER = ' (?)'
SHOW_LAST_NAME_ONLY_LIST = [
    ANTHONY_SCARAMUCCI,
    JEFFREY_EPSTEIN,
    STEVE_BANNON,
]

@dataclass(kw_only=True)
class TextMessage:
    """Class representing a single iMessage text message."""
    sender: Name
    sender_label: str = ''
    is_sender_verified: bool = False
    content: str
    date_str: str

    def __post_init__(self):
        # Normalize sender if matches known Epstein identifiers
        self.sender = JEFFREY_EPSTEIN if self.sender in KNOWN_EPSTEIN_SENDERS else self.sender

        # Determine display name for sender
        if not self.sender:
            self.sender_label = UNKNOWN
        elif self.sender in SHOW_LAST_NAME_ONLY_LIST and not self.sender_label:
            self.sender_label = extract_last_name(self.sender)
        else:
            self.sender_label = self.sender_label or self.sender

        # Add uncertainty marker if sender isn't confirmed or is not Jeffrey Epstein
        if not self.is_sender_verified and self.sender is not None and self.sender != JEFFREY_EPSTEIN:
            self.sender_label += POSSIBLE_MARKER

        # Process text based on whether it's a link
        if self.is_url():
            self.content = self.content.replace('\n', '').replace(' ', '_')
        else:
            self.content = self.content.replace('\n', ' ')

    @property
    def sort_key_datetime(self) -> datetime:
        try:
            return self.extract_timestamp()
        except Exception as e:
            return FALLBACK_TIMESTAMP

    def is_url(self) -> bool:
        return self.content.startswith('http')

    def extract_timestamp(self) -> datetime:
        return datetime.strptime(self.date_str, AMERICAN_DATE_FORMAT)

    def formatted_time_display(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            time_str = site_config.format_text_msg_time(self.extract_timestamp())
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            time_str = self.date_str
        return Text(f"[{time_str}]", style=TIMESTAMP_DIM)

    def _content_segment(self) -> Text:
        if self.is_url():
            return Text.from_markup(f"[link={self.content}]{self.content}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.content)

    def __eq__(self, other: Self):
        return self.sender == other.sender and \
               self.content == other.content and \
               self.date_str == other.date_str and \
               self.sender_label == other.sender_label

    def __rich__(self) -> Text:
        time_txt = self.formatted_time_display().append(' ')
        style_for_sender = get_style_for_name(self.sender_label if self.sender_label.startswith('+') else self.sender)
        name_txt = Text(self.sender_label, style=style_for_sender)
        return Text('').append(time_txt).append(name_txt).append(': ', style='dim').append(self._content_segment())

    def __repr__(self) -> str:
        attributes = []
        append_attr = lambda k, v: attributes.append(f"{k}={v}")

        for _field in sorted(fields(self), key=lambda f: f.name):
            attr_name = _field.name
            attr_value = getattr(self, attr_name)

            # Skip redundant author_str representation when full name is available
            if attr_name == 'sender_label' and self.sender and self.sender_label.startswith(str(attr_value)):
                continue
            elif isinstance(attr_value, str):
                append_attr(attr_name, f'"{attr_value}"')
            else:
                append_attr(attr_name, attr_value)

        return f"{type(self).__name__}(" + ', '.join(attributes) + ')'

