class FeishuException(Exception):
    """Base exception class for all Feishu-related issues."""

    def __init__(self, msg: str, code: str = None, extra_info: dict = None):
        super().__init__(msg)
        self.msg = msg
        self.code = code
        self.extra_info = extra_info or {}

class FeishuAuthException(FeishuException):
    """Raised when authentication with Feishu API fails."""
    pass

class FeishuApiException(FeishuException):
    """General exception for Feishu API errors."""
    pass

class FeishuResourceNotFoundException(FeishuException):
    """Raised when a requested resource is not found (HTTP 404)."""
    pass

class FeishuAccessDeniedException(FeishuException):
    """Raised when access to a resource is denied (HTTP 403)."""
    pass

class FeishuTooManyRequestsException(FeishuException):
