# Viewer compatibility blueprint for /viewer routes
from __future__ import annotations
import os
from typing import Any
from flask import Blueprint, Response, redirect, request

def generate_viewer_blueprint() -> Blueprint:
    """Generate the viewer compatibility blueprint for /viewer routes."""
    bp = Blueprint(
        "graph_viewer",
        __name__,
        url_prefix="/viewer",
    )

    def _get_viewer_endpoint() -> str:
        return (os.environ.get("GRAPH_VIEWER_URL") or "").strip().rstrip("/")

    def _unavailable_error_response() -> Response:
        return Response(
            "Graph Viewer URL is not configured. Set GRAPH_VIEWER_URL.",
            status=503,
            mimetype="text/plain",
        )

    def _is_static_resource(path: str) -> bool:
        if not path:
            return False
        if path.startswith("assets/"):
            return True
        _, ext = os.path.splitext(path)
        return ext.lower() in {
            ".js",
            ".css",
            ".svg",
            ".png",
            ".jpg",
            ".jpeg",
            ".webp",
            ".ico",
            ".json",
            ".txt",
            ".map",
            ".woff",
            ".woff2",
            ".ttf",
        }

    def _construct_redirect_url(endpoint: str, route: str) -> str:
        clean_route = route.lstrip("/")
        target = f"{endpoint}/{clean_route}" if clean_route else endpoint
        query_string = request.query_string.decode("utf-8", errors="ignore")
        return f"{target}?{query_string}" if query_string else target

    def _generate_bootstrap_page(endpoint: str, route: str) -> str:
        clean_endpoint = f"{endpoint}/"
        clean_route = route.lstrip("/")
        # Minimal HTML template; hash preserved on client side.
        return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width,initial-scale=1" />
    <title>Redirecting to Graph Viewer...</title>
  </head>
  <body>
    <p>Redirecting to Graph Viewer...</p>
    <script>
      (function () {{
        const base = "{clean_endpoint}";
        const relPath = "{clean_route}";
        const target = new URL(relPath, base);
        const incoming = new URLSearchParams(window.location.search);
        incoming.forEach((value, key) => target.searchParams.set(key, value));
        if (!target.searchParams.has("server")) {{
          target.searchParams.set("server", window.location.origin);
        }}
        window.location.replace(target.toString() + window.location.hash);
      }})();
    </script>
  </body>
</html>
"""

    @bp.route("/", defaults={"route": ""})
    @bp.route("/<path:route>")
    def handle_viewer_request(route: str) -> Any:
        """Handle redirection or bootstrap to standalone graph viewer service."""
        endpoint = _get_viewer_endpoint()
        if not endpoint:
            return _unavailable_error_response()

        if _is_static_resource(route):
            return redirect(_construct_redirect_url(endpoint, route), code=302)

        html_content = _generate_bootstrap_page(endpoint, route)
        return Response(html_content, status=200, mimetype="text/html")

    return bp

def check_viewer_status() -> bool:
    """Determine whether the graph viewer compatibility route is active."""
    return os.environ.get("ENABLE_GRAPH_VIEWER", "true").lower() in ("true", "1", "yes")

