# Register and manage advantage functions and policy losses for RL algorithms
from functools import wraps
from typing import Callable, Optional
import torch
from rlinf.algorithms.utils import (
    compute_scores,
    postprocess_embodied_advantages_results,
    postprocess_loss_metrics,
    postprocess_reasoning_advantages_results,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

ADVANTAGE_REGISTRY: dict[str, Callable] = {}

def register_advantage_function(name: str):
    """Decorator to register an advantage computation function."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        ADVANTAGE_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def fetch_advantage_function(name: str) -> Callable:
    """Retrieve a registered advantage function by name."""
    if name.lower() not in ADVANTAGE_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' is not registered. Available options: {list(ADVANTAGE_REGISTRY.keys())}"
        )
    return ADVANTAGE_REGISTRY[name.lower()]

LOSS_REGISTRY: dict[str, Callable] = {}

def register_policy_loss_function(name: str):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        LOSS_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def retrieve_policy_loss_function(name: str):
    if name not in LOSS_REGISTRY:
        raise ValueError(f"Loss function '{name}' is not registered")
    return LOSS_REGISTRY[name]

def compute_actor_loss(**kwargs) -> tuple[torch.Tensor, dict]:
    """
    Unified actor loss computation entry point.
    """
    loss_identifier = kwargs["loss_type"]
    loss_function = retrieve_policy_loss_function(loss_identifier)
    environment_type = kwargs["task_type"]

    if environment_type == "embodied":
        kwargs = preprocess_loss_inputs(**kwargs)

    loss_value, metric_data = loss_function(**kwargs)

    if environment_type == "embodied":
        metric_data = postprocess_loss_metrics(metric_data)

    return loss_value, metric_data

def compute_advantage_and_returns(**kwargs) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified entry for computing advantages and returns.
    Accepts variable keyword arguments, preprocesses them as needed, then dispatches
    to the appropriate algorithm via registry.
    """
    advantage_type = kwargs["adv_type"]
    algorithm_fn = fetch_advantage_function(advantage_type)
    environment_type = kwargs["task_type"]

    if environment_type == "embodied":
        kwargs = preprocess_embodied_advantages_inputs(**kwargs)
        if advantage_type != "gae":
            kwargs = compute_scores(**kwargs)

        advantages, returns = algorithm_fn(**kwargs)
        result = postprocess_embodied_advantages_results(
            advantages=advantages, returns=returns, **kwargs
        )
    else:
        # reasoning tasks
        kwargs = preprocess_reasoning_advantages_inputs(**kwargs)
        advantages, returns = algorithm_fn(**kwargs)
        result = postprocess_reasoning_advantages_results(advantages, returns)

    return result

# Custom judge for environment service evaluation
from ajet.task_judge.base_judge import BaseJudge
from ajet.workflow import WorkflowOutput, WorkflowTask

class EnvServiceJudge(BaseJudge):
    def __init__(self, settings):
        self.settings = settings

    def evaluate_performance(self, task: WorkflowTask, result: WorkflowOutput) -> tuple:
        base_score = 0.0
        environment = task.gym_env
        base_score = environment.evaluate(task.episode_uuid, params={"sparse": False})

        if base_score >= 1:
            success_flag = True
        else:
            success_flag = False

        if success_flag:
            final_score = 1.0 + base_score * 0.5
        else:
            final_score = 0.0 + base_score * 0.5

        return final_score, success_flag

