# Memcache-based distributed backend implementation for Ascend devices
from enum import Enum
import torch
from vllm.config import ParallelConfig
from vllm.logger import logger
from vllm_ascend.distributed.kv_transfer.kv_pool.ascend_store.backend.backend import Backend
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type

class MmcOperation(Enum):
    L2G_COPY = 0
    G2L_COPY = 1
    G2H_COPY = 2
    H2G_COPY = 3

class AscendMemcacheBackend(Backend):
    def __init__(self, parallel_config: ParallelConfig):
        try:
            from memcache_hybrid import DistributedObjectStore  # type: ignore
        except ImportError as err:
            raise ImportError(
                "Required module 'memcache_hybrid' not found. "
                "Please install it following the guide at "
                "https://gitee.com/ascend/memfabric_hybrid "  # noqa: E501
                "to enable MemcacheConnector functionality."
            ) from err

        try:
            chip_version = get_ascend_device_type()
            if chip_version in {AscendDeviceType.A2}:
                import torch
                from vllm.distributed import get_world_group
                dummy_tensor = torch.zeros(1, device="npu")
                gather_result = [torch.empty_like(dummy_tensor) for _ in range(torch.distributed.get_world_size())]
                torch.distributed.all_gather(gather_result, dummy_tensor, group=get_world_group().device_group)
                self.local_rank = parallel_config.rank
                self.object_store = DistributedObjectStore()
                init_status = self.object_store.init(self.local_rank)
                assert init_status == 0
            else:
                self.local_rank = parallel_config.rank
                self.object_store = DistributedObjectStore()
                init_status = self.object_store.init(self.local_rank)
                assert init_status == 0
        except ValueError as config_err:
            logger.error("Failed to load hardware configuration: %s", config_err)
            raise
        except RuntimeError as runtime_err:
            logger.error("Runtime initialization error: %s", runtime_err)
            raise

    def set_npu_device(self):
        target_device = torch.device(f"npu:{self.local_rank}")
        torch.npu.set_device(target_device)

    def register_memory_buffers(self, buffer_ptrs: list[int], buffer_sizes: list[int]):
        chip_version = get_ascend_device_type()
        if chip_version in {AscendDeviceType.A2}:
            for ptr, size in zip(buffer_ptrs, buffer_sizes):
                self.object_store.register_buffer(ptr, size)
        else:
            return

    def check_key_existence(self, key_list: list[str]) -> list[int]:
        return self.object_store.batch_is_exist(key_list)

    def retrieve_data(self, keys: list[str], dest_addresses: list[list[int]], lengths: list[list[int]]):
        try:
            results = self.object_store.batch_get_into_layers(keys, dest_addresses, lengths, MmcOperation.G2L_COPY.value)
            for status_code in results:
                if status_code != 0:
                    logger.error(f"KV retrieval failed for keys {keys}, status: {results}")
        except Exception as io_err:
            logger.error(f"Error during data retrieval for keys {keys}: {io_err}")

    def store_data(self, keys: list[str], source_addresses: list[list[int]], lengths: list[list[int]]):
        try:
            results = self.object_store.batch_put_from_layers(keys, source_addresses, lengths, MmcOperation.L2G_COPY.value)
            for status_code in results:
                if status_code != 0:
                    logger.error(f"KV storage failed for keys {keys}, status: {results}")
        except Exception as io_err:
            logger.error(f"Error during data storage for keys {keys}: {io_err}")

