# Dictionary to store API information
api_metadata = {}
DEFAULT_CONNECTION_TIMEOUT = 60
DEFAULT_SOCKET_READ_TIMEOUT = 60

class CoreTrait(Service):
    def __init__(self, config=None):
        if config is None:
            config = {}
        self.config = config

        # Ensure region is provided in configuration
        if "region" not in config:
            raise ValueError("region parameter is required")

        region = config.get("region", "")
        self.service_info = CoreTrait.get_service_info(region)
        self.api_metadata = CoreTrait.get_api_info()

        # Handle authentication credentials if provided
        if config.get("access_key", None) and config.get("secret_key", None):
            self.set_access_key(config["access_key"])
            self.set_secret_key(config["secret_key"])

        # Handle session token if provided
        if config.get("session_token", None):
            self.set_session_token(config["session_token"])

        # Initialize parent Service class with service and API info
        super(CoreTrait, self).__init__(self.service_info, self.api_metadata)

    @staticmethod
    def get_service_info(
        region,
    ):
        return ServiceInfo(
            f"vke.{region}.volcengineapi.com",
            {"Accept": "application/json", "x-tt-mcp": "volc"},
            Credentials("", "", "vke", region),
            DEFAULT_CONNECTION_TIMEOUT,
            DEFAULT_SOCKET_READ_TIMEOUT,
            "https",
        )

    @staticmethod
    def get_api_info():
        return api_metadata

    def set_api_metadata(self, api_info):
        self.api_metadata = {**self.api_metadata, **api_info}
        return

    def mcp_get_request(self, action, parameters={}, doseq=0):
        response = self.get(action, parameters, doseq)
        if response == "":
            raise Exception("%s: empty response received" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

    def mcp_post_request(self, action, parameters={}, body={}):
        response = self.json(action, parameters, body)
        if response == "":
            raise Exception("%s: empty response received" % action)
        response_json = json.loads(json.dumps(response))
        return response_json

# Custom logger class for QTextEdit widget
import logging
from PySide6.QtCore import Signal, QObject

class CustomLogHandler(logging.Handler, QObject):
    log_signal = Signal(str, str)

    def __init__(self, text_edit_widget):
        super().__init__()
        QObject.__init__(self)
        self.text_widget = text_edit_widget
        self.log_signal.connect(self.handle_log_entry)

    def emit(self, record):
        formatted_message = self.format(record)
        self.log_signal.emit(record.levelname, formatted_message)

    def handle_log_entry(self, level_name, message):
        text_color = "#D3D3D3"
        if level_name == "INFO":
            text_color = "#2ECC71"
        elif level_name == "WARNING":
            text_color = "#F1C40F"
        elif level_name == "ERROR":
            text_color = "#E74C3C"
        elif level_name == "DEBUG":
            text_color = "#95A5A6"

        scrollbar = self.text_widget.verticalScrollBar()
        is_scrolled_to_bottom = scrollbar.value() >= (scrollbar.maximum() - 15)

        self.text_widget.append(f'<span style="color:{text_color}; font-family:Monospace; font-size:11pt;">{message}</span>')

        if is_scrolled_to_bottom:
            scrollbar.setValue(scrollbar.maximum())

