# Modified version: renamed variables, reordered logic slightly, updated comments
from typing import IO, Dict, List, Mapping, Optional, Tuple, Union, cast

# File typing inspired by the flexibility of types within the httpx library
# https://github.com/encode/httpx/blob/master/httpx/_types.py
FileData = Union[IO[bytes], bytes, str]
FileParam = Union[
    # file (or bytes)
    FileData,
    # (filename, file (or bytes))
    Tuple[Optional[str], FileData],
    # (filename, file (or bytes), content_type)
    Tuple[Optional[str], FileData, Optional[str]],
    # (filename, file (or bytes), content_type, headers)
    Tuple[
        Optional[str],
        FileData,
        Optional[str],
        Mapping[str, str],
    ],
]

def transform_file_dict_to_httpx_format(
    mapping: Dict[str, Union[FileParam, List[FileParam]]],
) -> List[Tuple[str, FileParam]]:
    """
    Converts a dictionary of files into a list of tuples suitable for HTTPX.
    Each tuple contains the field name and the corresponding file object.
    While HTTPX typically expects a dict, using a list allows sending multiple
    files under the same field name — this approach works universally.
    Reference: https://github.com/encode/httpx/pull/1032
    """
    result = []
    for field_name, file_obj in mapping.items():
        if isinstance(file_obj, list):
            for item in file_obj:
                result.append((field_name, item))
        else:
            result.append((field_name, file_obj))
    return result

def ensure_content_type(*, file: FileParam, fallback_content_type: str) -> FileParam:
    """
    Determines the appropriate content type for a file parameter.
    If no content type is specified, it falls back to the provided default.
    """
    if isinstance(file, tuple):
        length = len(file)
        if length == 2:
            filename, data = cast(Tuple[Optional[str], FileData], file)  # type: ignore
            return (filename, data, fallback_content_type)
        elif length == 3:
            filename, data, declared_type = cast(Tuple[Optional[str], FileData, Optional[str]], file)  # type: ignore
            final_type = declared_type if declared_type else fallback_content_type
            return (filename, data, final_type)
        elif length == 4:
            filename, data, declared_type, headers = cast(  # type: ignore
                Tuple[Optional[str], FileData, Optional[str], Mapping[str, str]], file
            )
            final_type = declared_type if declared_type else fallback_content_type
            return (filename, data, final_type, headers)
        else:
            raise ValueError(f"Unexpected tuple size: {length}")
    return (None, file, fallback_content_type)

