# Health check workflow implementation
from typing import TypedDict
from langgraph.graph import END, START, StateGraph

class WorkflowState(TypedDict):
    value: int

def increment(state: WorkflowState) -> WorkflowState:
    return {"value": state.get("value", 0) + 1}

def double_value(state: WorkflowState) -> WorkflowState:
    return {"value": state.get("value", 0) * 2}

def decrease_by_three(state: WorkflowState) -> WorkflowState:
    return {"value": state.get("value", 0) - 3}

def create_pipeline():
    pipeline = StateGraph(WorkflowState)
    pipeline.add_node("increment", increment)
    pipeline.add_node("double_value", double_value)
    pipeline.add_node("decrease_by_three", decrease_by_three)
    pipeline.add_edge(START, "increment")
    pipeline.add_edge("increment", "double_value")
    pipeline.add_edge("double_value", "decrease_by_three")
    pipeline.add_edge("decrease_by_three", END)
    return pipeline.compile()

if __name__ == "__main__":
    pipeline = create_pipeline()
    output = pipeline.invoke({"value": 5})
    print(f"Health pipeline result: {output['value']} (expected 7)")

