# Modified version of the original code with renamed variables and reordered statements
from typing import ClassVar, List, Optional, Dict, Any
from pydantic import BaseModel
from app.ai.context.sections.base import ContextSection, xml_tag, xml_escape

class WidgetData(BaseModel):
    widget_identifier: str
    widget_label: str
    widget_category: str
    process_id: str
    process_title: str
    record_count: int = 0
    field_names: List[str] = []
    schema_model: Optional[Dict[str, Any]] = None
    metrics: Dict[str, Any] = {}
    sample_data: Optional[str] = None

class WidgetsContainer(ContextSection):
    tag_name: ClassVar[str] = "widgets"
    entries: List[WidgetData] = []

    def render(self) -> str:
        sections: List[str] = []

        for item in self.entries or []:
            content_parts = []

            # Add basic metadata
            content_parts.append(xml_tag("type", xml_escape(item.widget_category)))
            content_parts.append(xml_tag("step", xml_escape(item.process_title), {"id": item.process_id}))
            content_parts.append(xml_tag("rows", str(item.record_count)))

            # Conditionally add optional fields
            if item.field_names:
                content_parts.append(
                    xml_tag("columns", ", ".join(xml_escape(f) for f in item.field_names))
                )

            if item.schema_model is not None:
                content_parts.append(xml_tag("data_model", xml_escape(str(item.schema_model))))

            if item.metrics:
                content_parts.append(xml_tag("stats", xml_escape(str(item.metrics))))

            if item.sample_data:
                content_parts.append(xml_tag("data_preview", xml_escape(item.sample_data)))

            # Wrap widget content
            sections.append(
                xml_tag("widget", "\n".join(content_parts), {
                    "id": item.widget_identifier, 
                    "title": item.widget_label
                })
            )

        return xml_tag(self.tag_name, "\n\n".join(sections))

# PDF text extraction and metadata retrieval tool
import sys
import argparse
import json
import pymupdf

def get_pdf_content(file_path, limit_pages=None):
    try:
        document = pymupdf.open(file_path)
        content = ""
        for idx, page in enumerate(document):
            if limit_pages and idx >= int(limit_pages):
                break
            content += page.get_text() + "\n"
        return content
    except Exception as error:
        return f"Error: {str(error)}"

def retrieve_document_info(file_path):
    try:
        document = pymupdf.open(file_path)
        return document.metadata
    except Exception as error:
        return {"error": str(error)}

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Process PDF files")
    parser.add_argument("action", choices=["extract", "metadata"])
    parser.add_argument("source_file")
    parser.add_argument("--page_limit", type=int, default=None)

    arguments = parser.parse_args()

    if arguments.action == "extract":
        print(get_pdf_content(arguments.source_file, arguments.page_limit))
    elif arguments.action == "metadata":
        print(json.dumps(retrieve_document_info(arguments.source_file), indent=2))

# Import required libraries
import mlx.core as mx
import math

def softmax_function(x: mx.array, axis_dim: int) -> mx.array:
    # Compute softmax using built-in function
    return mx.softmax(x, axis=axis_dim)

def linear_layer(
    input_tensor: mx.array,
    weight_matrix: mx.array,
    bias_vector: mx.array | None = None,
) -> mx.array:
    if bias_vector is not None:
        return mx.matmul(input_tensor, weight_matrix.T) + bias_vector
    else:
        return mx.matmul(input_tensor, weight_matrix.T)

def scaled_sigmoid_unit(x: mx.array) -> mx.array:
    return x / (1 + mx.exp(-x))

# Modified version with Type I clone transformations (variable renaming, literal changes, statement reordering)
from typing import Dict, Any
import time
import torch
from torch.distributed.tensor import DTensor, Replicate
from .constants import AVG_PER_STEP_TOKEN_NUM, GLOBAL_STEP_TOKEN_NUM
from .device import get_device_type, get_torch_device

def move_params_to_device(model, target_device: torch.device | str | int | None, apply_recursively: bool = True):
    """Transfer the parameters and buffers to the designated device without duplicating memory if already present.
    Args:
        module: The module whose parameters and buffers may be relocated.
        target_device: The target device for parameters and buffers. If `None`, default device is used.
        apply_recursively: Whether submodules' parameters and buffers should also be relocated.
    Returns:
        The (possibly) relocated module.
    """
    temp_device = torch.empty((), device=target_device).device
    return model._apply(
        lambda tensor: torch.empty_like(tensor, device=temp_device) if tensor.device != temp_device else tensor,
        recurse=apply_recursively,
    )

def convert_tensor_to_dtensor(local_tensor: torch.Tensor, mesh, placement_list):
    replicate_placements = [Replicate() for _ in range(mesh.ndim)]
    initial_dtensor = DTensor.from_local(local_tensor=local_tensor, device_mesh=mesh, placements=replicate_placements)
    final_dtensor = initial_dtensor.redistribute(device_mesh=mesh, placements=placement_list)
    return final_dtensor

def initialize_model_parameters(model):
    deferred_initializations = []

    def _setup_before_init():
        # Identify parameters that cannot be initialized as DTensors; restore full tensors and re-shard after init
        for layer_name, submodule in model.named_modules():
            setattr(submodule, "_is_initialized", False)
            if getattr(submodule, "_is_hf_initialized", False):
                submodule._is_hf_initialized = False
            if isinstance(submodule, torch.nn.Embedding) and submodule.padding_idx is not None:
                deferred_initializations.append([layer_name, submodule.weight.data.device_mesh, submodule.weight.data.placements])
                restored_weight = torch.empty(submodule.weight.data.shape, device=submodule.weight.device)
                submodule.weight = torch.nn.Parameter(restored_weight, requires_grad=submodule.weight.requires_grad)

    def _complete_after_init():
        if not deferred_initializations:
            return
        for target_layer, mesh, placements in deferred_initializations:
            for name, submodule in model.named_modules():
                if name != target_layer:
                    continue
                if isinstance(submodule, torch.nn.Embedding) and submodule.padding_idx is not None:
                    dtensor_weight = convert_tensor_to_dtensor(submodule.weight.data, mesh, placements)
                    submodule.weight = torch.nn.Parameter(dtensor_weight, requires_grad=submodule.weight.requires_grad)

    _setup_before_init()
    model.init_weights()
    _complete_after_init()

def prepare_batch_for_device(batch_data: Dict[str, Any], dtype_float: str = None):
    updated_batch = dict()
    for key, value in batch_data.items():
        if key in [AVG_PER_STEP_TOKEN_NUM, GLOBAL_STEP_TOKEN_NUM]:
            updated_batch[key] = value.to(device=get_device_type())
        elif isinstance(value, torch.Tensor):
            target_dtype = dtype_float if torch.is_floating_point(value) else None
            updated_batch[key] = value.to(device=get_device_type(), dtype=target_dtype)
        elif isinstance(value, list) and all(isinstance(item, torch.Tensor) for item in value):
            updated_batch[key] = [
                item.to(device=get_device_type(),
                        dtype=dtype_float if torch.is_floating_point(item) else None)
                for item in value
            ]
    return updated_batch

def measure_time(sync_barrier=False):
    if sync_barrier:
        torch.distributed.barrier()
    get_torch_device().synchronize()
    return time.time()

def check_npu_support():
    try:
        import torch_npu
        return torch_npu.npu.is_available()
    except ImportError:
        return False

class SingleInstance(type):
    """Metaclass enforcing singleton pattern for ParallelState class."""
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            new_instance = super().__call__(*args, **kwargs)
            cls._instances[cls] = new_instance
        return cls._instances[cls]

# Feature Flags API endpoints for admin-only management
from fastapi import APIRouter, Depends, HTTPException, Query, Body, status
from typing import List, Optional, Dict, Any
from ..services.feature_flags import get_feature_service
from ..routers.auth import require_admin
from ..models import User

router = APIRouter(prefix="/flags", tags=["Feature Flags"])

@router.get("/")
async def retrieve_all_flags(current_user: User = Depends(require_admin)):
    """Retrieve all feature flags stored in Consul."""
    service = get_feature_service()
    return service.fetch_all_flags()

@router.post("/")
async def add_or_modify_flag(
    feature_name: str = Query(...),
    settings: Dict[str, Any] = Body(...),  # {enabled: bool, rollout_percentage: int, tenant_overrides: {...}}
    current_user: User = Depends(require_admin)
):
    """Admin only: Modify, enable/disable or configure rollout/overrides for a specific feature flag."""
    service = get_feature_service()

    # Validate the settings object
    if not isinstance(settings.get('enabled'), bool):
         raise HTTPException(status_code=400, detail="'enabled' must be boolean")

    result = service.update_flag(feature_name, settings)
    if not result:
         raise HTTPException(status_code=500, detail="Failed to write to Consul")

    return {"message": f"Flag '{feature_name}' updated successfully.", "settings": settings}

@router.delete("/")
async def remove_flag(
    feature_name: str = Query(...),
    current_user: User = Depends(require_admin)
):
    """Admin only: Delete a feature flag completely."""
    service = get_feature_service()
    try:
        service.client.kv.delete(f"soulsense/features/{feature_name}")
        service.cache.flush()
        return {"message": f"Flag '{feature_name}' removed."}
    except Exception as e:
         raise HTTPException(status_code=500, detail=str(e))

