import operator

# Define supported operators mapping to their functions
MATH_OPS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}

def perform_calculation(x, y, operation):
    """Perform safe calculation using operator module"""
    if operation not in MATH_OPS:
        raise ValueError(f"Unsupported operation: {operation}")
    return MATH_OPS[operation](float(x), float(y))

def check_number_input(input_val):
    """Check if input can be converted to a number"""
    try:
        float(input_val)
        return True
    except ValueError:
