# Load golden dataset from JSON files in a directory
import json
from pathlib import Path

def load_golden_dataset(path: Path | str) -> list[dict]:
    """Loads all test cases from .json files in a specific golden dataset directory."""
    path = Path(path)
    test_cases = []
    if not path.exists() or not path.is_dir():
        return test_cases
    for file_path in path.glob("*.json"):
        try:
            with open(file_path, encoding="utf-8") as file:
                content = json.load(file)
                if isinstance(content, dict) and "test_cases" in content:
                    test_cases.extend(content["test_cases"])
                elif isinstance(content, list):
                    test_cases.extend(content)
                else:
                    test_cases.append(content)
        except Exception as error:
            print(f"Error loading {file_path}: {error}")
    return test_cases

