# A simple stack implementation using list as base
from typing import List, TypeVar
T = TypeVar("T")

class Stack(List[T]):
    """A lightweight wrapper around Python's built-in list for stack operations."""

    @property
    def peek(self) -> T:
        """Return the top element without removing it."""
        return self[-1]

    def push(self, value: T) -> None:
        """Add an element to the top of the stack."""
        self.append(value)

