# Script to inspect Linux GUI application UI tree using dogtail
import sys
import argparse
from dogtail.tree import root

def traverse_node(node, level=0, limit_depth=10):
    if level > limit_depth:
        return
    try:
        label = node.name.strip()
        role_type = node.roleName
        # Display only nodes with labels or interactive components
        if label or role_type in ['push button', 'entry', 'menu item', 'toggle button', 'check box']:
            print('  ' * level + f'<{role_type}> {label}')
        for child_node in node.children:
            traverse_node(child_node, level + 1, limit_depth)
    except:
        pass

def entry_point():
    parser = argparse.ArgumentParser(description="Inspect Linux GUI application UI tree.")
    parser.add_argument("program_name", help="Name of the application to inspect.")
    parser.add_argument("--max-depth", type=int, default=15, help="Maximum depth to traverse.")
    arguments = parser.parse_args()
    try:
        app_instance = root.application(arguments.program_name)
        print(f"Dump for application: {arguments.program_name}")
        traverse_node(app_instance, limit_depth=arguments.max_depth)
    except Exception as error:
        print(f"Error: Could not find or inspect application '{arguments.program_name}'. {error}")

if __name__ == "__main__":
    entry_point()

import logging
from contextlib import contextmanager
from functools import wraps
from time import time
import torch.distributed
from .utils import SingletonPattern
__all__ = ["Stopwatch", "stopwatch"]
log = logging.getLogger(__name__)

class Stopwatch(metaclass=SingletonPattern):
    def __init__(self):
        self.recorded_times = {}
        self.active_timers = {}

    def begin(self, label):
        assert label not in self.active_timers, f"Stopwatch {label} is already running."
        self.active_timers[label] = time()
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            log.info(f"Stopwatch {label} started")

    def stop(self, label):
        assert label in self.active_timers, f"Stopwatch {label} was never started."
        duration = time() - self.active_timers[label]
        self.accumulate(label, duration)
        del self.active_timers[label]
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            log.info(f"Stopwatch {label} stopped (duration: {duration:.1f}s)")

    def clear(self, label=None):
        if label is None:
            self.recorded_times.clear()
        elif label in self.recorded_times:
            del self.recorded_times[label]

    def accumulate(self, label, duration):
        self.recorded_times[label] = self.recorded_times.get(label, 0) + duration

    def get_stats(self):
        return self.recorded_times

    @contextmanager
    def scope(self, label):
        self.begin(label)
        try:
            yield
        finally:
            self.stop(label)

def stopwatch(name_or_callable):
    """
    Can be used either as a decorator or a context manager:
    @stopwatch
    def task():
        ...
    or
    with stopwatch("operation_name"):
        ...
    """
    # Context manager usage
    if isinstance(name_or_callable, str):
        label = name_or_callable
        return Stopwatch().scope(label)

    func = name_or_callable
    @wraps(func)
    def decorated(*args, **kwargs):
        with Stopwatch().scope(func.__name__):
            return func(*args, **kwargs)
    return decorated

@contextmanager
def reverse_timer(label):
    Stopwatch().stop(label)
    try:
        yield
    finally:
        Stopwatch().begin(label)

