class LoggingCallback(pl.Callback):
    def on_batch_end(self, trainer, pl_module):
        learning_rates = {f"lr_group_{i}": param["lr"] for i, param in enumerate(trainer.optimizers[0].param_groups)}
        pl_module.logger.log_metrics(learning_rates)

    @rank_zero_only
    def _log_results(
        self, trainer: pl.Trainer, pl_module: pl.LightningModule, mode: str, save_outputs=True
    ) -> None:
        logger.info(f"***** {mode} results at step {trainer.global_step:05d} *****")
        metrics = trainer.callback_metrics
        trainer.logger.log_metrics({k: v for k, v in metrics.items() if k not in ["log", "progress_bar", "predictions"]})

        # Save logs to file
        output_dir = Path(pl_module.hparams.output_dir)
        if mode == "test":
            results_path = output_dir / "test_results.txt"
            generations_path = output_dir / "test_generations.txt"
        else:
            # Not saving intermediate generations by default
            results_path = output_dir / f"{mode}_results/{trainer.global_step:05d}.txt"
            generations_path = output_dir / f"{mode}_generations/{trainer.global_step:05d}.txt"
            results_path.parent.mkdir(exist_ok=True)
            generations_path.parent.mkdir(exist_ok=True)

        with open(results_path, "a+") as writer:
            for key in sorted(metrics):
                if key in ["log", "progress_bar", "predictions"]:
                    continue
                value = metrics[key]
                if isinstance(value, torch.Tensor):
                    value = value.item()
                line = f"{key}: {value:.6f}\n"
                writer.write(line)

        if not save_outputs:
            return

        if "predictions" in metrics:
            content = "\n".join(metrics["predictions"])
            generations_path.open("w+").write(content)

    @rank_zero_only
    def on_train_start(self, trainer, pl_module):
        try:
            total_params = pl_module.model.model.num_parameters()
        except AttributeError:
            total_params = pl_module.model.num_parameters()
        trainable_count = count_trainable_params(pl_module)
        # Convert to millions
        trainer.logger.log_metrics({"n_params": total_params, "mp": total_params / 1e6, "grad_mp": trainable_count / 1e6})

    @rank_zero_only
    def on_test_end(self, trainer: pl.Trainer, pl_module: pl.LightningModule):
        save_json(pl_module.metrics, pl_module.metrics_save_path)
        return self._log_results(trainer, pl_module, "test")

    @rank_zero_only
    def on_validation_end(self, trainer: pl.Trainer, pl_module):
        save_json(pl_module.metrics, pl_module.metrics_save_path)
        # Uncomment to save validation outputs
        # return self._log_results(trainer, pl_module, "valid")

def get_checkpoint_callback(output_dir, metric, save_top_k=1, lower_is_better=False):
    """Saves the best model based on validation metric."""
    if metric == "rouge2":
        exp = "{val_avg_rouge2:.4f}-{step_count}"
    elif metric == "bleu":
        exp = "{val_avg_bleu:.4f}-{step_count}"
    elif metric == "loss":
        exp = "{val_avg_loss:.4f}-{step_count}"
    else:
        raise NotImplementedError(
            f"seq2seq callbacks only support rouge2, bleu and loss, got {metric}, You can make your own by adding to"
            " this function."
        )
    checkpoint_callback = ModelCheckpoint(
        dirpath=output_dir,
        filename=exp,
        monitor=f"val_{metric}",
        mode="min" if "loss" in metric else "max",
        save_top_k=save_top_k,
    )
    return checkpoint_callback

def get_early_stopping_callback(metric, patience):
    return EarlyStopping(
        monitor=f"val_{metric}",
        mode="min" if "loss" in metric else "max",
        patience=patience,
        verbose=True,
    )

