# Modified version of CommandDispatcher with Type I clone transformations
from typing import List
from queue import Queue, Empty
from cosmos_rl.dispatcher.command import Command

class CommandDispatcher:
    """
    A simple in-memory command dispatcher for colocated mode.
    It uses Python Queue to simulate the command publish-subscribe mechanism.
    """
    def __init__(self, queue_names: List[str], is_master=True):
        """
        Initialize the CommandDispatcher.
        Args:
            queue_names (List[str]): List of command queue names.
            is_master (bool): Flag indicating if this instance is the master.
        """
        if is_master:
            self.queues = {name: Queue() for name in queue_names}
        else:
            self.queues = {}

    def send_command(self, payload, queue_name: str):
        """
        Send a command to the specified command queue.
        Args:
            payload : The packed command to send.
            queue_name (str): The name of the command queue.
        """
        if queue_name in self.queues:
            self.queues[queue_name].put(payload)

    def receive_commands(self, queue_name: str) -> List[dict]:
        """
        Receive commands from the specified command queue.
        Args:
            queue_name (str): The name of the command queue.
        Returns:
            list: A list of commands in msgpack format.
        """
        if queue_name not in self.queues:
            return []
        cmd_list = []
        if not self.queues[queue_name].empty():
            try:
                cmd = self.queues[queue_name].get_nowait()
                cmd_list.append(cmd)
            except Empty:
                pass
        return cmd_list

    def peek_command(self, queue_name: str) -> Command:
        """
        Peek at the front command from the specified command queue without removing it.
        Args:
            queue_name (str): The name of the command queue.
        Returns:
            Command: The front command if exists, else None.
        """
        if queue_name not in self.queues:
            return None
        if not self.queues[queue_name].empty():
            try:
                cmd_obj = self.queues[queue_name].queue[0]
                return Command.depack(cmd_obj)
            except Empty:
                pass
        return None

    def fetch_command(self, queue_name: str) -> Command:
        """
        Fetch and remove the front command from the specified command queue.
        Args:
            queue_name (str): The name of the command queue.
        Returns:
            Command: The fetched command if exists, else None.
        """
        if queue_name not in self.queues:
            return None
        if not self.queues[queue_name].empty():
            try:
                cmd_obj = self.queues[queue_name].get_nowait()
                return Command.depack(cmd_obj)
            except Empty:
                pass
        return None

