# Group items in an iterable by a key function, without requiring sorted input
from collections import defaultdict
from collections.abc import Callable, Iterable
from typing import Any
import torch

def group_items_by_key(items: Iterable[Any], key_func=None):
    """Group elements of an iterable using a key function (similar to itertools.groupby but unsorted)"""
    groups = defaultdict(list)
    for element in items:
        groups[key_func(element) if key_func is not None else element].append(element)
    return dict(groups)

# TODO FSDP can also utilize this utility
def split_named_parameters_by_size(named_parameters: Iterable[tuple[str, torch.Tensor]], max_chunk_size: int):
    return _partition_by_size(
        named_parameters,
        size_calculator=lambda param_pair: param_pair[1].nbytes,
        max_size=max_chunk_size,
    )

def _partition_by_size(data_items: Iterable[Any], size_calculator: Callable[[Any], int], max_size: int):
    current_bucket: list[Any] = []
    current_total_size = 0
    for item in data_items:
        item_size = size_calculator(item)
        if current_bucket and (current_total_size + item_size) >= max_size:
            yield current_bucket
            current_bucket = []
            current_total_size = 0
        current_bucket.append(item)
        current_total_size += item_size
    if current_bucket:
        yield current_bucket

