    CRED_ENVS,
    CRED_ENVS_DICT,
)

DEPLOYMENT_ENVIRONMENTS = ["prod", "dev", "stg"]

# Context manager to open a file or read from environment variable
@contextlib.contextmanager
def open_auth(credential_path: Optional[Any], file_mode: str):
    if not credential_path:
        logger.info(f"No credential file provided {credential_path}.")
        yield None
        return

    filename = credential_path.split("/")[-1].split(".")[0]
    if not filename:
        raise ValueError(f"Could not parse into env var: {credential_path}")

    env_var_name = f"PROD_{filename.upper()}"

    if CRED_ENVS.APP_ENV in DEPLOYMENT_ENVIRONMENTS and env_var_name in CRED_ENVS_DICT:
        object_storage_config = get_credentials_from_environment(env_var_name)
        logger.info(f"using ENV vars for {env_var_name}")
        yield object_storage_config
    else:
        logger.info(f"using credential file: {credential_path}")
        with open(credential_path, file_mode) as file_handle:
            yield file_handle

def get_credentials_from_environment(env_var_name: str) -> dict[str, str]:
    try:
        object_storage_config = CRED_ENVS_DICT[env_var_name]
    except KeyError:
        raise ValueError(f"Could not find {env_var_name} in CRED_ENVS")

    empty_arguments = {
        key.upper() for key in object_storage_config if object_storage_config[key] == ""
    }

    if empty_arguments:
        raise ValueError(
            f"Some required environment variable(s) were not provided for {env_var_name}",
            empty_arguments,
        )

    return object_storage_config

def load_json_auth(file_handle):
    if CRED_ENVS.APP_ENV in DEPLOYMENT_ENVIRONMENTS:
        return file_handle if file_handle else {}
    else:
        return json.load(file_handle)

# Remove key-value pairs where value is None from dictionary
def filter_none_values(data: Mapping[str, Optional[Any]]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    for k, v in data.items():
        if v is not None:
            result[k] = v
    return result

