import os
from typing import Mapping, Optional
from fastapi.staticfiles import StaticFiles
from ...core.config import _is_loopback_host

def get_auth_token_from_env(
    env_var_name: str, *, environment: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    if not env_var_name:
        return None
    source = environment if environment is not None else os.environ
    token_value = source.get(env_var_name)
    if token_value is None:
        return None
    token_value = token_value.strip()
    return token_value or None

def determine_allowed_hosts(server_host: str, permitted_hosts: list[str]) -> list[str]:
    filtered = [item.strip() for item in permitted_hosts if item and item.strip()]
    if filtered:
        return filtered
    if _is_loopback_host(server_host):
        return ["localhost", "127.0.0.1", "::1", "testserver"]
    return []

_DEFAULT_CACHE_POLICY = "public, max-age=31536000, immutable"

class CachedStaticFiles(StaticFiles):
    def __init__(self, *args, cache_policy: str = _DEFAULT_CACHE_POLICY, **kwargs):
        super().__init__(*args, **kwargs)
        self._cache_policy = cache_policy

    async def fetch_response(self, path: str, scope):
        response = await super().fetch_response(path, scope)
        if response.status_code in (200, 206, 304):
            response.headers.setdefault("Cache-Control", self._cache_policy)
        return response

