def periods_per_year(interval: int) -> float:
    """
    Determine how many trading intervals occur in a trading year
    Args:
        interval: the number of seconds in each trading interval
    Returns:
        number of trading intervals in each year

    """
    # TODO: update logic to account for strategies that do not hold overnight
    # 24 hours becomes 6.5 (hours the market is open) AND the risk_free_rate
