# NATS callback function registry module
__all__ = ['register']

from django.conf import settings

class CallbackRegistry:
    """Registry for managing NATS callback functions"""
    def __init__(self):
        self._registry = {}

    def register(self, name=None, func=None, **options):
        # Direct registration: register(func, name, ...)
        if func is not None:
            return self._add_function(func, name, **options)

        # Decorator without arguments: @register
        if name is not None and func is None and callable(name):
            return self._add_function(name, **options)

        # Decorator with arguments: @register(...)
        def decorator(func):
            return self.register(name, func, **options)
        return decorator

    def _add_function(self, func, name: str = None, **options):
        namespace = options.get('namespace', getattr(settings, 'NATS_NAMESPACE', 'default'))
        function_name = name or getattr(func, '_decorated_function', func).__name__
        jetstream = options.get('js', False)
        key = f'{namespace}.js.{function_name}' if jetstream else f'{namespace}.{function_name}'

        if key in self._registry:
            raise ValueError(f'Duplicate NATS function key `{key}`.')

        self._registry[key] = {
            'func': func,
            'namespace': namespace,
            'name': function_name,
            'js': jetstream,
        }
        return func

# Global registry instance and exportable register function
global_registry = CallbackRegistry()
register = global_registry.register

# Distributed locking mechanism using torch.distributed backend
import time
import uuid
import torch.distributed as dist
from torch.distributed.distributed_c10d import _get_default_store

class DistributedMutex:
    def __init__(self, lock_name, retry_delay=0.05, group_namespace=None):
        if not dist.is_initialized():
            raise RuntimeError("Process group not initialized")
        self.backend_store = _get_default_store()
        ns = group_namespace or f"ws{dist.get_world_size()}"
        self.prefix = f"lock/{ns}/{lock_name}"
        self.counter_key = f"{self.prefix}/counter"
        self.owner_key = f"{self.prefix}/owner"
        self.retry_delay = retry_delay
        self.current_token = None
        try:
            self.backend_store.add(self.counter_key, 0)
        except RuntimeError:
            pass

    def acquire(self, max_wait=None):
        begin_time = time.perf_counter()
        wait_interval = self.retry_delay
        my_id = f"{dist.get_rank()}:{uuid.uuid4()}".encode()
        while True:
            try:
                current_value = self.backend_store.add(self.counter_key, 1)
                if current_value == 1:
                    self._record_owner(my_id)
                    self.current_token = my_id
                    return True
                self._decrement_counter()
            except RuntimeError:
                # Handle contention by waiting and retrying
                pass
            if max_wait is not None and (time.perf_counter() - begin_time) > max_wait:
                return False
            time.sleep(wait_interval)
            wait_interval = min(wait_interval * 1.5, 0.5)

    def release(self):
        if self.current_token is None:
            raise RuntimeError("Lock not held by this process")
        current_owner = self._fetch_owner()
        if current_owner is not None and current_owner != self.current_token:
            raise RuntimeError("Lock owner mismatch; refusing to release")
        self._remove_owner()
        self._decrement_counter()
        self.current_token = None

    def _decrement_counter(self):
        delay = self.retry_delay
        while True:
            try:
                self.backend_store.add(self.counter_key, -1)
                return
            except RuntimeError:
                time.sleep(delay)
                delay = min(delay * 1.5, 0.5)

    def _record_owner(self, token: bytes):
        try:
            self.backend_store.set(self.owner_key, token)
        except RuntimeError as err:
            self._decrement_counter()
            raise RuntimeError("Failed to record lock owner") from err

    def _fetch_owner(self) -> bytes | None:
        try:
            result = self.backend_store.get(self.owner_key)
            return result if result else None
        except RuntimeError:
            return None

    def _remove_owner(self):
        try:
            self.backend_store.set(self.owner_key, b"")
        except RuntimeError:
            pass

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()
        return False

