# Resolve dimensions based on strategy and custom inputs
from typing import List, Optional
from enum import Enum

class DimensionCategory(str, Enum):
    APPLICATION = "application_first"
    INFRASTRUCTURE = "infrastructure_first"
    INSTANCE = "instance_first"
    CUSTOM = "custom"

class DimensionHandler:
    DEFAULT_DIMENSION_MAP = {
        DimensionCategory.APPLICATION: ["service"],
        DimensionCategory.INFRASTRUCTURE: ["location"],
        DimensionCategory.INSTANCE: ["resource_name"],
    }
    PRIORITY_SEQUENCE = [
        DimensionCategory.APPLICATION,
        DimensionCategory.INFRASTRUCTURE,
        DimensionCategory.INSTANCE,
    ]

    @classmethod
    def determine_dimensions_for_mode(
        cls,
        dim_category: str,
        user_dimensions: Optional[List[str]] = None,
    ) -> List[List[str]]:
        if dim_category == DimensionCategory.CUSTOM.value or dim_category == "custom":
            if user_dimensions:
                return [user_dimensions]
            return [["event_id"]]
        try:
            category = DimensionCategory(dim_category)
        except ValueError:
            category = DimensionCategory.INSTANCE
        start_pos = cls.PRIORITY_SEQUENCE.index(category)
        output = []
        for priority_type in cls.PRIORITY_SEQUENCE[start_pos:]:
            output.append(cls.DEFAULT_DIMENSION_MAP[priority_type])
        output.append(["event_id"])
        return output

