class SystemState:
    NET_ACTIVE = "CONNECTION_WORKING"

class TransitionRecord:
    def __init__(self, origin=None, action=None, destination=None, finished=False):
        self.origin = origin
        self.action = action
        self.destination = destination
        self.finished = finished

    def is_fully_defined(self):
        return all([self.origin, self.action, self.destination, self.finished])

    def remains_unchanged(self):
        return self.origin == self.destination

    @staticmethod
    def build_complete(origin, action, destination, finished):
        return TransitionRecord(origin, action, destination, finished)

class DummySettings:
