    settings = DummySettings()
    evaluator = NetworkEvaluator(settings)
    initial_record = TransitionRecord(SystemState.NET_ACTIVE)
    result_record = evaluator.assess(initial_record)

    target_record = TransitionRecord.build_complete(
        SystemState.NET_ACTIVE, 
        expected_action, 
        expected_destination, 
        expected_finished
    )

    assert result_record.is_fully_defined() == target_record.is_fully_defined()
