from twisted.trial.unittest import TestCase

class PalindromeTestCase(TestCase):
    def test_palindrome(self, input_text):
        # Filter alphanumeric characters and convert to lowercase
        filtered_chars = []
        for char in input_text:
            if char.isalnum():
                filtered_chars.append(char.lower())

        # Build the cleaned string from filtered characters
        normalized_text = ''.join(filtered_chars)

        # Create reversed version using manual reversal
        reversed_text = ''
        for i in range(len(normalized_text) - 1, -1, -1):
            reversed_text += normalized_text[i]

        # Assert that cleaned string matches its reverse
        self.assertEqual(normalized_text, reversed_text, f"{input_text} is not a palindrome")

