import glob
import re

def extract_file_info(pattern):
    results = []
    rss_pattern = re.compile(r'kb=(\d+)')
    size_pattern = re.compile(r'size=(\d+)')

    for filepath in glob.iglob(pattern):
        try:
            with open(filepath, 'r') as file_obj:
                header_line = file_obj.readline()

            kb_value = None
            size_value = None

            rss_match = rss_pattern.search(header_line)
            if rss_match:
                kb_value = int(rss_match.group(1))

            size_match = size_pattern.search(filepath)
            if size_match:
                size_value = int(size_match.group(1))

            if kb_value is not None and size_value is not None:
                results.append({
                    'path': filepath,
                    'kb': kb_value,
                    'size': size_value
                })
        except (IOError, OSError):
            # Skip files that cannot be read
            continue

    return results

