from pathlib import Path
import shutil

def transfer_directory_contents(source_path: Path, target_path: Path, replace_existing=False):
    # Define patterns to exclude during copying
    exclusion_patterns = shutil.ignore_patterns("*.pyc", "__pycache__")

    # Validate source directory
    if not (source_path.exists() and source_path.is_dir()):
        raise ValueError("Source folder does not exist or is not a directory")

    # Validate target directory
    if not (target_path.exists() and target_path.is_dir()):
        raise ValueError("Destination folder does not exist or is not a directory")

    # Process each item in the source directory
    for element in source_path.iterdir():
        if element.is_file():
            # Copy file only if overwrite flag is set or target doesn't exist
            if replace_existing or not (target_path / element.name).exists():
                shutil.copy2(element, target_path)
        elif element.is_dir():
            # Recursively handle subdirectories
            new_target = target_path / element.name
            new_target.mkdir(parents=True, exist_ok=True)
            transfer_directory_contents(element, new_target, replace_existing)

