from collections import defaultdict

class TreeAPIParser(BaseAPIParser):
    """
    Constructs a hierarchical tree representation of API endpoints
    """
    def __init__(self, *args, **kwargs):
        self.api_tree = defaultdict(lambda: defaultdict(dict))
        super().__init__(*args, **kwargs)

    def parse(self):
        self.build_endpoint_tree(self.url_patterns, self.api_tree)

    def build_endpoint_tree(self, patterns, tree_structure):
        for pattern in patterns:
            segments = pattern.strip('/').split('/')
            current_level = tree_structure
            for segment in segments:
                if segment not in current_level:
                    current_level[segment] = defaultdict(dict)
                current_level = current_level[segment]

# Refactored version with equivalent functionality but different implementation approach

class SyncHandlerManager:
    def __init__(self, inbox_manager):
        self.inbox_manager = inbox_manager
        self._client_event_runner = None
        # Using a dictionary to track handler states instead of separate boolean attributes
        self._handler_states = {
            'receiver': False,
            'client_event': False
        }

    def _set_handler_state(self, handler_type, state):
        """Helper method to update handler state"""
        if handler_type in self._handler_states:
            self._handler_states[handler_type] = state

    def start_receiver_handlers(self):
        # Logic to start receiver handlers
        self._set_handler_state('receiver', True)

    def stop_receiver_handlers(self):
        # Logic to stop receiver handlers
        self._set_handler_state('receiver', False)

    def start_client_event_handlers(self):
        # Logic to start client event handlers
        self._set_handler_state('client_event', True)

    def stop_client_event_handlers(self):
        # Logic to stop client event handlers
        self._set_handler_state('client_event', False)

    def stop(self):
        # Check each handler type and stop if active
        for handler_type, is_running in self._handler_states.items():
            if is_running:
                getattr(self, f'stop_{handler_type}_handlers')()

    @property
    def receiver_handlers_running(self):
        return self._handler_states['receiver']

    @property
    def client_event_handlers_running(self):
        return self._handler_states['client_event']

