from typing import List

def calculate_average(numbers: List[float]) -> float:
    if len(numbers) < 3:
        raise ValueError("Input list should contain at least 3 numbers")

    # Find minimum and maximum values using manual iteration instead of built-in functions
    min_val = numbers[0]
    max_val = numbers[0]
    for num in numbers:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    # Calculate sum excluding min and max by iterating through the list
    total_sum = 0.0
    for num in numbers:
        if num != min_val and num != max_val:
            total_sum += num

    # Adjust count to exclude min and max values
    adjusted_count = len(numbers) - 2

    return total_sum / adjusted_count

