# Custom JWT authentication class for DRF

from rest_framework.authentication import BaseAuthentication
from rest_framework.exceptions import AuthenticationFailed
import jwt
from django.conf import settings
from django.contrib.auth.models import User

class CustomJWTAuth(BaseAuthentication):
    def authenticate(self, request):
        auth_header = self.extract_token(request)
        if not auth_header:
            return None

        try:
            decoded_data = jwt.decode(
                auth_header, 
                settings.SECRET_KEY, 
                algorithms=['HS256']
            )

            user_obj = User.objects.get(username=decoded_data['username'])
            return (user_obj, auth_header)

        except jwt.ExpiredSignatureError:
            raise AuthenticationFailed('Token expired')
        except jwt.PyJWTError:
            raise AuthenticationFailed('Token is invalid')

    def extract_token(self, request):
        auth_value = request.META.get('HTTP_AUTHORIZATION')
        if not auth_value:
            return None

        token_parts = auth_value.split()

        if len(token_parts) != 2 or token_parts[0].lower() != 'bearer':
            return None

        return token_parts[1]

