# Check if the system is in a safe state (no deadlock)
def is_safe_state(allocated, max_requirement, available):
    process_count = len(allocated)  # Total number of processes
    resource_count = len(available)  # Total number of resource types

    # Initialize work vector and completion status list
    remaining_resources = available.copy()
    completed = [False] * process_count

    # Continue until no more processes can be scheduled
    while True:
        progress_made = False
        for idx in range(process_count):
            if not completed[idx]:
                # Check if process requirements can be satisfied with current resources
                if all(req <= remain for req, remain in zip(max_requirement[idx], remaining_resources)):
                    # Execute this process and release its resources
                    progress_made = True
                    completed[idx] = True
                    remaining_resources = [remaining_resources[r] + allocated[idx][r] for r in range(resource_count)]
                    break

        if not progress_made:
            break

    # System is safe if all processes completed successfully
    return all(completed)

