def transform_network_layers(network):
    # Import required components for layer transformation
    from keras.layers import Activation
    from keras import layers

    transformed_layers = []

    # Iterate through each layer in the network
    for current_layer in network.layers:
        # Determine source of relu6 activation based on layer type
        if 'keras.applications.mobilenet' in str(current_layer.__class__):
            from keras.applications.mobilenet import relu6
        else:
            from keras_applications.mobilenet import relu6

        # Create new activation layer with same name and relu6 function
        new_layer = Activation(relu6, name=current_layer.name)
        transformed_layers.append(new_layer)

    # Reconstruct the model with transformed layers
    if transformed_layers:
        # Build new model using transformed layers
        output_tensors = []
        for idx, layer in enumerate(transformed_layers):
            if idx == 0:
                # First layer takes original input
                output_tensors.append(layer(network.input))
            else:
                # Subsequent layers take previous layer's output
                output_tensors.append(layer(output_tensors[-1]))

        # Create new model with transformed layers
        from keras.models import Model
        return Model(inputs=network.input, outputs=output_tensors[-1])

    return network

