async def withdraw(account_id: str, amount: float):
    async with app.state.db.acquire() as conn:
        # First check if account exists and get current balance
        account = await conn.query_single("""
            SELECT Account {
                balance
            }
            FILTER .id = <uuid>$account_id;
        """, account_id=account_id)

        # Handle case where account doesn't exist
        if account is None:
            return {"message": "Account not found"}

        # Check for sufficient funds and valid withdrawal amount
        if amount <= 0:
            return {"message": "Withdrawal amount must be positive"}
        elif account.balance >= amount:
            await conn.execute("""
                UPDATE Account
                FILTER .id = <uuid>$account_id
                SET {
                    balance := .balance - <balance_t>$amount
                };
            """, account_id=account_id, amount=amount)
            return {"message": "Withdrawal successful"}
        else:
            return {"message": "Insufficient funds"}

