# Check if a binary tree is symmetric (mirror of itself)
def is_symmetric(root):
    def check_symmetry(node1, node2):
        # Both nodes are None: symmetric
        if not node1 and not node2:
            return True
        # One node is None but not the other: not symmetric
        if not node1 or not node2:
            return False
        # Values must match and subtrees must be mirrors of each other
        return (node1.val == node2.val and 
                check_symmetry(node1.left, node2.right) and 
                check_symmetry(node1.right, node2.left))

    # Empty tree is symmetric
    if not root:
        return True

    # Check if left and right subtrees are mirrors
    return check_symmetry(root.left, root.right)

