import json
from base64 import b64encode

def transform_and_serialize(data: dict, fields_to_transform: list) -> str:
    result = data.copy()
    for field in fields_to_transform:
        if field in data:
            original_value = str(data[field])
            encoded_bytes = b64encode(original_value.encode('utf-8'))
            result[field] = encoded_bytes.decode('utf-8')
    return json.dumps(result)

