import random

def sort_list(data, size):
    # Perform selection sort to arrange elements in ascending order
    for pos in range(size - 1):
        lowest = pos
        for check in range(pos + 1, size):
            if data[check] < data[lowest]:
                lowest = check
        data[pos], data[lowest] = data[lowest], data[pos]

