import socket

def setup_udp_server(port_number: int) -> str:
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        except Exception:
            pass

        try:
            sock.bind(('', port_number))
            return f"UDP server ready on port {port_number}"
        except OSError:
            return f"Failed to bind to port {port_number}"
    except socket.error as err:
