import urllib.parse

def build_query_string(params, mapping):
    """
    Transform a parameter dictionary into a URL-encoded query string.
    :param params: dictionary containing request parameters
    :param mapping: dictionary that maps internal parameter names to query parameter names
    :return: URL-encoded query string
    """
    encoded_pairs = {}
    for key in mapping:
        if key in params and params[key] is not None:
            encoded_pairs[mapping[key]] = str(params[key])
    return urllib.parse.urlencode(encoded_pairs)

