import time
import functools

class MemoizeWithTimeout:
    def __init__(self, expiry=None, exclude=None, hasher=None):
        self.expiry = expiry
        self.exclude = exclude or []
        self.hasher = hasher
        self.memory = {}

    def __call__(self, fn):
        """Main decorator logic.
        :arg function fn: The function to be decorated.
        """
        @functools.wraps(fn)
        def inner(*arguments, **keywords):
            """Internal handler that manages caching behavior.
            """
            # Skip caching if arguments match excluded cases
            if self.exclude and arguments in self.exclude:
                return fn(*arguments, **keywords)

            # Generate cache key using custom hasher or default to arguments
            identifier = arguments if not self.hasher else self.hasher(*arguments, **keywords)

            # Check if cached result exists and is still valid
            if identifier in self.memory:
                value, recorded_time = self.memory[identifier]
                if not self.expiry or (time.time() - recorded_time) < self.expiry:
                    return value

            # Compute and store new result
            value = fn(*arguments, **keywords)
            self.memory[identifier] = (value, time.time())
            return value

        return inner

