# Read integers from standard input and compute min, max, and average

def process_input():
    minimum = float('inf')
    maximum = float('-inf')
    cumulative_sum = 0
    count = 0

    try:
        while True:
            line = input()
            # Check if the line represents a valid integer (positive or negative)
            is_valid = False
            if line.isdigit():
                is_valid = True
            elif line.startswith('-') and len(line) > 1 and line[1:].isdigit():
                is_valid = True

            if not is_valid:
                break

            value = int(line)

            # Update min and max
            if value < minimum:
                minimum = value
            if value > maximum:
                maximum = value

            cumulative_sum += value
            count += 1

        if count > 0:
            print("min: " + str(minimum))
            print("avg: " + str(cumulative_sum / count))
            print("max: " + str(maximum))
        else:
            print("No valid input provided")

    except EOFError:
        print("Error: Unexpected end of input")

if __name__ == "__main__":
