# Custom collection class that ensures at least one element exists

from typing import TypeVar, List, Set, Dict, Any

T = TypeVar("T")
U = TypeVar("U")

class RequiredElementList:
    def __init__(self, *items: T) -> None:
        if len(items) == 0:
            raise ValueError("RequiredElementList must have at least one item")
        self._storage = list(items)

    def get(self, position: int) -> T:
        return self._storage[position]

    def put(self, position: int, new_value: T) -> None:
        self._storage[position] = new_value

    def delete(self, position: int) -> None:
        del self._storage[position]

    def size(self) -> int:
        return len(self._storage)

    def add(self, item: T) -> None:
        self._storage.append(item)

    def add_many(self, additional_items: List[T]) -> None:
        self._storage.extend(additional_items)

    def erase(self, target: T) -> None:
        self._storage.remove(target)

    def as_set(self) -> Set[T]:
        return set(self._storage)

    def as_dictionary(self) -> Dict[T, U]:
        if len(self._storage) % 2 != 0:
            raise ValueError("RequiredElementDict needs an even count of items")
        keys = self._storage[::2]
        values = self._storage[1::2]
        return dict(zip(keys, values))

# Custom logging handler to send error-level logs to Rollbar

import logging
import rollbar
from rollbar.logger import RollbarHandler

class RollbarErrorReporter(logging.Handler):
    def __init__(self, api_key, env_name, min_level=logging.WARNING):
        super().__init__(min_level)
        rollbar.init(api_key, environment=env_name, handler='async')

    def emit(self, log_record):
        try:
            formatted_msg = self.format(log_record)
            severity = log_record.levelname.lower()

            if severity in ['error', 'critical', 'fatal']:
                rollbar.report_message(
                    formatted_msg, 
                    severity, 
                    extra_data={'log_record': log_record.__dict__}
                )
        except Exception:
            self.handleError(log_record)

