import numpy

def get_package_versions() -> dict[str, tuple[int, int] | None]:
    def _extract_major_minor(version_str: str) -> tuple[int, int] | None:
        try:
            parts = version_str.split('.')
            if len(parts) < 2:
                return None
            major = int(parts[0])
            minor = int(parts[1])
            return (major, minor)
        except (ValueError, AttributeError, IndexError):
            return None

    versions = {
        'cloudpickle': _extract_major_minor(getattr(cloudpickle, '__version__', None)),
        'json_tricks': _extract_major_minor(getattr(json_tricks, '__version__', None)),
        'yaml': _extract_major_minor(getattr(yaml, '__version__', None)),
        'nni': _extract_major_minor(getattr(nni, '__version__', None)),
        'python': sys.version_info[:2],
        'numpy': _extract_major_minor(numpy.__version__)
    }

    return versions

