from typing import Any, Dict

class PaymentFailureEvent:
    def __init__(self, payment_net_id, token_net_id, trans_id, destination, cause):
        self.payment_network_identifier = payment_net_id
        self.token_network_identifier = token_net_id
        self.identifier = trans_id
        self.target = destination
        self.reason = cause

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, PaymentFailureEvent):
            return False

        # Compare all attributes using their respective values
        return all([
            self.payment_network_identifier == other.payment_network_identifier,
            self.token_network_identifier == other.token_network_identifier,
            self.identifier == other.identifier,
            self.target == other.target,
            self.reason == other.reason
        ])

    def __ne__(self, other: Any) -> bool:
        return not self.__eq__(other)

    def to_dictionary(self) -> Dict[str, Any]:
        return {
            'payment_network_identifier': self.payment_network_identifier,
            'token_network_identifier': self.token_network_identifier,
            'identifier': self.identifier,
            'target': self.target,
            'reason': self.reason
        }

import re

class DuplicateBindingError(Exception):
    pass

class InvalidQueryFormatError(Exception):
    pass

def check_sql_bindings(binding_list):
    registered_functions = {}
    valid_sql_pattern = r'^\s*(SELECT|UPDATE|INSERT|DELETE)\s+.+'

    for func_decorator, query_text in binding_list:
        if func_decorator in registered_functions:
            raise DuplicateBindingError(f"Function '{func_decorator.__name__}' has already been associated with a SQL command")

        if not re.match(valid_sql_pattern, query_text):
            raise InvalidQueryFormatError(f"The SQL query '{query_text}' does not follow proper syntax")

        registered_functions[func_decorator] = query_text

    return "All SQL bindings are properly configured"

