def get_data_for_room_list(room_dict):
    """
    Processes data from a dungeon game and returns a list of rooms with their respective items and non-player characters (NPCs).
    Args:
    room_dict (dict): A dictionary containing data for rooms, items, and NPCs.
    Returns:
    list: A list of rooms with their associated items and NPCs.
    Example:
    Input:
    room_dict = {
        'roomID': 1,
        'roomName': 'Starting Room',
        'npcID': 101,
        'npcName': 'Goblin',
        'npcItemID': 201,
        'npcItemName': 'Sword',
        'npcItemDesc': 'A sharp sword wielded by the Goblin',
        'roomItemID': 301,
        'roomItemName': 'Potion',
        'roomItemDescription': 'A healing potion'
    }
    Output:
    [
        {
            'roomID': 1,
            'roomName': 'Starting Room',
            'npc': {
                'npcID': 101,
                'name': 'Goblin',
                'item': {
                    'itemID': 201,
                    'name': 'Sword',
                    'description': 'A sharp sword wielded by the Goblin'
                }
            },
            'item': {
                'itemID': 301,
                'name': 'Potion',
                'description': 'A healing potion'
            }
        }
    ]
    """
    result_rooms = []

    # Check if input is a valid dictionary before processing
    if not isinstance(room_dict, dict):
        return result_rooms

    try:
        # Extract NPC information
        npc_info = {
            'npcID': room_dict.get('npcID'),
            'name': room_dict.get('npcName'),
            'item': {
                'itemID': room_dict.get('npcItemID'),
                'name': room_dict.get('npcItemName'),
                'description': room_dict.get('npcItemDesc')
            }
        }

        # Extract room item information
        room_item_info = {
            'itemID': room_dict.get('roomItemID'),
            'name': room_dict.get('roomItemName'),
            'description': room_dict.get('roomItemDescription')
        }

        # Construct the room entry
        room_entry = {
            'roomID': room_dict.get('roomID'),
            'roomName': room_dict.get('roomName'),
            'npc': npc_info,
            'item': room_item_info
        }

        result_rooms.append(room_entry)

    except (KeyError, AttributeError):
        # Silently handle missing keys or attribute errors
        pass

    return result_rooms

