class ValidationException(Exception):
    pass

def validate_stream_payload(payload):
    try:
        # Check that 'streams' exists, is a non-empty list
        if "streams" not in payload:
            raise AssertionError("Missing 'streams' key")
        if not isinstance(payload["streams"], list):
            raise AssertionError("'streams' must be a list")
        if len(payload["streams"]) == 0:
            raise AssertionError("'streams' list cannot be empty")

        # Extract the first stream's 'stream' dictionary
        first_stream_entry = payload["streams"][0]
        stream = first_stream_entry.get("stream", {})

        # Verify stream is a dict with required keys
        required_keys = ["test", "chaostoolkit_lib_version", "chaostoolkit_run_trace_id", 
                        "chaostoolkit_experiment_ref", "One", "source"]
        if not isinstance(stream, dict):
            raise AssertionError("'stream' must be a dictionary")
        for key in required_keys:
            if key not in stream:
                raise AssertionError(f"Missing required key '{key}' in 'stream'")

        # Validate specific field values
        if stream["test"] != "yes":
            raise AssertionError("Invalid value for 'test' key")
        if stream["source"] != "chaostoolkit":
            raise AssertionError("Invalid value for 'source' key")

        return True
    except AssertionError as e:
        raise ValidationException(str(e))

import torch

def custom_mean(tensor, dim=None, keepdim=False):
    if dim is None:
        # Compute mean over all dimensions
        return tensor.mean()
    else:
        # Normalize dim to a list and sort in ascending order
        dims = [dim] if isinstance(dim, int) else list(dim)
        dims = sorted(dims)

        # Apply mean sequentially for each dimension
        result = tensor.clone()
        for idx, d in enumerate(dims):
            result = result.mean(dim=d, keepdim=True)

        # Remove squeezed dimensions if keepdim is False
        if not keepdim:
            for i, d in enumerate(dims):
                actual_dim = d - i  # Adjust index due to previous squeezes
                result = result.squeeze(actual_dim)

        return result

