# Secure HTTP server with custom logging and dual-port support

import http.server
import ssl
import sys
import logging
from datetime import datetime as dt

class LoggingHandler(http.server.SimpleHTTPRequestHandler):
    def log_message(self, format, *args):
        timestamp = dt.now().strftime("%Y-%m-%d %H:%M:%S")
        log_line = f"{self.client_address[0]} - - [{timestamp}] \"{self.command} {self.path} HTTP/1.1\""
        self.record_log(log_line)

    def record_log(self, message):
        try:
            with open(f"{self.server.base_dir}/access.log", "a") as file:
                file.write(message + "\n")
        except Exception as e:
            logging.error(f"Log write error: {e}")

class DualProtocolServer:
    def __init__(self, target_directory):
        self.work_dir = target_directory

    def start_services(self, http_port, https_port, private_key, cert_file):
        # HTTP server instance
        http_server = http.server.HTTPServer(("", http_port), http.server.SimpleHTTPRequestHandler)
        http_server.base_dir = self.work_dir

        # HTTPS server instance
        secure_server = http.server.HTTPServer(("", https_port), LoggingHandler)
        secure_server.base_dir = self.work_dir
        secure_server.socket = ssl.wrap_socket(
            secure_server.socket,
            server_side=True,
            keyfile=private_key,
            certfile=cert_file
        )

        # Configure error logging
        logging.basicConfig(
            filename=f"{self.work_dir}/error.log",
            level=logging.ERROR,
            format="%(asctime)s - %(levelname)s - %(message)s"
        )

        try:
            print(f"Starting servers on ports {http_port} (HTTP) and {https_port} (HTTPS)")
            from threading import Thread

            def run_http():
                try:
                    http_server.serve_forever()
                except Exception as e:
                    logging.error(f"HTTP server error: {e}")

            def run_https():
                try:
                    secure_server.serve_forever()
                except Exception as e:
                    logging.error(f"HTTPS server error: {e}")

            Thread(target=run_http, daemon=True).start()
            Thread(target=run_https, daemon=True).start()

            # Keep main thread alive
            import time
            while True:
                time.sleep(1)

        except KeyboardInterrupt:
            print("\nShutting down servers...")
            http_server.shutdown()
            secure_server.shutdown()
        except Exception as e:
            logging.critical(f"Critical server failure: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python secure_server.py <directory_to_serve>")
        sys.exit(1)

    directory_to_serve = sys.argv[1]
    server_instance = DualProtocolServer(directory_to_serve)
    server_instance.start_services(
        8000, 
        8443, 
        "/tmp/server1.example.com.key", 
        "/tmp/server1.example.com.pem"
    )

