import re

class TextCreator:
    def produce_content(
        self, source_data, length_limit=100, termination_marker=None, pattern_filter=None
    ):
        placeholder = "placeholder text, 456. Simple as pie, easy to try."

        if isinstance(source_data, str):
            result = placeholder
        elif isinstance(source_data, list):
            result = [f"{idx}_{placeholder}" for idx, _ in enumerate(source_data)]
        else:
            raise TypeError("source_data has unexpected type %s" % type(source_data))

        result = self.refine_output(result, length_limit, termination_marker, pattern_filter)
        return result

    def refine_output(self, content, limit, terminator, regex_pattern):
        if isinstance(content, list):
            content = " ".join(content)

        if terminator and terminator in content:
            end_pos = content.find(terminator) + len(terminator)
            content = content[:end_pos]

        if regex_pattern:
            content = re.sub(regex_pattern, '', content)

        if limit and len(content) > limit:
            content = content[:limit]

        return content

