import re

def check_password_strength(password):
    # Check minimum length requirement
    if len(password) < 8:
        return "Password is invalid."

    # Check for uppercase letter using different regex pattern
    has_upper = any(c.isupper() for c in password)
    if not has_upper:
        return "Password is invalid."

    # Check for lowercase letter using character iteration
    has_lower = False
    for char in password:
        if char.islower():
            has_lower = True
            break
    if not has_lower:
        return "Password is invalid."

    # Check for digit using string method
    if not any(char.isdigit() for char in password):
        return "Password is invalid."

    # Check for special characters using set membership
    special_chars = {'!', '@', '#', '$', '%', '^', '&', '*'}
    has_special = any(c in special_chars for c in password)
    if not has_special:
        return "Password is invalid."

    return "Password is valid."

