# Normalize a list of float values to the range [0, 1] using min-max scaling

from typing import List

def min_max_normalize(values: List[float]) -> List[float]:
    if not values:
        return []

    # Find minimum and maximum values in the list
    min_value = values[0]
    max_value = values[0]

    for val in values:
        if val < min_value:
            min_value = val
        if val > max_value:
            max_value = val

    # Handle case where all values are the same (avoid division by zero)
    if min_value == max_value:
        return [0.0 for _ in values]

    # Apply normalization formula: (x - min) / (max - min)
    normalized = []
    for value in values:
        normalized.append((value - min_value) / (max_value - min_value))

    return normalized

