# Implementation of a generic stack using linked list structure

class StackNode:
    def __init__(self, value) -> None:
        self.value = value
        self.link = None

class GenericStack:
    def __init__(self) -> None:
        self.head = None
        self.length = 0

    def is_empty(self) -> bool:
        return self.length == 0

    def push(self, item) -> None:
        temp = StackNode(item)
        temp.link = self.head
        self.head = temp
        self.length += 1

    def pop(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        result = self.head.value
        self.head = self.head.link
        self.length -= 1
        return result

    def top_element(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.head.value

    def count(self) -> int:
        return self.length

# Modified version using different logic but same functionality

from pint import UnitRegistry

class Float:
    def __init__(self, setter=False, values=None, unit=None, mapping=None):
        self.setter = setter
        self.values = values if values else []
        self.unit = unit
        self.mapping = mapping if mapping else {}

    def pre_set(self, _, value):
        # Check if setter is enabled first
        if not self.setter:
            raise ValueError("Setter is not enabled")

        # Handle unit conversion if unit is specified
        if self.unit and isinstance(value, (int, float)):
            return self._convert_value_to_unit(value)
        elif self.unit and hasattr(value, 'magnitude'):
            # Handle pint quantity objects
            ureg = UnitRegistry()
            return ureg(value).to(self.unit).magnitude
        return value

    def post_get(self, _, value):
        # Reverse lookup in mapping dictionary
        if self.mapping:
            for k, v in self.mapping.items():
                if v == value:
                    return k
            return None
        return value

    def _convert_value_to_unit(self, value):
        # Convert numeric value to specified unit
        if self.unit:
            ureg = UnitRegistry()
            return ureg(str(value)).to(self.unit).magnitude
        return value

# Test cases
def test_pre_set_without_unit():
    f = Float(setter=True)
    assert f.pre_set(None, 5) == 5

def test_pre_set_with_unit():
    f = Float(setter=True, unit='mV')
    u = UnitRegistry()
    assert f.pre_set(None, 1.0) == 1.0
    assert f.pre_set(None, u.parse_expression('0.0024 V')) == 2.4

def test_with_mapping_no_units():
    m = Float(mapping={1.0: 'On', 2.0: 'Off'})
    assert m.post_get(None, 'On') == 1.0

