# Monitor a directory for newly created files and log their details

import os
import time
from pathlib import Path

def track_directory_changes(directory_path):
    # Define the path for the log file inside the monitored directory
    log_file = Path(directory_path) / "directory_events.log"

    # Ensure the log file exists; create it if missing
    if not log_file.exists():
        log_file.touch()

    # Capture initial state of files in the directory
    previous_files = {
        item.name: {
            'size': item.stat().st_size,
            'ctime': item.stat().st_ctime
        }
        for item in Path(directory_path).iterdir() 
        if item.is_file()
    }

    while True:
        # Re-scan current files in the directory
        current_state = {
            item.name: {
                'size': item.stat().st_size,
                'ctime': item.stat().st_ctime
            }
            for item in Path(directory_path).iterdir() 
            if item.is_file()
        }

        # Identify newly added files (present now but not before)
        new_entries = {}
        for name, info in current_state.items():
            if name not in previous_files:
                new_entries[name] = info

        # Log any new files found
        if new_entries:
            with open(log_file, 'a') as logger:
                for filename, metadata in new_entries.items():
                    timestamp = time.ctime(metadata['ctime'])
                    size = metadata['size']
                    logger.write(f"Detected: {filename}, Size: {size} bytes, Time: {timestamp}\n")

            # Refresh baseline to include newly detected files
            previous_files.update(new_entries)

        # Pause before next scan
        time.sleep(1)

# Entry point for execution
if __name__ == "__main__":
    target_directory = "/path/to/your/directory"
    track_directory_changes(target_directory)

