# Script to fetch data from an API and save the response to a JSON file

import requests
import argparse
import logging
import json
from datetime import datetime as dt

def fetch_api_data(endpoint_url, query_params):
    try:
        api_response = requests.get(endpoint_url, params=query_params)
        api_response.raise_for_status()  # Trigger error for HTTP error codes
        return api_response.json()
    except requests.exceptions.RequestException as error:
        logging.error(f"Error occurred during API request: {error}")
        return None

def save_api_results(api_data, destination_file):
    if api_data is not None:
        try:
            with open(destination_file, 'w', encoding='utf-8') as output:
                json.dump(api_data, output, indent=4, ensure_ascii=False)
                logging.info(f"Successfully saved API results to {destination_file}")
        except (OSError, IOError) as write_error:
            logging.error(f"Could not write to file {destination_file}: {write_error}")
    else:
        logging.warning("No data received from API to save")

def parse_arguments():
    argument_parser = argparse.ArgumentParser(
        description='Fetch data from an API and store it in a JSON file'
    )
    argument_parser.add_argument('api_endpoint', help='Target API URL')
    argument_parser.add_argument(
        '--query',
        help='Query parameters in key=value format, separated by &',
        default=''
    )
    argument_parser.add_argument('output_path', help='Path to output JSON file')
    return argument_parser.parse_args()

def setup_logging():
    log_format = '%(asctime)s - %(levelname)s - %(message)s'
    logging.basicConfig(
        filename='api_fetch.log',
        level=logging.INFO,
        format=log_format,
        datefmt='%Y-%m-%d %H:%M:%S'
    )

def main():
    args = parse_arguments()
    setup_logging()

    endpoint = args.api_endpoint
    # Parse query parameters safely
    parameters = {}
    if args.query:
        for pair in args.query.split('&'):
            if '=' in pair:
                key, value = pair.split('=', 1)
                parameters[key] = value

    output_file = args.output_path
    logging.info(f"Initiating API request to {endpoint} with params: {parameters}")

    result = fetch_api_data(endpoint, parameters)
    save_api_results(result, output_file)

if __name__ == "__main__":
    main()

# Custom validation decorator for function inputs

def check_arguments(expected_types=None, allowed_module=None, custom_check=None):
    def apply_validation(target_func):
        def secure_execution(*parameters, **options):
            # Validate number and types of positional arguments
            if expected_types is not None:
                if len(parameters) != len(expected_types):
                    raise ValueError(f"Expected {len(expected_types)} parameters, received {len(parameters)}")
                for index, value in enumerate(parameters):
                    if not isinstance(value, expected_types[index]):
                        raise TypeError(f"Parameter at index {index+1} must be of type {expected_types[index]}")

            # Verify calling module matches allowed scope
            if allowed_module is not None:
                import inspect
                caller_frame = inspect.currentframe().f_back
                caller_module = inspect.getmodule(caller_frame)
                if caller_module.__name__ != allowed_module:
                    raise ValueError(f"Function invoked from unauthorized module: {caller_module.__name__}")

            # Apply user-defined validation rule
            if custom_check is not None:
                if not custom_check(*parameters, **options):
                    raise ValueError("Validation failed: arguments do not meet required conditions")

            return target_func(*parameters, **options)
        return secure_execution
    return apply_validation

