from typing import Iterator, Dict, Any, List, Tuple, Optional
from abc import ABC, abstractmethod

class AbstractRow(ABC):
    pass

class JoinedRow(AbstractRow):
    def __init__(self, left: Dict[str, Any], right: Dict[str, Any], _id: int):
        self.left = left
        self.right = right
        self._id = _id

class RightJoin(LeftJoin):
    def _produce(self) -> Iterator[AbstractRow]:
        # Process each group of joined rows associated with right-side records
        for right_record, match_groups in self.grouped:
            # Track if any matches were found for this right record
            has_match = False

            # First pass: check all potential matches against the predicate
            for potential_match in match_groups:
                left_data = potential_match.left

                # Test if the current left-right pair satisfies the join condition
                if self.predicate(left_data, right_record):
                    has_match = True
                    # Yield a new joined row with matched data
                    yield JoinedRow(left_data, right_record, _id=-1)

            # If no matches were found, yield a right record with null/left-empty fields
            if not has_match:
                # Create empty dict with same keys as left schema (assuming first match has the schema)
                empty_left = {}
                if match_groups:
                    # Use the first group's left keys to create empty dict
                    sample_left = match_groups[0].left
                    empty_left = {key: None for key in sample_left}

                yield JoinedRow(empty_left, right_record, _id=-1)

import sys
from os.path import exists

def setup_logging():
    loggers = []

    # Check for available syslog device
    syslog_paths = ['/dev/log', '/var/run/syslog']
    found_syslog = None
    for path in syslog_paths:
        if exists(path):
            found_syslog = path
            break

    if found_syslog is not None:
        loggers.append('syslog')

    # Add console logger unless running under mod_wsgi
    is_mod_wsgi = False
    if len(sys.argv) > 0 and sys.argv[0] == 'mod_wsgi':
        is_mod_wsgi = True

    if not is_mod_wsgi:
        loggers.append('console')

    return loggers

import boto3
from pathlib import Path
import secrets as sec_module

class AWSParameterStoreAccessor:
    def __init__(self, parameter_prefix):
        self.parameter_prefix = parameter_prefix

    def retrieve_secrets(self):
        if self.parameter_prefix is None:
            return sec_module.__dict__.get('secrets', {})

        param_path = Path(self.parameter_prefix)
        ssm = boto3.client('ssm')

        params_response = ssm.get_parameters_by_path(
            Path=param_path,
            Recursive=True,
            WithDecryption=True
        )

        secret_map = {}
        for item in params_response.get('Parameters', []):
            key_name = item['Name'].split('/')[-1]
            value = item['Value']
            secret_map[key_name] = value

        return secret_map

