import pathlib
import sys
import typing
import shutil

def copy_directory_tree(source: pathlib.Path, target: pathlib.Path, logger: typing.TextIO = sys.stdout) -> None:
    # Verify source directory exists
    if not source.is_dir():
        print(f"Source path '{source}' is not a valid directory.", file=logger)
        return

    # Attempt to create target directory structure
    try:
        target.mkdir(parents=True, exist_ok=True)
    except OSError as os_error:
        if os_error.errno == 13:  # Permission denied
            print(f"Permission denied: Cannot create directory '{target}'", file=logger)
        else:
            print(f"Failed to create directory '{target}': {os_error}", file=logger)
        return

    # Process each item in the source directory
    for entry in source.iterdir():
        try:
            if entry.is_dir():
                # Recursively process subdirectories
                copy_directory_tree(entry, target / entry.name, logger)
            else:
                # Copy files with metadata preservation
                shutil.copy2(entry, target / entry.name)
                print(f"Successfully copied '{entry}' to '{target / entry.name}'", file=logger)
        except PermissionError:
            print(f"Access denied when copying '{entry}' to '{target / entry.name}'", file=logger)
        except FileNotFoundError:
            print(f"Source file '{entry}' could not be found during copy operation", file=logger)
        except OSError as os_error:
            print(f"OS error while copying '{entry}' to '{target / entry.name}': {os_error}", file=logger)
        except Exception as unexpected_error:
            print(f"Unexpected error copying '{entry}' to '{target / entry.name}': {unexpected_error}", file=logger)

