def handle_doe_configuration(doe_count=10, weight_param=None):
    # Ensure doe_count defaults to 10 if not specified
    if doe_count is None:
        doe_count = 10

    # Handle weight_param initialization
    if weight_param is None:
        weight_param = None
    # Convert single float weight to list format
    elif isinstance(weight_param, (int, float)):
        weight_param = [float(weight_param)]
    # Validate iterable weights against doe_count
    elif hasattr(weight_param, '__iter__'):
        if len(weight_param) != doe_count:
            raise ValueError("Length of weight_param must match the number of stochastic input variables")
    else:
        raise ValueError("Invalid weight_param type provided")

    return doe_count, weight_param

import aiohttp
from typing import Optional, Dict, Union

async def fetch_data(url: str, proxy_url: Optional[str] = None, request_headers: Optional[Dict[str, str]] = None, payload: Optional[bytes] = None, connection_timeout: int = 15) -> Union[bytes, None]:
    try:
        async with aiohttp.ClientSession() as client_session:
            async with client_session.get(url, proxy=proxy_url, headers=request_headers, data=payload, timeout=connection_timeout) as http_response:
                if http_response.status == 200:
                    return await http_response.read()
                else:
                    return None
    except aiohttp.ClientError:
        return None

