class TaskManager(Cog):
    def __init__(self, debug_mode: bool = False) -> None:
        super().__init__("task_manager")
        self.debug_mode = debug_mode
        self.task_records = []

    def register_task(self, task_name: str) -> None:
        self.task_records.append({"name": task_name, "done": False})
        if self.debug_mode:
            log.debug(f"New task registered: {task_name}")

    def mark_task_done(self, position: int) -> None:
        if 0 <= position < len(self.task_records):
            self.task_records[position]["done"] = True
            if self.debug_mode:
                log.debug(f"Task marked as done: {self.task_records[position]['name']}")
        else:
            if self.debug_mode:
                log.debug(f"Attempted to access invalid task position: {position}")

    def display_tasks(self) -> List[str]:
        formatted_tasks = [
            f"{idx+1}. [{'X' if record['done'] else ' '}] {record['name']}"
            for idx, record in enumerate(self.task_records)
        ]
        if self.debug_mode:
            log.debug(f"Tasks displayed: {formatted_tasks}")
        return formatted_tasks

