from datetime import datetime

def create_date_filter(start: str = None, finish: str = None, specific_date: str = None) -> dict:
    if start and finish:
        # Parse and validate the date range
        begin_date = datetime.strptime(start, "%d/%m/%Y")
        conclude_date = datetime.strptime(finish, "%d/%m/%Y")
        if not (begin_date < conclude_date):
            raise ValueError("Start date must be earlier than end date.")

        return {POST_PUB_DATE: {
            "$gte": begin_date,
            "$lt": conclude_date
        }}

    elif specific_date:
        # Handle single date specification
        target_date = datetime.strptime(specific_date, "%d/%m/%Y")
        return {POST_PUB_DATE: target_date}

    else:
        # No valid date input provided
        raise ValueError("Must specify either a date range (start and finish) or a specific date.")

