import inspect
from functools import wraps
from typing import Any, Callable, Type, Union

def type_check(enable_input_validation=True, enable_output_validation=True):
    def decorator(fn: Callable) -> Callable:
        @wraps(fn)
        def wrapper(*input_args, **input_kwargs) -> Any:
            if enable_input_validation:
                func_sig = inspect.signature(fn)
                bound_params = func_sig.bind(*input_args, **input_kwargs)
                for arg_name, arg_value in bound_params.arguments.items():
                    expected_type = func_sig.parameters[arg_name].annotation
                    if expected_type is not inspect.Parameter.empty and not isinstance(arg_value, expected_type):
                        raise TypeError(f"Type mismatch for parameter '{arg_name}'. Expected {expected_type}, got {type(arg_value)}")

            output = fn(*input_args, **input_kwargs)

            if enable_output_validation:
                expected_return_type = func_sig.return_annotation
                if expected_return_type is not inspect.Parameter.empty and not isinstance(output, expected_return_type):
                    raise TypeError(f"Return type mismatch. Expected {expected_return_type}, got {type(output)}")

            return output
        return wrapper
    return decorator

