from typing import Optional, List
import requests
from typing_extensions import Literal

class PaginatedAPIHandler:
    MAX_RESULTS_LIMIT = 1000
    MAX_PER_PAGE = 50

    def fetch_results(self, page: int, per_page: int, previous_token: Optional[str]) -> Optional[List[str]]:
        # Check if we've exceeded the maximum allowed results
        if previous_token is not None and self.MAX_RESULTS_LIMIT > 0:
            current_offset = int(previous_token) * self.MAX_PER_PAGE
            if current_offset >= self.MAX_RESULTS_LIMIT:
                return None

        response = self._make_api_request(page, per_page, previous_token)
        if response is None:
            return None

        try:
            resp_data = response.json()
            # Handle list responses directly
            if isinstance(resp_data, list):
                return resp_data
            # For non-list responses (e.g., dict with 'results' key), extract appropriately
            elif isinstance(resp_data, dict):
                return resp_data.get("results", [])
            else:
                return []
        except (ValueError, AttributeError):
            return []

    def _make_api_request(self, page: int, per_page: int, previous_token: Optional[str]) -> Optional[requests.Response]:
        # Construct API endpoint with pagination parameters
        # This implementation uses a generic endpoint - adjust as needed for specific API
        url = "https://api.example.com/data"
        params = {
            "page": page,
            "per_page": per_page
        }

        if previous_token:
            params["offset"] = int(previous_token) * self.MAX_PER_PAGE

        try:
            response = requests.get(url, params=params, timeout=30)
            if response.status_code == 200:
                return response
            return None
        except requests.RequestException:
            return None

