# Validate package metadata structure and content types

def check_package_metadata(metadata: dict) -> bool:
    mandatory_fields = ['packages', 'license', 'description', 'long_description', 'long_description_content_type',
                        'install_requires', 'url', 'author', 'author_email']

    # Check presence of all required keys
    for field in mandatory_fields:
        if field not in metadata:
            return False

    # Validate packages field - must be non-empty list of strings
    packages = metadata['packages']
    if not isinstance(packages, list) or len(packages) == 0:
        return False
    for pkg in packages:
        if not isinstance(pkg, str):
            return False

    # Validate license field - must be non-empty string
    license_val = metadata['license']
    if not isinstance(license_val, str) or len(license_val.strip()) == 0:
        return False

    # Validate description field - must be non-empty string
    description = metadata['description']
    if not isinstance(description, str) or len(description.strip()) == 0:
        return False

    # Validate long_description field - must be non-empty string
    long_desc = metadata['long_description']
    if not isinstance(long_desc, str) or len(long_desc.strip()) == 0:
        return False

    # Validate long_description_content_type - must be 'text/markdown'
    content_type = metadata['long_description_content_type']
    if content_type != 'text/markdown':
        return False

    # Validate install_requires field - must be non-empty list of strings
    dependencies = metadata['install_requires']
    if not isinstance(dependencies, list) or len(dependencies) == 0:
        return False
    for dep in dependencies:
        if not isinstance(dep, str):
            return False

    # Validate url field - must be non-empty string
    project_url = metadata['url']
    if not isinstance(project_url, str) or len(project_url.strip()) == 0:
        return False

    # Validate author field - must be non-empty string
    author_name = metadata['author']
    if not isinstance(author_name, str) or len(author_name.strip()) == 0:
        return False

    # Validate author_email field - must be non-empty string
    author_email = metadata['author_email']
    if not isinstance(author_email, str) or len(author_email.strip()) == 0:
        return False

    return True

