from datetime import datetime, timedelta
from typing import Optional

class TaskLifecycle:
    def __init__(self, created_at: datetime, destroyed_at: datetime):
        self.created_at = created_at
        self.started_at: Optional[datetime] = None
        self.completed_at: Optional[datetime] = None
        self.destroyed_at = destroyed_at
        self.total_runtime: Optional[int] = None

    def begin_processing(self, start_timestamp: datetime) -> None:
        if start_timestamp < self.created_at or start_timestamp > self.destroyed_at:
            raise ValueError("Invalid start time")
        if self.started_at is not None or self.completed_at is not None:
            raise ValueError("Processing already initiated or concluded")
        self.started_at = start_timestamp

    def finish_processing(self, end_timestamp: datetime) -> None:
        if end_timestamp < self.created_at or end_timestamp > self.destroyed_at:
            raise ValueError("Invalid end time")
        if self.started_at is None:
            raise ValueError("Processing not yet started")
        if self.completed_at is not None:
            raise ValueError("Processing already completed")
        self.completed_at = end_timestamp
        self.total_runtime = int((self.completed_at - self.started_at).total_seconds())

    def retrieve_runtime(self) -> Optional[int]:
        if self.total_runtime is None:
            raise ValueError("Runtime data unavailable")
        return self.total_runtime

