from urllib.parse import urlparse, urlunparse

def hide_credentials_in_url(url):
    if not url:
        return url

    # Parse the URL into components
    parsed = urlparse(url)

    # Build a sanitized network location part
    host_part = parsed.hostname or ""

    # Add port if present
    if parsed.port is not None:
        host_part += f":{parsed.port}"

    # Replace credentials with masked version if any exist
    if parsed.username or parsed.password:
        host_part = f"***:***@{host_part}"

    # Reconstruct the URL with the modified netloc
    return urlunparse(parsed._replace(netloc=host_part))

