# DNS provider implementation for Name.com API v4
import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class NamecomDnsProvider(BaseDnsProvider):
    # Provider identification constants
    PROVIDER_TYPE = "namecom"
    PROVIDER_NAME = "Name.com"
    PROVIDER_DESCRIPTION = "Name.com DNS API v4"
    REQUIRED_CREDENTIALS = ["username", "api_token"]

    # API endpoint configuration
    BASE_URL = "https://api.name.com/v4"

    def _get_auth(self) -> Tuple[str, str]:
        """Return authentication credentials as tuple."""
        return (self.credentials['username'], self.credentials['api_token'])

    def _request(self, method: str, path: str, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        """Execute HTTP request to Name.com API with error handling."""
        url = f"{self.BASE_URL}{path}"
        try:
            response = requests.request(
                method=method,
                url=url,
                auth=self._get_auth(),
                json=data,
                timeout=30,
                headers={'Content-Type': 'application/json'}
            )

            if response.status_code >= 400:
                try:
                    error_details = response.json().get('message', response.reason)
                except Exception:
                    error_details = response.reason
                return False, error_details

            return True, response.json() if response.text else None

        except requests.RequestException as exception:
            return False, str(exception)

    def _locate_domain(self, domain: str) -> Optional[str]:
        """Search for the longest matching domain in the account."""
        domain_segments = domain.split('.')
        for index in range(len(domain_segments) - 1, 0, -1):
            candidate = '.'.join(domain_segments[index:])
            success, result = self._request('GET', f'/domains/{candidate}')
            if success:
                return candidate
        return None

    def create_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        """Create a new TXT record for the specified domain."""
        found_domain = self._locate_domain(domain)
        if not found_domain:
            return False, f"Could not locate domain {domain}"

        # Ensure FQDN format
        fqdn = record_name if record_name.endswith('.') else record_name + '.'

        # Prepare record payload
        payload = {
            'host': self.get_relative_record_name(record_name, found_domain),
            'type': 'TXT',
            'answer': record_value,
            'ttl': ttl,
            'fqdn': fqdn
        }

        success, result = self._request('POST', f'/domains/{found_domain}/records', payload)
        if not success:
            return False, f"Failed to create record: {result}"

        return True, "Record created successfully"

    def delete_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        """Delete a TXT record matching the specified criteria."""
        found_domain = self._locate_domain(domain)
        if not found_domain:
            return False, f"Could not locate domain {domain}"

        # Retrieve existing records
        success, result = self._request('GET', f'/domains/{found_domain}/records')
        if not success:
            return False, f"Failed to list records: {result}"

        # Find and delete matching TXT record
        host_part = self.get_relative_record_name(record_name, found_domain)
        for record in result.get('records', []):
            if (record.get('type') == 'TXT' and 
                record.get('host') == host_part):
                self._request('DELETE', f'/domains/{found_domain}/records/{record["id"]}')

        return True, "Record deleted successfully"

    def test_connection(self) -> Tuple[bool, str]:
        """Test API connectivity by listing available domains."""
        success, result = self._request('GET', '/domains')
        if success:
            domains_list = result.get('domains', [])
            return True, f"Connected. Found {len(domains_list)} domain(s)"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls) -> list:
        """Return credential schema definition for UI generation."""
        return [
            {
                'name': 'username',
                'label': 'Username',
                'type': 'text',
                'required': True
            },
            {
                'name': 'api_token',
                'label': 'API Token',
                'type': 'password',
                'required': True,
                'help': 'name.com > Account > API Token'
            }
        ]

import torch
from vllm.distributed import get_pcp_group
from vllm_ascend.platform import ModelConfig
from vllm_ascend.utils import singleton

def _create_causal_mask(max_len: int, data_type: torch.dtype) -> torch.Tensor:
    # Build lower triangular mask (causal)
    causal_flag = torch.tril(torch.ones((max_len, max_len), dtype=torch.bool))
    # Invert to mark positions that should be masked
    inverted_mask = ~causal_flag
    # Set mask values based on precision: -inf for float16, 0 otherwise
    fill_value = float("-inf") if data_type == torch.float16 else 0.0
    result = torch.zeros((max_len, max_len), dtype=data_type)
    result = result.masked_fill(inverted_mask, fill_value)
    return result

@singleton
class CausalAttentionMaskFactory:
    def __init__(self, device: torch.device):
        self._cached_mask = None
        self._max_cached_length = 0
        self.target_device = device
        self.mla_prefill_mask = None
        self.splitfuse_mask = None
        self.pcp_mla_pattern = None
        self.sliding_window_mask = None

    def obtain_causal_mask(self, required_length: int, target_dtype: torch.dtype) -> torch.Tensor:
        # Rebuild mask if cache is missing or insufficient size
        if self._cached_mask is None or required_length > self._max_cached_length:
            self._cached_mask = _create_causal_mask(required_length, target_dtype)
            self._max_cached_length = required_length

        assert self._cached_mask is not None, "Causal mask generation failed unexpectedly"

        # Ensure correct dtype and move to target device
        if self._cached_mask.dtype != target_dtype:
            self._cached_mask = self._cached_mask.to(target_dtype)

        return self._cached_mask[:required_length, :required_length].contiguous().to(
            self.target_device, non_blocking=True
        )

    def get_split_fuse_pattern(self) -> torch.Tensor:
        if self.splitfuse_mask is None:
            self.splitfuse_mask = (
                torch.triu(torch.ones(2048, 2048, dtype=torch.int8), diagonal=1).to(self.target_device)
            )
        return self.splitfuse_mask

    def acquire_mla_mask(self, dtype: torch.dtype) -> torch.Tensor:
        if self.mla_prefill_mask is None or self.mla_prefill_mask.dtype != dtype:
            if dtype == torch.float16:
                fill_val = torch.finfo(torch.float32).min
            else:
                fill_val = 0.0

            triu_pattern = torch.triu(torch.ones(512, 512, device=self.target_device, dtype=dtype), diagonal=1)
            self.mla_prefill_mask = torch.where(triu_pattern == 1, fill_val, 0.0).to(dtype)
        return self.mla_prefill_mask

    def fetch_pcp_mla_pattern(self, dtype: torch.dtype) -> torch.Tensor:
        if self.pcp_mla_pattern is None or self.pcp_mla_pattern.dtype != dtype:
            self.pcp_mla_pattern = torch.triu(
                torch.ones(512, 512, device=self.target_device, dtype=dtype), diagonal=1
            )
        return self.pcp_mla_pattern

    def build_sliding_window_mask(self, dtype: torch.dtype, window_size: int) -> torch.Tensor:
        if self.sliding_window_mask is None or self.sliding_window_mask.dtype != dtype:
            if window_size is not None:
                base_mask = torch.ones(2048, 2048, dtype=torch.bool, device=self.target_device)
                upper_tri = torch.triu(base_mask, diagonal=1)
                lower_tri = torch.tril(base_mask, -window_size)
                combined = upper_tri.logical_or(lower_tri)
                self.sliding_window_mask = combined.to(dtype)
        return self.sliding_window_mask

    def produce_attention_mask(self, config: ModelConfig) -> torch.Tensor:
        if config.runner_type == "pooling":
            return self.obtain_causal_mask(2048, torch.bool)
        return self.get_split_fuse_pattern()

    def produce_optimized_mla_mask(self, config: ModelConfig) -> torch.Tensor:
        if get_pcp_group().world_size > 1:
            return self.fetch_pcp_mla_pattern(config.dtype)
        return self.acquire_mla_mask(config.dtype)

import random
import numpy as np
import torch

def create_data_iterators(train_loader=None, val_loader=None, test_loader=None, mode="cycle"):
    def _infinite_cycle(loader):
        while True:
            for batch in loader:
                yield batch

    def _make_iterator(data_loader, strategy=mode):
        """Generate appropriate iterator based on strategy."""
        if strategy == "once":
            return iter(data_loader)
        elif strategy == "cycle":
            return iter(_infinite_cycle(data_loader))
        else:
            raise ValueError(f"Unsupported iteration mode: {strategy}")

    # Create iterators for each provided dataset
    train_iter = _make_iterator(train_loader) if train_loader is not None else None
    val_iter = _make_iterator(val_loader) if val_loader is not None else None
    test_iter = _make_iterator(test_loader) if test_loader is not None else None

    return train_iter, val_iter, test_iter

def setup_deterministic_worker(seed_value):
    """Configure workers for reproducible data loading."""
    def worker_init_fn(worker_id):
        # Set seeds for all relevant libraries
        np.random.seed(seed_value)
        torch.manual_seed(seed_value)
        random.seed(seed_value)
    return worker_init_fn

# Type III Clone: DenseMLPProfiler with refactored logic and variable names

from typing import Optional, Tuple
from primus.core.projection.base_module_profiler import BaseModuleProfiler
from primus.core.projection.profiler_spec import ModuleProfilerSpec
from primus.core.projection.training_config import TrainingConfig
from .utils import benchmark_layer


class DenseFeedForwardProfiler(BaseModuleProfiler):
    def __init__(self, settings, inner_profilers=None):
        super().__init__(settings, inner_profilers)
        self.target_module = None  # Will be assigned during profiling
        self._profile_cache = None  # Stores (fwd_duration, bwd_duration, act_mem_usage)
        self._cache_identifier = None  # Identifier for cache: (batch_dim, sequence_length)

    def assign_module(self, module):
        """Assign the concrete Dense Feed-Forward Network module to profile."""
        self.target_module = module
        # Reset cache upon module change
        self._profile_cache = None
        self._cache_identifier = None

    def count_parameters(self, rank: Optional[int] = None) -> int:
        # SwiGLU uses three linear layers (gate, up, down); standard FFN uses two (up, down)
        ffn_projection_count = 3 if self.settings.model_config.swiglu else 2
        return (
            self.settings.model_config.hidden_dimension
            * self.settings.model_config.intermediate_dimension
            * ffn_projection_count
        )

    def estimate_activation_storage(self, batch_size: int, seq_len: int) -> int:
        effective_tokens = (
            batch_size
            * seq_len
            // self.settings.model_parallel.tensor_model_parallel_degree
            // self.settings.model_parallel.context_model_parallel_degree
        )
        # Memory footprint after initial projections
        if self.settings.model_config.swiglu:
            # Store both gate and up activations for backward pass (bf16)
            temp_memory = 2 * effective_tokens * self.settings.model_config.intermediate_dimension * 2
        else:
            temp_memory = effective_tokens * self.settings.model_config.intermediate_dimension * 2  # bf16
        # After activation function
        post_activation_memory = effective_tokens * self.settings.model_config.intermediate_dimension * 2  # bf16
        # Output layer memory
        output_memory = effective_tokens * self.settings.model_config.hidden_dimension * 2  # bf16
        # Peak memory = input + intermediate (both required for gradient computation)
        return temp_memory + post_activation_memory + output_memory

    def _fetch_profile_data(self, batch_size: int, seq_len: int) -> Tuple[float, float, int]:
        """Retrieve or compute benchmark data (with caching)."""
        identifier = (batch_size, seq_len)
        if self._profile_cache is None or self._cache_identifier != identifier:
            self._profile_cache = benchmark_layer(
                self.target_module,
                [(seq_len, batch_size, self.settings.model_config.hidden_dimension)],
            )
            self._cache_identifier = identifier
        return self._profile_cache

    def get_forward_latency(self, batch_size: int, seq_len: int) -> float:
        fwd_time, _, _ = self._fetch_profile_data(batch_size, seq_len)
        return fwd_time

    def get_backward_latency(self, batch_size: int, seq_len: int) -> float:
        _, bwd_time, _ = self._fetch_profile_data(batch_size, seq_len)
        return bwd_time

    def get_activation_storage(self, batch_size: int, seq_len: int) -> int:
        _, _, stored_activation = self._fetch_profile_data(batch_size, seq_len)
        return stored_activation


def create_dense_ffn_profiler_spec(config: TrainingConfig) -> ModuleProfilerSpec:
    return ModuleProfilerSpec(
        profiler=DenseFeedForwardProfiler,
        config=config,
        sub_profiler_specs=None,
    )

