    controller = Turtle2SmoothController.launch_controller(freq=50)

    while True:
        try:
            user_input = input("Enter command (q to quit, getpos, reset, go): ")

            if user_input == "q":
                print("Exiting...")
                break
            elif user_input == "getpos":
                state_data = controller.get_state().wait()
                position = state_data[0].follow2_pos
                print(f"Current position: {position}")
            elif user_input == "reset":
                controller.reset_arms().wait()
                print("Arms reset.")
            elif user_input == "go":
