                    [0, 0, 0, 0, 0, 0, 0],
                    [0.27, 0.09, 0.02, 0.0, 1.0, 0.5, 0.0],
                ).wait()
            else:
                print(f"Unrecognized command: '{user_input}'")

        except KeyboardInterrupt:
