import os
from typing import Dict
from agent.tool_base import Tool

class FileWriteTool(Tool):
    name = "file_write"
    description = "Saves text content to a specified file path, automatically creating any missing parent directories."
    parameters = {
        "type": "object",
        "properties": {
            "destination": {
                "type": "string",
                "description": "Target file location where the content should be saved.",
            },
            "data": {
                "type": "string",
                "description": "The textual data to store in the file.",
            },
        },
        "required": ["destination", "data"],
    }

    async def execute(self, arguments: Dict) -> str:
        target_path = arguments["destination"]
        file_data = arguments["data"]

        try:
            # Extract directory portion of the path
            folder_path = os.path.dirname(target_path)

            # Create directory structure if needed
            if folder_path and not os.path.exists(folder_path):
                await self.run_cmd(cmd=["mkdir", "-p", folder_path])

            # Write content to file using tee command
            await self.run_cmd(cmd=["tee", target_path], stdin=file_data)

            return f"Content successfully saved to {target_path}"
        except Exception as error:
            return f"Failed to write file: {error}"

import gc
import weakref
from typing import Any, Dict, List, Tuple
from statgpt.common.config import multiline_logger as logger

class GarbageCollectorMonitor:
    """Monitor and inspect object lifecycle via weak references."""

    def __init__(self):
        self._monitored_refs: Dict[str, weakref.ReferenceType] = {}

    def register_instance(self, target: Any, label: str):
        """Register an object for lifecycle monitoring using a weak reference."""
        def _on_deletion(ref):
            # Capture type before deletion (though obj may be gone)
            try:
                obj_type = getattr(target, '__class__', type(target)).__name__
            except Exception:
                obj_type = "unknown"
            logger.info(f"GC: Instance '{label}' (type={obj_type}) has been deallocated")

        try:
            instance_type = type(target).__name__
        except Exception:
            instance_type = "unknown"

        # Create weak reference with callback
        proxy = weakref.ref(target, _on_deletion)
        self._monitored_refs[label] = proxy
        logger.info(f"GC: Now monitoring instance '{label}' (type={instance_type}, addr={id(target)})")

    def inspect_registered(self) -> Tuple[List[Tuple[str, str, int]], List[str]]:
        """Determine which registered instances are still active."""
        present: List[Tuple[str, str, int]] = []
        absent: List[str] = []

        for label, proxy in self._monitored_refs.items():
            candidate = proxy()
            if candidate is not None:
                try:
                    typ = type(candidate).__name__
                except Exception:
                    typ = "unknown"
                present.append((label, typ, id(candidate)))
            else:
                absent.append(label)

        if present:
            logger.info("GC: Active instances:")
            for lbl, typ, addr in present:
                logger.info(f"  - {lbl} (type={typ}, addr={addr})")
        if absent:
            logger.info(f"GC: Deallocated instances: {absent}")
        return present, absent

    def trace_references(self, label: str, max_count: int = 5) -> str:
        """Trace objects referencing a monitored instance."""
        proxy = self._monitored_refs.get(label)
        if proxy is None:
            return f"Instance '{label}' is not under observation"

        referent = proxy()
        if referent is None:
            return f"Instance '{label}' no longer exists"

        referrers = gc.get_referrers(referent)
        logger.info(f"GC: Instance '{label}' is referenced by {len(referrers)} sources:")
        count = 0
        for source in referrers:
            if count >= max_count:
                break
            try:
                src_typ = type(source).__name__
            except Exception:
                src_typ = "unknown"

            if src_typ == 'frame':
                continue  # Omit internal frame data

            logger.info(f"  [{count}] Kind: {src_typ}")
            if hasattr(source, '__name__'):
                logger.info(f"      Name: {getattr(source, '__name__', '')}")
            if hasattr(source, '__class__'):
                cls_name = getattr(getattr(source, '__class__', None), '__name__', '')
                logger.info(f"      Class: {cls_name}")
            if isinstance(source, dict):
                keys_sample = list(source.keys())[:3]
                logger.info(f"      Keys: {keys_sample}")
            count += 1

        return f"Identified {len(referrers)} referrers for '{label}'"


