def report_gc_metrics():
    """Output garbage collection statistics and trigger manual collection."""
    gen_stats = gc.get_stats()
    for idx, stats in enumerate(gen_stats):
        logger.info(
            f"GC Level {idx}: runs={stats['collections']}, "
            f"freed={stats['collected']}, orphaned={stats['uncollectable']}"
        )

    logger.info("GC: Initiating full collection...")
    reclaimed = gc.collect()
    logger.info(f"GC: Recovered {reclaimed} unreachable objects")

    # Inspect any unreachable objects that couldn't be freed
    if gc.garbage:
        logger.warning(f"GC: Detected {len(gc.garbage)} unreclaimable items!")
        for item in gc.garbage[:5]:
            try:
                item_typ = type(item).__name__
            except Exception:
                item_typ = "unknown"
            logger.warning(f"  - Type: {item_typ}, ID: {id(item)}")

