import json
from pathlib import Path

# Define the path to the log file relative to the project root
LOG_FILE = Path(__file__).resolve().parent.parent / 'skills' / 'logs' / 'token_log.jsonl'

def filter_high_usage(limit=1000):
    # Return empty list if log file doesn't exist
    if not LOG_FILE.is_file():
        print('Log file not found at', LOG_FILE)
        return []

    results = []
    with LOG_FILE.open('r', encoding='utf-8') as file:
        for record in file:
            try:
                data = json.loads(record.strip())
                # Check if token count meets or exceeds threshold
                if data.get('total_tokens', 0) >= limit:
                    results.append(data)
            except (json.JSONDecodeError, TypeError):
                # Skip malformed lines
                pass
    return results

