# Custom exception hierarchy for HTTP and request-related errors

from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """Base exception for ambiguous errors during request handling."""

    def __init__(self, *args, **kwargs):
        # Extract response and request from kwargs if provided
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)

        # If response exists but no explicit request, try to get it from response
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = response.request

        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """Raised when a JSON parsing error occurs."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Raised when text cannot be decoded into JSON format."""

    def __init__(self, *args, **kwargs):
        # Initialize parent classes separately to preserve JSON-specific args
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """Raised when an HTTP protocol error occurs."""

class ConnectionError(RequestException):
    """Raised when network connection fails."""

class ProxyError(ConnectionError):
    """Raised when proxy configuration or connection fails."""

class SSLError(ConnectionError):
    """Raised when SSL/TLS handshake or certificate verification fails."""

class Timeout(RequestException):
    """Raised when request operations exceed time limits.

    This exception encompasses both connection and read timeout scenarios.
    """

class ConnectTimeout(ConnectionError, Timeout):
    """Raised when connection establishment exceeds the allowed time limit.

    These requests are typically safe to retry.
    """

class ReadTimeout(Timeout):
    """Raised when server takes too long to send response data."""

class URLRequired(RequestException):
    """Raised when a valid URL is necessary but missing."""

class TooManyRedirects(RequestException):
    """Raised when redirect limit is exceeded."""

class MissingSchema(RequestException, ValueError):
    """Raised when URL lacks required scheme (e.g., 'http://' or 'https://')."""

class InvalidSchema(RequestException, ValueError):
    """Raised when URL uses unsupported or invalid scheme."""

class InvalidURL(RequestException, ValueError):
    """Raised when URL format is malformed or syntactically incorrect."""

class InvalidHeader(RequestException, ValueError):
    """Raised when HTTP header value is invalid or improperly formatted."""

class InvalidProxyURL(InvalidURL):
    """Raised when proxy URL is syntactically invalid."""

class ChunkedEncodingError(RequestException):
    """Raised when server sends malformed chunked encoding data."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Raised when response content cannot be properly decoded."""

class StreamConsumedError(RequestException, TypeError):
    """Raised when attempting to consume already consumed response content."""

class RetryError(RequestException):
    """Raised when custom retry logic fails to complete successfully."""

class UnrewindableBodyError(RequestException):
    """Raised when body cannot be rewound after failed transmission attempt."""

# Warning classes
class RequestsWarning(Warning):
    """Base warning class for Requests library warnings."""

class FileModeWarning(RequestsWarning, DeprecationWarning):
    """Raised when file is opened in text mode but binary length is detected."""

class RequestsDependencyWarning(RequestsWarning):
    """Raised when imported dependency version doesn't meet requirements."""

# Clone: Type III — Functional equivalence with structural variation

from abc import ABC, abstractmethod
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes


class _ToolFactoryMap(MutableMapping):
    """Custom registry for mapping tool types to their constructor classes."""

    def __init__(self) -> None:
        self._store: dict[ToolTypes, type['StatGptBase']] = {}

    def __setitem__(self, key: ToolTypes, value: type['StatGptBase']) -> None:
        if not issubclass(value, StatGptBase):
            raise TypeError(f"{value} must inherit from {StatGptBase}")
        if key in self._store:
            raise RuntimeError(
                f"Duplicate registration attempt: '{key}' already bound to {self._store[key]}"
            )
        self._store[key] = value

    def __delitem__(self, key: ToolTypes) -> None:
        del self._store[key]

    def __getitem__(self, key: ToolTypes) -> type['StatGptBase']:
        if key not in self._store:
            raise KeyError(
                f"No handler registered for tool type '{key}'. "
                f"Ensure the corresponding module is imported globally.\n"
                f"Registered types: {list(self._store.keys())}"
            )
        return self._store[key]

    def __iter__(self):
        return iter(self._store)

    def __len__(self):
        return len(self._store)


# Global registry instance
_TOOL_REGISTRY = _ToolFactoryMap()


class InputContext(BaseModel):
    """Schema for contextual inputs passed during tool execution."""
    # injected by framework; excluded from LLM-visible schema
    context_data: Annotated[dict, InjectedToolArg] = Field(default_factory=dict)


T_Config = TypeVar('T_Config', bound=BaseToolConfig)


class StatGptBase(BaseTool, ABC, Generic[T_Config]):
    """Abstract base class for all StatGPT tools with async-first design."""

    response_mode: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    category: ToolTypes  # Dynamically assigned via subclass hook

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)

        # Skip registration for abstract base itself
        if cls.__bases__ == (ABC, BaseTool, Generic):
            return

        tool_category = kwargs.pop('category', None)
        if tool_category is None:
            raise ValueError(f"Subclass {cls.__name__} must define 'category'")
        if not isinstance(tool_category, ToolTypes):
            raise TypeError(f"'{tool_category}' is not a valid {ToolTypes}")

        cls.category = tool_category
        _register_tool(cls, tool_category)

    def __init__(self, config: T_Config, channel_settings: ChannelConfig, **extra):
        super().__init__(**extra)
        self._config = config
        self._channel = channel_settings

    @property
    def step_label(self) -> str:
        """Human-readable label for the current execution phase."""
        override = self._config.details.stages_config.tool_call_name
        if override:
            return override
        pretty_name = self.name.replace('_', ' ').title()
        return f"Executing {pretty_name} step"

    @property
    def output_label(self) -> str:
        """Label used when presenting results."""
        override = self._config.details.stages_config.tool_result_name
        if override:
            return override
        pretty_name = self.name.replace('_', ' ').title()
        return f"Output from {pretty_name} operation"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """Synchronous fallback — intentionally disabled."""
        raise NotImplementedError("Sync execution is unsupported. Use async method.")

    @abstractmethod
    async def execute_async(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        """Core async execution method."""
        pass

    @classmethod
    def input_schema(cls, cfg: T_Config) -> type[InputContext]:
        """Return the argument schema expected by this tool."""
        return InputContext

    @staticmethod
    def build(config: T_Config, channel: ChannelConfig) -> 'StatGptBase':
        """Factory method to instantiate a tool from configuration."""
        handler_class = _TOOL_REGISTRY[config.type]
        return handler_class(
            config=config,
            channel_settings=channel,
            name=config.name,
            description=config.description,
            args_schema=handler_class.input_schema(config),
        )


def _register_tool(tool_cls: type['StatGptBase'], category: ToolTypes) -> None:
    """Internal helper to register a concrete tool class."""
    _TOOL_REGISTRY[category] = tool_cls

import re
from pathlib import Path
from typing import Any, Dict, Optional, Tuple
import yaml

class SkillLoader:
    """Load and parse SKILL.md files."""

    # Pattern to match YAML frontmatter enclosed in triple dashes
    FRONTMATTER_REGEX = re.compile(r"^---\s*\n(.*?)\n---\s*\n(.*)$", re.DOTALL)

    @classmethod
    def load(cls, file_path_str: str) -> Dict[str, Any]:
        """Load Skill from file and return as dict."""
        path_obj = Path(file_path_str)
        if not path_obj.is_file():
            raise FileNotFoundError(f"Skill file not found: {file_path_str}")

        raw_text = path_obj.read_text(encoding="utf-8")
        return cls.parse(raw_text, source_path=str(path_obj))

    @classmethod
    def parse(cls, text_content: str, origin_path: str = "") -> Dict[str, Any]:
        """Parse SKILL.md content and return as dict."""
        header_section, main_body = cls._extract_header_and_body(text_content)

        if header_section is None or header_section.strip() == "":
            raise ValueError("SKILL.md must have YAML frontmatter")

        try:
            metadata = yaml.safe_load(header_section)
        except yaml.YAMLError:
            raise ValueError("Invalid YAML frontmatter")

        if not isinstance(metadata, dict):
            raise ValueError("Invalid YAML frontmatter")

        required_fields = ["name", "description"]
        for field in required_fields:
            if field not in metadata:
                raise ValueError(f"Skill must have '{field}' field")

        return {
            "name": metadata["name"],
            "description": metadata["description"],
            "content": main_body.strip(),
            "source_path": origin_path,
            "allowed_tools": metadata.get("allowed-tools", []),
            "tags": metadata.get("tags", []),
        }

    @classmethod
    def _extract_header_and_body(cls, full_content: str) -> Tuple[Optional[str], str]:
        """Extract frontmatter and body from content."""
        match = cls.FRONTMATTER_REGEX.match(full_content)
        if match:
            return match.group(1), match.group(2)
        return None, full_content

    @classmethod
    def to_skill_md(cls, skill_data: Dict[str, Any]) -> str:
        """Convert skill dict to SKILL.md format."""
        header_dict: dict = {
            "name": skill_data["name"],
            "description": skill_data.get("description", ""),
        }

        yaml_output = yaml.dump(
            header_dict, 
            allow_unicode=True, 
            sort_keys=False
        )

        body_text = skill_data.get("content", "")
        return f"---\n{yaml_str.rstrip()}\n---\n\n{body_text}"

# CS:GO Match Statistics Analyzer - Type III Clone
# This script retrieves and analyzes a player's match data from the Leetify API

import sys
import json
import argparse
import requests
import subprocess
import os
from datetime import datetime

# Retrieve API key from environment variables
API_KEY = os.getenv("LEETIFY_API_KEY")
if not API_KEY:
    print(json.dumps({"error": "LEETIFY_API_KEY environment variable not set"}))
    sys.exit(1)

# Define the base URL for the Leetify public API
API_BASE_URL = "https://api-public.cs-prod.leetify.com"

def make_api_call(path, query_params=None):
    """Send an authenticated GET request to the Leetify API"""
    auth_headers = {"Authorization": f"Bearer {API_KEY}"}
    full_url = f"{API_BASE_URL}{path}"

    try:
        api_response = requests.get(full_url, params=query_params, headers=auth_headers)
        if api_response.status_code == 200:
            return {"success": True, "payload": api_response.json()}
        else:
            return {
                "success": False, 
                "error_msg": f"HTTP {api_response.status_code}: {api_response.text}"
            }
    except Exception as exc:
        return {"success": False, "error_msg": str(exc)}

def fetch_player_match_details(player_steam_id, match_position=0):
    # Step 1: Fetch list of recent matches for the player
    match_list_result = make_api_call(
        '/v3/profile/matches', 
        {'steam64_id': player_steam_id, 'limit': match_position + 1}
    )

    if not match_list_result['success']:
        print(json.dumps({"error": match_list_result.get('error_msg')}))
        return

    raw_matches = match_list_result['payload']

    # Normalize response format (some endpoints return wrapped data)
    if isinstance(raw_matches, dict) and 'matches' in raw_matches:
        raw_matches = raw_matches['matches']

    if not isinstance(raw_matches, list):
        print(json.dumps({"error": "Unexpected API response structure"}))
        return

    total_matches = len(raw_matches)
    if match_position >= total_matches:
        print(json.dumps({
            "error": f"Match index {match_position} out of range. Available matches: {total_matches}"
        }))
        return

    selected_match = raw_matches[match_position]

    # Step 2: Locate the current player's stats within the match
    player_record = next(
        (record for record in selected_match.get('player_stats', []) 
         if record['steam64_id'] == player_steam_id), 
        None
    )

    if not player_record:
        print(json.dumps({"error": "Player statistics not found in this match"}))
        return

    # Step 3: Build comprehensive analysis object
    match_analysis = {
        "metadata": {
            "map_name": selected_match.get('map'),
            "timestamp": selected_match.get('end_time'),
            "final_score": selected_match.get('scoreboard'),
            "source": selected_match.get('ingest_source'),
            "match_uuid": selected_match.get('match_id')
        },
        # Full player performance metrics including:
        # - Accuracy and hit distribution
        # - Utility usage and effectiveness
        # - Entry/entry-frag stats
        # - Clutch attempts and success rate
        # - Spray patterns and control
        "performance": player_record
    }

    # Output formatted JSON for downstream processing
    print(json.dumps(match_analysis, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    cli_parser = argparse.ArgumentParser(description="Analyze CS:GO match statistics")
    cli_parser.add_argument("--player", required=True, help="Steam username to analyze")
    cli_parser.add_argument("--match", type=int, default=0, help="Match index (0 = most recent)")
    arguments = cli_parser.parse_args()

    current_script_path = os.path.dirname(os.path.abspath(__file__))

    try:
        # Resolve Steam username to Steam ID using external utility
        steam_id_output = subprocess.check_output(
            ['python3', os.path.join(current_script_path, 'steam_ids.py'), 'resolve', '--user', arguments.player],
            text=True
        ).strip()

        if not steam_id_output or "not found" in steam_id_output.lower():
            print(json.dumps({"error": f"Could not resolve Steam ID for user '{arguments.player}'"}))
            sys.exit(1)

        target_steam_id = steam_id_output

    except Exception as error:
        print(json.dumps({"error": f"Steam ID lookup failed: {str(error)}"}))
        sys.exit(1)

    fetch_player_match_details(target_steam_id, arguments.match)

