from typing import Dict
from agent.tool_base import Tool

class FileEditTool(Tool):
    name = "file_edit"
    description = (
        "Replace a specific substring in a file with a new one. "
        "The target substring must appear exactly once and match precisely (including whitespace). "
        "Include sufficient surrounding context to ensure uniqueness."
    )
    parameters = {
        "type": "object",
        "properties": {
            "filepath": {
                "type": "string",
                "description": "Path to the file that needs modification.",
            },
            "target_text": {
                "type": "string",
                "description": "Exact text to locate and substitute. Must be unique within the file.",
            },
            "replacement_text": {
                "type": "string",
                "description": "Text to insert in place of the target.",
            },
        },
        "required": ["filepath", "target_text", "replacement_text"],
    }

    async def execute(self, arguments: Dict) -> str:
        filepath = arguments["filepath"]
        target_text = arguments["target_text"]
        replacement_text = arguments["replacement_text"]

        try:
            file_content = await self.run_cmd(cmd=["cat", filepath])
        except Exception as err:
            return f"Failed to read file: {err}"

        if target_text == replacement_text:
            return "No operation needed: target and replacement are identical."

        occurrences = file_content.count(target_text)
        if occurrences == 0:
            return "Error: specified text not found in file."
        if occurrences > 1:
            return f"Error: found {occurrences} matches for target text. Provide more context to uniquely identify it."

        updated_content = file_content.replace(target_text, replacement_text, 1)

        try:
            await self.run_cmd(cmd=["tee", filepath], stdin=updated_content)
            return f"File '{filepath}' updated successfully"
        except Exception as write_error:
            return f"Error saving changes: {write_error}"

import json
from volcengine.base.Service import Service
