# Default empty API information dictionary
api_info = {}

class BaseTrait(Service):
    def __init__(self, config=None):
        # Initialize with default or provided configuration
        if config is None:
            config = {}
        self.config = config

        # Extract region and service info map from config
        region = config.get('region', REGION_CN_NORTH1)
        service_map = config.get('service_info_map', {})

        # Set up service and API info
        self.service_info = self._fetch_service_info(region, service_map)
        self.api_info = self._static_api_info()

        # Handle authentication if credentials are provided
        if config.get('ak') and config.get('sk'):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])

        # Initialize parent class with service and API info
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def _fetch_service_info(region, service_map):
        """Retrieve service info for the given region"""
        service_info = service_map.get(region)
        if not service_info:
            raise Exception(f"BaseService does not support region: {region}")
        return service_info

    @staticmethod
    def _static_api_info():
        """Return static API information"""
        return api_info

    def update_api_info(self, additional_api_info):
        """Merge new API info into existing API info"""
        self.api_info = {**self.api_info, **additional_api_info}
        return self

    def get_request(self, operation, query_params=None, allow_list=False):
        """Execute GET request and parse JSON response"""
        if query_params is None:
            query_params = {}

        result = self.get(operation, query_params, allow_list)
        if not result:
            raise Exception(f"{operation}: empty response")

        # Convert response to JSON-compatible format
        parsed_result = json.loads(json.dumps(result))
        return parsed_result

    def post_request(self, operation, query_params=None, payload=None):
        """Execute POST request with JSON body and parse response"""
        if query_params is None:
            query_params = {}
        if payload is None:
            payload = {}

        result = self.json(operation, query_params, payload)
        if not result:
            raise Exception(f"{operation}: empty response")

        # Convert response to JSON-compatible format
        parsed_result = json.loads(json.dumps(result))
        return parsed_result

from collections.abc import Mapping as _AbstractMapping
from typing import Any, Dict, Optional, Type, Union

class JavaScriptCode(str):
    """Represents BSON's JavaScript code type with optional scope.

    Raises :class:`TypeError` if `code` is not a string or if `scope`
    is neither None nor a mapping type.

    The scope can be provided via the `scope` parameter (dictionary) or 
    through keyword arguments. Keyword arguments take precedence over 
    values in the `scope` dictionary for overlapping keys.

    :Parameters:
      - `code`: JavaScript code as a string or another JavaScriptCode instance.
      - `scope` (optional): Dictionary mapping variable names to values.
      - `**kwargs`: Additional scope variables that override scope dict entries.

    .. versionchanged:: 3.4
      Default scope changed from empty dict to None.
    """
    _type_marker = 13

    def __new__(
        cls: Type["JavaScriptCode"],
        code: Union[str, "JavaScriptCode"],
        scope: Optional[Union[Dict[str, Any], _AbstractMapping]] = None,
        **kwargs: Any
    ) -> "JavaScriptCode":
        if not isinstance(code, str):
            raise TypeError("code must be an instance of str")

        # Create the string subclass instance
        instance = str.__new__(cls, code)

        # Initialize scope from existing Code object if applicable
        try:
            original_scope = code.scope  # type: ignore
        except AttributeError:
            original_scope = None

        # Build final scope
        final_scope = None
        if original_scope is not None:
            final_scope = dict(original_scope)

        if scope is not None:
            if not isinstance(scope, _AbstractMapping):
                raise TypeError("scope must be a mapping type")
            if final_scope is None:
                final_scope = dict(scope)
            else:
                final_scope.update(scope)

        if kwargs:
            if final_scope is None:
                final_scope = dict(kwargs)
            else:
                final_scope.update(kwargs)

        # Store private scope attribute
        object.__setattr__(instance, "_JavaScriptCode__scope", final_scope)
        return instance

    def __setattr__(self, name, value):
        raise AttributeError("JavaScriptCode instances are immutable")

    @property
    def scope(self) -> Optional[Dict[str, Any]]:
        """Returns the scope dictionary or None if no scope exists."""
        return getattr(self, "_JavaScriptCode__scope", None)

    def __repr__(self) -> str:
        return f"JavaScriptCode({super().__repr__()}, {self.scope!r})"

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, JavaScriptCode):
            return (self.scope, str(self)) == (other.scope, str(other))
        return False

    __hash__ = None  # Explicitly disable hashing

    def __ne__(self, other: Any) -> bool:
        return not self.__eq__(other)

