from .tools import PipelineTool

class AudioTranscriptionTool(PipelineTool):
    default_checkpoint = "distil-whisper/distil-large-v3"
    description = "This tool converts spoken audio into written text by performing speech recognition."
    name = "speech_to_text_converter"
    pre_processor_class = WhisperProcessor
    model_class = WhisperForConditionalGeneration
    inputs = {"audio": {"type": "audio", "description": "Audio file containing speech to transcribe"}}
    output_type = "text"

    def prepare_input(self, audio_data):
        return self.pre_processor(audio_data, return_tensors="pt")

    def process_audio(self, processed_inputs):
        return self.model.generate(processed_inputs["input_features"])

    def format_output(self, generated_tokens):
        return self.pre_processor.batch_decode(generated_tokens, skip_special_tokens=True)[0]

import json
from dataclasses import dataclass, fields
from typing import Any, Dict, List, Union
from uuid import uuid5, NAMESPACE_DNS

@dataclass
class EmbeddingMessage:
    payload: Union[str, List[Dict[str, Any]]]
    metadata: Dict[str, Any]

    def __post_init__(self):
        # Generate deterministic UUID based on content (alternative to uuid4)
        self.identifier = str(uuid5(NAMESPACE_DNS, f"{self.payload}{self.metadata}"))

    def serialize(self) -> Dict[str, Any]:
        """Transform the message into a dictionary representation."""
        result = {
            "id": self.identifier,
            "message": self.payload,
            "context_data": self.metadata
        }
        return result

    def to_json_string(self) -> str:
        """Convert the message to a JSON-formatted string."""
        return json.dumps(self.serialize())

    @classmethod
    def deserialize(cls, data: Dict[str, Any]) -> "EmbeddingMessage":
        """Reconstruct an embedding message from a dictionary."""
        instance = cls(
            payload=data["message"],
            metadata=data["context_data"]
        )
        if "id" in data:
            instance.identifier = data["id"]
        return instance

    @classmethod
    def parse_json(cls, json_text: str) -> "EmbeddingMessage":
        """Build an object from a JSON string with error handling."""
        try:
            parsed_data = json.loads(json_text)
            return cls.deserialize(parsed_data)
        except (json.JSONDecodeError, KeyError) as err:
            raise ValueError(f"Failed to parse JSON input: {err}")

# Google Slides CLI tool - Type III clone with refactored logic

import os
from pathlib import Path
import click
from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build

# Token file location (same as original)
TOKEN_FILE = Path.home() / ".simple-google-workspace" / "token.json"

def _load_credentials():
    """Load credentials from token file."""
    if not TOKEN_FILE.exists():
        raise click.ClickException("Not authenticated. Run: uv run scripts/auth.py login")
    return Credentials.from_authorized_user_file(TOKEN_FILE)

def _create_slides_service():
    """Create and return a Google Slides service instance."""
    creds = _load_credentials()
    return build("slides", "v1", credentials=creds)

def _create_drive_service():
    """Create and return a Google Drive service instance."""
    creds = _load_credentials()
    return build("drive", "v3", credentials=creds)

@click.group()
def cli():
    """Google Slides commands."""

@cli.command()
@click.argument("query")
def find(query: str):
    """Find presentations by name."""
    drive = _create_drive_service()

    # Modified query format for better escaping
    search_query = f"name contains '{query.replace(\"'\", \"''\")}' and mimeType = 'application/vnd.google-apps.presentation'"

    results = drive.files().list(
        q=search_query,
        fields="files(id,name)"
    ).execute()

    files = results.get("files", [])

    if not files:
        click.echo("No presentations found.")
        return

    for idx, f in enumerate(files, 1):
        click.echo(f"{idx}. [{f['id']}] {f['name']}")

@cli.command()
@click.argument("presentation_id")
def get(presentation_id: str):
    """Get presentation metadata and slide titles."""
    slides = _create_slides_service()
    presentation = slides.presentations().get(presentationId=presentation_id).execute()

    click.echo(f"Title: {presentation.get('title')}")
    click.echo(f"Slides: {len(presentation.get('slides', []))}")
    click.echo("---")

    for i, slide in enumerate(presentation.get("slides", []), 1):
        title = "(No title)"

        # Improved logic to find slide title
        page_elements = slide.get("pageElements", [])
        for element in page_elements:
            if "shape" in element:
                shape = element["shape"]
                placeholder = shape.get("placeholder", {})

                if placeholder.get("type") == "TITLE":
                    text_data = shape.get("text", {})
                    text_elements = text_data.get("textElements", [])

                    for te in text_elements:
                        if "textRun" in te:
                            content = te["textRun"].get("content", "").strip()
                            if content:
                                title = content
                                break
                    break

        click.echo(f"Slide {i}: {title}")

@cli.command()
@click.argument("presentation_id")
def text(presentation_id: str):
    """Extract all text from presentation."""
    slides = _create_slides_service()
    presentation = slides.presentations().get(presentationId=presentation_id).execute()

    click.echo(f"# {presentation.get('title')}\n")

    for i, slide in enumerate(presentation.get("slides", []), 1):
        click.echo(f"## Slide {i}")

        # Collect all text content from shapes
        text_blocks = []
        for element in slide.get("pageElements", []):
            if "shape" in element:
                shape = element["shape"]
                if "text" in shape:
                    text_data = shape["text"]
                    text_elements = text_data.get("textElements", [])

                    for te in text_elements:
                        if "textRun" in te:
                            content = te["textRun"].get("content", "").strip()
                            if content:
                                text_blocks.append(content)

        # Output collected text blocks
        for block in text_blocks:
            click.echo(block)

        click.echo()

@cli.command()
@click.argument("title")
def create(title: str):
    """Create a new presentation."""
    slides = _create_slides_service()

    presentation_body = {
        "title": title
    }

    presentation = slides.presentations().create(body=presentation_body).execute()

    pid = presentation.get("presentationId")
    link = f"https://docs.google.com/presentation/d/{pid}"

    click.echo(f"Created: {presentation.get('title')}")
    click.echo(f"ID: {pid}")
    click.echo(f"Link: {link}")

if __name__ == "__main__":
    cli()

# Retrieve the pair address for a new pool transaction

from solders.signature import Signature

def fetch_pool_pair_address(ctx, signature_str):
    pair_address = None 
    try:
        sig_obj = Signature.from_string(signature_str)
        tx_data = ctx.get_transaction(
            sig_obj, 
            encoding="jsonParsed", 
            max_supported_transaction_version=0
        )

        if tx_data.value and tx_data.value.transaction:
            instructions = tx_data.value.transaction.transaction.message.instructions

            for instruction in instructions:
                program_id_str = str(instruction.program_id)
                if "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8" == program_id_str:
                    # Extract the 5th account (index 4) as the pair address
                    pair_address = str(instruction.accounts[4])
                    break

        return pair_address
    except Exception:
        return pair_address

