# Convert Narwhals frames to Polars equivalents

import polars as pl
import narwhals as nw
from typing import Any, TypeVar, overload

FrameT = TypeVar("FrameT", bound=nw.Frame)
DataFrameT = TypeVar("DataFrameT", bound=nw.DataFrame[Any])
LazyFrameT = TypeVar("LazyFrameT", bound=nw.LazyFrame[Any])

def to_polars_eager(nw_frame: nw.Frame) -> pl.DataFrame:
    """Transform a Narwhals frame into an eager Polars DataFrame."""
    return nw_frame.lazy().collect().to_polars()

def to_polars_lazy(nw_lazy: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals lazy frame to a Polars lazy frame.
    If the underlying implementation is already Polars, return directly."""
    if nw_lazy.implementation == nw.Implementation.POLARS:
        return nw_lazy.to_native()
    else:
        return nw_lazy.collect().to_polars().lazy()

@overload
def adapt_to_polars(frame: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars(frame: LazyFrameT) -> LazyFrameT: ...

def adapt_to_polars(frame: FrameT) -> FrameT:
    # Return unchanged if already using Polars backend
    if frame.implementation == nw.Implementation.POLARS:
        return frame

    # Handle DataFrame case
    elif isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())

    # Handle LazyFrame case
    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()

    # Raise error for unsupported types
    else:
        raise TypeError(f"Unsupported frame type: {type(frame)}")

__all__ = ["to_polars_eager", "to_polars_lazy", "adapt_to_polars"]

# Compute SHA-256 hash of the input string
import hashlib

def compute_sha256(text):
    hasher = hashlib.sha256()
    hasher.update(text.encode('utf-8'))
    return hasher.hexdigest()

# Custom exception hierarchy for nima-core error handling

from typing import Optional, List

class CoreException(Exception):
    """Root exception class for all nima-core related errors."""
    pass

class ImpactVectorException(CoreException):
    """Raised when an impact vector specification is malformed."""
    pass

class UnknownImpactNameException(ImpactVectorException):
    """Raised when an unrecognized impact name is referenced."""

    def __init__(self, identifier: str, acceptable_names: Optional[List[str]] = None):
        self.identifier = identifier
        self.acceptable_names = acceptable_names
        message = f"Unrecognized impact: '{identifier}'"
        if acceptable_names:
            message += f". Acceptable impacts: {', '.join(acceptable_names)}"
        super().__init__(message)

class ImpactRangeException(ImpactVectorException):
    """Raised when an impact value falls outside the allowed interval."""

    def __init__(self, factor: str, measurement: float):
        self.factor = factor
        self.measurement = measurement
        super().__init__(
            f"Impact '{factor}' must be within [0, 1], received {measurement}"
        )

class ReferenceVectorException(ImpactVectorException):
    """Raised when a reference vector fails validation."""

    def __init__(self, issue: str):
        super().__init__(f"Reference vector invalid: {issue}")

class MemoryOperationError(CoreException):
    """Raised when state persistence operations (save/load) fail."""

    def __init__(self, location: str, action: str, cause: str):
        self.location = location
        self.action = action
        self.cause = cause
        super().__init__(
            f"Unable to {action} memory at '{location}': {cause}"
        )

class CharacterProfileMissingError(CoreException):
    """Raised when a requested personality profile cannot be located."""

    def __init__(self, profile_id: str, accessible_profiles: Optional[List[str]] = None):
        self.profile_id = profile_id
        self.accessible_profiles = accessible_profiles
        message = f"Profile unavailable: '{profile_id}'"
        if accessible_profiles:
            message += f". Accessible profiles: {', '.join(accessible_profiles)}"
        super().__init__(message)

class SentimentAnalysisFailure(CoreException):
    """Raised when sentiment detection encounters an unrecoverable issue."""
    pass

class ModelClassificationError(CoreException):
    """Raised for issues related to model archetypes."""
    pass

class UnregisteredModelClassError(ModelClassificationError):
    """Raised when an unregistered archetype is requested."""

    def __init__(self, model_name: str, registered_models: Optional[List[str]] = None):
        self.model_name = model_name
        self.registered_models = registered_models
        message = f"Archetype not registered: '{model_name}'"
        if registered_models:
            message += f". Registered: {', '.join(registered_models)}"
        super().__init__(message)

