from .p0_kernel_core import validate_with_understanding

def assess_candidate_action(context: dict, proposal: dict) -> dict:
    """Assess a proposed action or message for safety and compliance.

    context: environment and usage details, e.g.:
      {
        "channel": "moltx|clawchat|internal",
        "task": "post|reply|tool_call|memory_write",
        "user_intent": "string description",
        "risk_tolerance": "low|medium|high"
      }
    proposal: {
      "content": "text of reply or description of action",
      "metadata": {... optional ...}
    }
    """
    text = proposal.get("content", "")
    assessment = validate_with_understanding(text, context)
    return assessment

def security_guardian(fn):
    """Decorator to wrap a generation function with Guardian validation layer.

    Example usage:
    @security_guardian
    def draft_response(context, *args, **kwargs):
        return llm_call(...)
    """
    def secured(context, *args, **kwargs):
        raw_output = fn(context, *args, **kwargs)
        evaluation = assess_candidate_action(context, {"content": raw_output})
        decision = evaluation.get("action", "allow")

        if decision == "allow":
            return raw_output
        elif decision == "flag":
            explanation = evaluation.get("understanding") or "Security Guardian detected potential risk."
            return f"{raw_output}\n\n[LYGO Security Note]: {explanation}"
        elif decision == "isolate":
            return "[BLOCKED BY LYGO SECURITY GUARDIAN: content failed Nano-Kernel validation]"
        else:
            # fallback for escalated cases
            return "[LYGO SECURITY GUARDIAN REQUIRES HUMAN REVIEW BEFORE DISSEMINATION]"
    return secured

