# Type III clone: Refactored KV cache utility functions with equivalent functionality

import gzip
import pickle
from typing import Tuple
import torch

# Define type alias for key-value cache structure
KVCache = Tuple[Tuple[torch.Tensor, torch.Tensor], ...]

def move_kv_to_cpu(past_key_values: KVCache) -> KVCache:
    """Convert all K and V tensors in the cache to CPU."""
    result = []
    for key_tensor, value_tensor in past_key_values:
        cpu_k = key_tensor.detach().cpu()
        cpu_v = value_tensor.detach().cpu()
        result.append((cpu_k, cpu_v))
    return tuple(result)

def move_kv_to_target_device(past_key_values: KVCache, target: str) -> KVCache:
    """Move all K and V tensors in the cache to specified device."""
    result = []
    for key_tensor, value_tensor in past_key_values:
        moved_k = key_tensor.to(target)
        moved_v = value_tensor.to(target)
        result.append((moved_k, moved_v))
    return tuple(result)

# --------- Serialization methods ---------
def store_kv_pickle(filepath: str, kv_cache: KVCache) -> None:
    """Store KV cache using standard pickle format."""
    with open(filepath, 'wb') as file_handle:
        pickle.dump(kv_cache, file_handle)

def retrieve_kv_pickle(filepath: str) -> KVCache:
    """Load KV cache from standard pickle file."""
    with open(filepath, 'rb') as file_handle:
        return pickle.load(file_handle)

def store_kv_compressed(filepath: str, kv_cache: KVCache) -> None:
    """Store KV cache using gzip compression."""
    with gzip.open(filepath, 'wb') as compressed_file:
        pickle.dump(kv_cache, compressed_file)

def retrieve_kv_compressed(filepath: str) -> KVCache:
    """Load KV cache from gzip-compressed file."""
    with gzip.open(filepath, 'rb') as compressed_file:
        return pickle.load(compressed_file)

def store_kv_torch_format(filepath: str, kv_cache: KVCache) -> None:
    """Store KV cache using PyTorch's native save method."""
    torch.save(kv_cache, filepath)

def retrieve_kv_torch_format(filepath: str) -> KVCache:
    """Load KV cache using PyTorch's native load method (CPU mapping)."""
    return torch.load(filepath, map_location='cpu')

def store_kv(filepath: str, kv_cache: KVCache, format_type: str = "pickle") -> None:
    """Generic KV cache storage function supporting multiple formats."""
    format_type = format_type.lower()
    if format_type == "pickle":
        store_kv_pickle(filepath, kv_cache)
    elif format_type == "gzip":
        store_kv_compressed(filepath, kv_cache)
    elif format_type == "torch":
        store_kv_torch_format(filepath, kv_cache)
    else:
        raise ValueError(f"Unsupported format: {format_type}")

def retrieve_kv(filepath: str, format_type: str = "pickle") -> KVCache:
    """Generic KV cache retrieval function supporting multiple formats."""
    format_type = format_type.lower()
    if format_type == "pickle":
        return retrieve_kv_pickle(filepath)
    elif format_type == "gzip":
        return retrieve_kv_compressed(filepath)
    elif format_type == "torch":
        return retrieve_kv_torch_format(filepath)
    else:
        raise ValueError(f"Unsupported format: {format_type}")

# --------- Sequence pruning ---------
def trim_kv_sequence(kv_cache: KVCache, recent_tokens: int) -> KVCache:
    """Retain only the most recent `recent_tokens` positions along sequence dimension."""
    trimmed = []
    for key_tensor, value_tensor in kv_cache:
        # Slice last 'recent_tokens' positions from sequence dimension (axis=2)
        trimmed_k = key_tensor[:, :, -recent_tokens:, :]
        trimmed_v = value_tensor[:, :, -recent_tokens:, :]
        trimmed.append((trimmed_k, trimmed_v))
    return tuple(trimmed)

