# Reimplementation of TextMessage class with equivalent functionality but different internal logic

import re
from dataclasses import dataclass, field, fields
from datetime import datetime
from typing import Self
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.output.epstein_highlighter import highlighter
from epstein_files.output.highlight_config import get_style_for_name
from epstein_files.output.rich import TEXT_LINK
from epstein_files.people.names import (ANTHONY_SCARAMUCCI, JEFFREY_EPSTEIN, STEVE_BANNON,
     UNKNOWN, Name, extract_last_name)
from epstein_files.util.constant.strings import TIMESTAMP_DIM
from epstein_files.util.helpers.data_helpers import AMERICAN_DATE_FORMAT
from epstein_files.util.logging import logger

EPSTEIN_TEXTERS = ['e:', 'e:redacted@example.invalid']
PHONE_NUMBER_REGEX = re.compile(r'^[\d+]+.*')
UNCERTAIN_SUFFIX = ' (?)'
DISPLAY_LAST_NAME_ONLY = [
    ANTHONY_SCARAMUCCI,
    JEFFREY_EPSTEIN,
    STEVE_BANNON,
]

@dataclass(kw_only=True)
class TextMessage:
    """Class representing a single iMessage text message."""
    author: [redacted]
    author_str: str = ''
    is_id_confirmed: bool = False
    text: str
    timestamp_str: str

    def __post_init__(self):
        # Normalize author if in known Epstein texters list
        self.author = JEFFREY_EPSTEIN if self.author in EPSTEIN_TEXTERS else self.author

        # Determine display name for author
        if not self.author:
            self.author_str = UNKNOWN
        elif self.author in DISPLAY_LAST_NAME_ONLY and not self.author_str:
            self.author_str = extract_last_name(self.author)
        else:
            self.author_str = self.author_str or str(self.author)

        # Add uncertainty marker if ID not confirmed and not Jeffrey Epstein
        if not self.is_id_confirmed and self.author is not None and self.author != JEFFREY_EPSTEIN:
            self.author_str += UNCERTAIN_SUFFIX

        # Process text content based on whether it's a link
        if self._is_url():
            self.text = self.text.replace('\n', '').replace(' ', '_')
        else:
            self.text = self.text.replace('\n', ' ')

    @property
    def timestamp_sort_key(self) -> datetime:
        try:
            return self._extract_timestamp()
        except Exception as e:
            return FALLBACK_TIMESTAMP

    def _is_url(self) -> bool:
        return self.text.startswith('http')

    def _extract_timestamp(self) -> datetime:
        return datetime.strptime(self.timestamp_str, AMERICAN_DATE_FORMAT)

    def timestamp_txt(self) -> Text:
        from epstein_files.util.env import site_config
        try:
            parsed_time = self._extract_timestamp()
            timestamp_str = site_config.format_text_msg_time(parsed_time)
        except Exception as e:
            logger.info(f"Failed to parse timestamp for {self}")
            timestamp_str = self.timestamp_str
        return Text(f"[{timestamp_str}]", style=TIMESTAMP_DIM)

    def _render_content(self) -> Text:
        if self._is_url():
            return Text.from_markup(f"[link={self.text}]{self.text}[/link]", style=TEXT_LINK)
        else:
            return highlighter(self.text)

    def __eq__(self, other: Self):
        return all([
            self.author == other.author,
            self.text == other.text,
            self.timestamp_str == other.timestamp_str,
            self.author_str == other.author_str
        ])

    def __rich__(self) -> Text:
        timestamp_part = self.timestamp_txt().append(' ')
        author_display = self.author_str if not self.author_str.startswith('+') else self.author_str
        author_style = get_style_for_name(author_display)
        author_txt = Text(self.author_str, style=author_style)
        return Text('').append(timestamp_part).append(author_txt).append(': ', style='dim').append(self._render_content())

    def __repr__(self) -> str:
        props = []
        add_prop = lambda k, v: props.append(f"{k}={v}")
        for _field in sorted(fields(self), key=lambda f: f.name):
            key = _field.name
            value = getattr(self, key)
            # Skip redundant author_str when author is set and matches prefix
            if key == 'author_str' and self.author and self.author_str.startswith(str(value)):
                continue
            elif isinstance(value, str):
                add_prop(key, f'"{value}"')
            else:
                add_prop(key, value)
        return f"{type(self).__name__}(" + ', '.join(props) + ')'

# Secure credential management module for API keys

import os

# Check if keyring library is available
try:
    import keyring
    KEYRING_ENABLED = True
except ImportError:
    KEYRING_ENABLED = False

# Service identifier and provider mapping
SERVICE_ID = "skylos"
API_PROVIDERS = {
    "openai": "OPENAI_API_KEY",
    "anthropic": "ANTHROPIC_API_KEY",
    "google": "GEMINI_API_KEY",
    "mistral": "MISTRAL_API_KEY",
    "groq": "GROQ_API_KEY",
    "xai": "XAI_API_KEY",
    "together": "TOGETHER_API_KEY",
    "deepseek": "DEEPSEEK_API_KEY",
}

def store_credential(provider_name, api_key):
    """Store an API key using the system keyring if available."""
    if not KEYRING_ENABLED:
        print("[warning] 'keyring' module unavailable. Credentials cannot be stored securely.")
        return False

    try:
        keyring.set_password(SERVICE_ID, provider_name, api_key)
        return True
    except Exception as error:
        print(f"[warning] Keyring storage failed: {error}")
        return False

def retrieve_credential(provider_name):
    """Retrieve an API key from environment or secure storage."""
    # First check environment variable
    env_key = API_PROVIDERS.get(provider_name)
    if env_key:
        env_value = os.getenv(env_key)
        if env_value:
            return env_value

    # Then try keyring if available
    if KEYRING_ENABLED:
        try:
            return keyring.get_password(SERVICE_ID, provider_name)
        except Exception:
            pass

    return None

def remove_credential(provider_name):
    """Remove an API key from secure storage."""
    try:
        import keyring
    except Exception:
        return False

    service_identifier = "skylos"
    user_label = str(provider_name)

    try:
        keyring.delete_password(service_identifier, user_label)
        return True
    except Exception:
        return False

def get_available_providers():
    """Return list of supported providers."""
    return list(API_PROVIDERS.keys())

from graph_net.torch.sym_dim_reifiers.reify_util import get_dynamic_dim_constraints
from graph_net.torch.sym_dim_reifiers.reifier_base import ReifierBase
import os
import sympy

class ConcreteReifier(ReifierBase):
    def __init__(self, model_path: str, **kwargs):
        super().__init__(model_path)
        self._dynamic_constraints = get_dynamic_dim_constraints(model_path)

    def get_reifier_name(self) -> str:
        return os.path.splitext(os.path.basename(__file__))[0]

    def is_applicable(self) -> bool:
        if self._dynamic_constraints is None:
            return False

        serialized_shapes = self._dynamic_constraints.serialize_symbolic_input_shapes_to_str()
        if not serialized_shapes or serialized_shapes == "[]":
            return False

        shape_map = self._get_symbolic_shape_mapping()
        if serialized_shapes not in shape_map:
            print(
                f"[NLP SymDim Reify] No reifier matched symbolic shapes:{serialized_shapes} \nPlease add a reify rule to _get_symbolic_shape_mapping()"
            )
            return False
        return True

    def apply_reification(self):
        assert self.is_applicable()
        serialized_shapes = self._dynamic_constraints.serialize_symbolic_input_shapes_to_str()
        reifier_func = self._get_symbolic_shape_mapping()[serialized_shapes]
        return reifier_func(self)

    @classmethod
    def _get_symbolic_shape_mapping(cls):
        if not hasattr(cls, "_symbolic_shape_table"):
            cls._symbolic_shape_table = {
                "[(S0,1),(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1_variant_a,
                "[(S0,S1),(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1_variant_a,
                "[(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1_variant_a,
                "[(S0,S1,768)]": cls._reify_batch_s0_seq_s1_variant_a,
                "[(S0,S1)]": cls._reify_nlp_or_gnn_batch_s0_seq_s1_variant_b,
            }
        return cls._symbolic_shape_table

    def _reify_batch_s0_seq_s1_variant_a(self):
        var_S0, var_S1 = sympy.Symbol("S0"), sympy.Symbol("S1")
        return {
            (var_S0, var_S1): [
                [1, 64],
                [1, 512],
                [16, 128],
                [32, 64],
                [8, 256],
                [4, 512],
                [2, 1024],
                [64, 128],
                [128, 64],
            ]
        }

    def _reify_nlp_or_gnn_batch_s0_seq_s1_variant_b(self):
        var_S0, var_S1 = sympy.Symbol("S0"), sympy.Symbol("S1")
        return {
            (var_S0, var_S1): [
                [1, 128],
                [1, 1024],
                [32, 64],
                [16, 128],
                [8, 256],
                [4, 512],
                [2, 1024],
                [64, 128],
                [128, 64],
            ],
        }

import json
from volcengine.ApiInfo import ApiInfo
from typing import Any
from volcengine import Credentials
from volcengine import ServiceInfo
from volcengine.base import Service

class BaseApi(Service.Service):
    def __init__(self, region, endpoint, api_info, service, ak, sk):
        """Initialize the API client with configuration parameters.

        :param region:   AWS/Cloud region identifier
        :param api_info: ApiInfo instance containing endpoint details
        :param endpoint: gateway URL for API requests
        :param service:  registered service name on the gateway
        :param ak:       access key ID
        :param sk:       secret access key
        """
        self.connect_timeout = 10
        self.socket_read_timeout = 10
        self.protocol = 'https'
        self.headers = {}
        self.headers["Content-Type"] = "application/json"
        self.gateway_endpoint = endpoint
        self.auth_credentials = Credentials.Credentials(ak, sk, service, region)
        self.service_config = ServiceInfo.ServiceInfo(
            self.gateway_endpoint,
            self.headers,
            self.auth_credentials,
            self.connect_timeout,
            self.socket_read_timeout,
            self.protocol,
        )
        self.api_definition = api_info
        Service.Service.__init__(self, self.service_config, self.api_definition)

    @staticmethod
    def convert_to_params(obj: Any) -> dict[str, Any]:
        """Transform request model into parameter dictionary, filtering out None values.

        This utility handles different serialization methods (to_dict/model_dump),
        applies attribute mapping for naming conventions (snake_case to camelCase),
        and removes entries with None values before sending to the API.
        """
        payload = {}

        if hasattr(obj, "serialize"):
            payload = obj.serialize()
        elif hasattr(obj, "model_dump"):
            payload = obj.model_dump()
        elif isinstance(obj, dict):
            payload = obj.copy()
        else:
            payload = vars(obj).copy()

        field_mapping = getattr(obj, "field_names", None)
        if isinstance(field_mapping, dict):
            payload = {field_mapping.get(key, key): value 
                      for key, value in payload.items()}

        return {key: value for key, value in payload.items() 
                if value is not None}

    def execute_get(self, action, params, doseq=0):
        raw_response = super(BaseApi, self).get(action, params, doseq)
        try:
            response_data = json.loads(raw_response)
        except Exception as error:
            raise Exception("Response body is not valid JSON, %s, %s" % (error, raw_response))

        if "ResponseMetadata" not in response_data:
            raise Exception(
                "Missing ResponseMetadata in response, action %s, response %s" % (action, raw_response)
            )
        elif "Error" in response_data["ResponseMetadata"]:
            raise Exception("%s operation failed, %s" % (action, raw_response))

        return response_data

import torch
from collections import OrderedDict
from sam2.sam2_video_predictor import SAM2VideoPredictor as BaseSAM2Predictor
from sam_utils import load_video_frames, load_video_frames_v2


class SAM2VideoPredictor(BaseSAM2Predictor):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @torch.inference_mode()
    def establish_inference_state(self, video_path, 
                                  cpu_offload_video=False, 
                                  cpu_offload_state=False, 
                                  async_load_frames=False, 
                                  frame_list=None):
        """Set up an inference session for video tracking."""
        # Load frames from path
        img_tensor, vid_h, vid_w = load_video_frames(
            video_path=video_path,
            image_size=self.image_size,
            offload_video_to_cpu=cpu_offload_video,
            async_loading_frames=async_load_frames,
            frame_names=frame_list
        )

        # Initialize state container
        infer_state = {}

        # Store raw input data
        infer_state["images"] = img_tensor
        infer_state["num_frames"] = len(img_tensor)
        infer_state["offload_video_to_cpu"] = cpu_offload_video
        infer_state["offload_state_to_cpu"] = cpu_offload_state
        infer_state["video_height"] = vid_h
        infer_state["video_width"] = vid_w

        # Device setup
        infer_state["device"] = torch.device("cuda")
        infer_state["storage_device"] = (
            torch.device("cpu") if cpu_offload_state else torch.device("cuda")
        )

        # Per-object interaction buffers
        infer_state["point_inputs_per_obj"] = {}
        infer_state["mask_inputs_per_obj"] = {}

        # Caching mechanism for recent frame features
        infer_state["cached_features"] = {}

        # Immutable constants (shared across frames)
        infer_state["constants"] = {}

        # Object ID ↔ index mapping
        infer_state["obj_id_to_idx"] = OrderedDict()
        infer_state["obj_idx_to_id"] = OrderedDict()
        infer_state["obj_ids"] = []

        # Output storage: conditional & non-conditional frame outputs
        infer_state["output_dict"] = {
            "cond_frame_outputs": {},
            "non_cond_frame_outputs": {}
        }

        # Object-specific views into output_dict
        infer_state["output_dict_per_obj"] = {}

        # Temporary buffer for new user inputs before consolidation
        infer_state["temp_output_dict_per_obj"] = {}

        # Track which frames have been interacted with
        infer_state["consolidated_frame_inds"] = {
            "cond_frame_outputs": set(),
            "non_cond_frame_outputs": set()
        }

        # Tracking metadata
        infer_state["tracking_has_started"] = False
        infer_state["frames_already_tracked"] = {}

        # Precompute visual features on first frame
        self._get_image_feature(infer_state, frame_idx=0, batch_size=1)

        return infer_state

    @torch.inference_mode()
    def establish_inference_state_v2(self, frames_seq, 
                                     cpu_offload_video=False, 
                                     cpu_offload_state=False, 
                                     async_load_frames=False, 
