import pytest
import re
from typing import Any, Dict, List, Union

def clean_response(payload: Any) -> Any:
    """
    Recursively process response payloads to eliminate non-deterministic values.
    Substitutes time-related and volatile fields with stable placeholders.
    """
    if isinstance(payload, dict):
        cleaned = {}
        for key, value in payload.items():
            # Normalize timestamp-like keys
            if key in ["created_at", "updated_at", "timestamp", "last_login", "date", "last_activity"]:
                cleaned[key] = "TIMESTAMP_REDACTED"
            # Normalize token/session identifiers
            elif key in ["session_id", "access_token", "refresh_token"] and isinstance(value, str):
                cleaned[key] = f"TOKEN_{key.upper()}"
            # Normalize variable latency measurements
            elif key == "latency_ms":
                cleaned[key] = 0.0
            # Normalize floating point precision
            elif isinstance(value, float):
                cleaned[key] = round(value, 4)
            else:
                cleaned[key] = clean_response(value)
        return cleaned
    elif isinstance(payload, list):
        return [clean_response(element) for element in payload]
    return payload

