from typing import Any
import operator
from langchain_core.documents import Document
from pydantic import BaseModel, Field, field_validator

class InputState(BaseModel):
    documents_text: list[str] = Field(
        default_factory=list, description="Text content extracted from documents"
    )

    @field_validator("documents_text", mode="before")
    @classmethod
    def standardize_input(cls, value) -> Any:
        """Convert various input formats into a list of strings.

        Supports:
        - List[str]
        - List[Document]
        - Mixed list of strings and Documents
        """
        if not isinstance(value, list):
            raise TypeError("Input must be a list for 'documents_text'")

        standardized = []
        for element in value:
            if isinstance(element, Document):
                # Extract page content from Document object
                standardized.append(element.page_content)
            elif isinstance(element, str):
                standardized.append(element)
            else:
                raise TypeError(f"Invalid item type in input: {type(element)}")

        return standardized

class OutputState(BaseModel):
    """Result structure for the summarization process."""
    aggregated_summary: str = Field(
        default="", description="Combined summary across all processed documents"
    )

class SummaryState(InputState, OutputState):
    """Aggregated state for document summarization workflow.

    Uses operator.add to merge multiple summaries during state transitions.
    """
    partial_summaries: Annotated[list, operator.add] = Field(
        default_factory=list, description="Individual summaries generated per document"
    )
    merged_summaries: list[Document] = Field(
        default_factory=list, description="Consolidated summary documents after processing"
    )

