class BaseFeishuException(Exception):
    """Root exception class covering all Feishu service-related problems."""

    def __init__(self, description: str, code: str = None, extra_info: dict = None):
        super().__init__(description)
        self.description = description
        self.code = code
        self.extra_info = extra_info or {}

class AuthFailure(BaseFeishuException):
    """Raised when authentication with Feishu services fails."""
    pass

class ServiceIssue(BaseFeishuException):
    """General error indicating an issue with the Feishu API."""
    pass

class MissingResource(BaseFeishuException):
    """Raised when a requested resource cannot be located (HTTP 404)."""
    pass

class AccessDenied(BaseFeishuException):
    """Raised when access to a resource is forbidden (HTTP 403)."""
    pass

class TooManyRequests(BaseFeishuException):
    """Raised when rate limiting prevents further requests (HTTP 429)."""
    pass

class ConnectionProblem(BaseFeishuException):
    """Raised for network failures such as timeouts or unreachable hosts."""
    pass

class InvalidPayload(BaseFeishuException):
    """Raised when data processing or validation encounters problems."""
    pass

