# Type III Clone: Refactored viewer blueprint with equivalent functionality
from __future__ import annotations
import os
from typing import Any, Dict
from flask import Blueprint, Response, redirect, request

def generate_viewer_module() -> Blueprint:
    """Generate a compatibility layer for /graph-viewer routes."""

    # Initialize blueprint with custom prefix
    module = Blueprint(
        "graph_viewer_compat",
        __name__,
        url_prefix="/graph-viewer",
    )

    def _get_viewer_endpoint() -> str:
        """Retrieve and normalize the Graph Viewer base URL from environment."""
        raw_url = os.environ.get("GRAPH_VIEWER_ENDPOINT", "")
        return raw_url.strip().rstrip("/")

    def _service_unavailable() -> Response:
        """Return 503 response when viewer is not configured."""
        return Response(
            "Graph Viewer service is not available. Please configure GRAPH_VIEWER_ENDPOINT.",
            status=503,
            mimetype="text/plain"
        )

    def _is_static_resource(path: str) -> bool:
        """Determine if the path refers to a static asset."""
        if not path:
            return False

        # Direct asset folder check
        if path.startswith("static/"):
            return True

        # Extension-based check (case-insensitive)
        _, ext = os.path.splitext(path)
        return ext.lower() in {
            ".js", ".css", ".svg", ".png", ".jpg", ".jpeg", 
            ".webp", ".ico", ".json", ".txt", ".map", 
            ".woff", ".woff2", ".ttf"
        }

    def _construct_redirect_target(endpoint: str, route: str) -> str:
        """Build full redirect target URL including query parameters."""
        clean_route = route.lstrip("/")
        destination = f"{endpoint}/{clean_route}" if clean_route else endpoint

        # Preserve original query string
        query_bytes = request.query_string
        query_str = query_bytes.decode("utf-8", errors="replace") if query_bytes else ""

        return f"{destination}?{query_str}" if query_str else destination

    def _generate_redirect_page(endpoint: str, route: str) -> str:
        """Create minimal HTML redirect page with embedded JS logic."""
        base_clean = f"{endpoint}/" if not endpoint.endswith("/") else endpoint
        path_clean = route.lstrip("/")

        # Construct HTML with inline script for client-side redirection
        html_template = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Redirecting to Graph Viewer...</title>
</head>
<body>
  <p>Redirecting to Graph Viewer...</p>
  <script>
    (function () {{
      const base = "{base_clean}";
      const relPath = "{path_clean}";
      const target = new URL(relPath, base);

      // Transfer all query parameters from current URL
      const params = new URLSearchParams(window.location.search);
      params.forEach((value, key) => target.searchParams.append(key, value));

      // Add server parameter if missing
      if (!target.searchParams.has("server")) {{
        target.searchParams.set("server", window.location.origin);
      }}

      // Preserve fragment identifier and redirect
      window.location.replace(target.toString() + window.location.hash);
    }})();
  </script>
</body>
</html>"""
        return html_template

    # Define route handlers
    @module.route("/", defaults={"route": ""})
    @module.route("/<path:route>")
    def handle_viewer_request(route: str) -> Any:
        """Route handler for viewer compatibility endpoints."""
        viewer_endpoint = _get_viewer_endpoint()

        # Check if viewer is properly configured
        if not viewer_endpoint:
            return _service_unavailable()

        # Static assets get direct redirect
        if _is_static_resource(route):
            return redirect(_construct_redirect_target(viewer_endpoint, route), code=302)

        # Otherwise serve redirect HTML page
        redirect_html = _generate_redirect_page(viewer_endpoint, route)
        return Response(redirect_html, status=200, mimetype="text/html")

    return module

def check_viewer_availability() -> bool:
    """Determine whether graph viewer functionality should be active."""
    env_value = os.environ.get("ENABLE_GRAPH_VIEWER", "true").lower()
    return env_value in ("true", "1", "yes", "on")

import base64
import io
import logging
from transformers import AutoProcessor, AutoTokenizer, PreTrainedTokenizerBase, ProcessorMixin

logger = logging.getLogger(__name__)

# Default image patch size for vision-language models
# Note: Qwen3-VL uses 16, Qwen2.5-VL uses 14
# Reference: https://github.com/QwenLM/Qwen3-VL/blob/main/qwen-vl-utils/README.md
DEFAULT_PATCH_SIZE = 14

def get_tokenizer(model_identifier: str, **kwargs):
    return AutoTokenizer.from_pretrained(model_identifier, **kwargs)

def get_processor(model_identifier: str, **kwargs):
    try:
        proc = AutoProcessor.from_pretrained(model_identifier, **kwargs)
    except (OSError, ValueError) as err:
        logger.warning(f"Could not load processor from {model_identifier}: {err}")
        proc = None

    # Ensure we only keep valid multimodal processors, discard pure tokenizers
    if isinstance(proc, PreTrainedTokenizerBase) or not isinstance(proc, ProcessorMixin):
        proc = None

    return proc

def extract_multimodal_data(prompt_text, processor_obj):
    # Temporary workaround; will be replaced with dedicated image utilities later
    from qwen_vl_utils import process_vision_info

    # Determine patch size from processor's image processor, fallback to default
    if hasattr(processor_obj.image_processor, "patch_size"):
        patch_dim = processor_obj.image_processor.patch_size
    else:
        logger.info(f"Patch size not found in processor; falling back to default: {DEFAULT_PATCH_SIZE}")
        patch_dim = DEFAULT_PATCH_SIZE

    images_list, videos_list = process_vision_info(prompt_text, image_patch_size=patch_dim)

    return {
        "images": images_list,
        "videos": videos_list
    }

def convert_image_to_base64(image_data) -> str:
    """Convert PIL image to base64-encoded PNG string."""
    output_buffer = io.BytesIO()

    # Ensure image is in RGB mode before saving
    if image_data.mode != "RGB":
        image_data = image_data.convert("RGB")

    image_data.save(output_buffer, format="PNG")
    encoded_bytes = base64.b64encode(output_buffer.getvalue())
    return encoded_bytes.decode("utf-8")

