from typing import Callable, Optional, Dict, Any
import torch

# Import helper functions from rlinf.algorithms.utils
from rlinf.algorithms.utils import (
    calculate_scores,
    postprocess_embodied_advantages_outputs,
    postprocess_loss_metric,
    postprocess_reasoning_advantages_outputs,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

# Registry dictionaries for advantage and loss functions
ADVANTAGE_REGISTRY: Dict[str, Callable] = {}
POLICY_LOSS_REGISTRY: Dict[str, Callable] = {}


def register_advantage_function(name: str):
    """Decorator to register an advantage computation function."""
    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        ADVANTAGE_REGISTRY[name.lower()] = wrapped
        return wrapped
    return decorator


def fetch_advantage_function(name: str) -> Callable:
    """Retrieve a registered advantage function by name."""
    key = name.lower()
    if key not in ADVANTAGE_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' is not registered. Available options: {list(ADVANTAGE_REGISTRY.keys())}"
        )
    return ADVANTAGE_REGISTRY[key]


def register_policy_loss_function(name: str):
    """Decorator to register a policy loss function."""
    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        POLICY_LOSS_REGISTRY[name.lower()] = wrapped
        return wrapped
    return decorator


def retrieve_policy_loss_function(name: str) -> Callable:
    """Get a registered policy loss function by name."""
    key = name.lower()
    if key not in POLICY_LOSS_REGISTRY:
        raise ValueError(f"Loss '{name}' has not been registered.")
    return POLICY_LOSS_REGISTRY[key]


def compute_actor_loss(**config) -> tuple[torch.Tensor, dict]:
    """
    Centralized actor loss computation entry point.
    Handles preprocessing/postprocessing based on task type.
    """
    loss_name = config["loss_type"]
    loss_func = retrieve_policy_loss_function(loss_name)
    task_category = config["task_type"]

    if task_category == "embodied":
        config = preprocess_loss_inputs(**config)

    total_loss, metric_dict = loss_func(**config)

    if task_category == "embodied":
        metric_dict = postprocess_loss_metric(metric_dict)

    return total_loss, metric_dict


def compute_advantage_and_return_values(**config) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified interface for computing advantages and returns.
    Routes to appropriate algorithm based on 'adv_type', handles preprocessing/postprocessing.
    """
    adv_method = config["adv_type"]
    target_fn = fetch_advantage_function(adv_method)
    environment_type = config["task_type"]

    if environment_type == "embodied":
        # Preprocess inputs specific to embodied tasks
        config = preprocess_embodied_advantages_inputs(**config)

        # For non-GAE methods, compute scores first
        if adv_method != "gae":
            config = calculate_scores(**config)

        # Compute advantages and returns
        adv_vals, ret_vals = target_fn(**config)

        # Postprocess outputs for embodied tasks
        result = postprocess_embodied_advantages_outputs(
            advantages=adv_vals, returns=ret_vals, **config
        )

    else:
        # Reasoning tasks (e.g., LLM-based)
        config = preprocess_reasoning_advantages_inputs(**config)

        # Compute advantages and returns
        adv_vals, ret_vals = target_fn(**config)

        # Postprocess outputs for reasoning tasks
        result = postprocess_reasoning_advantages_outputs(adv_vals, ret_vals)

    return result

# Custom reward computation for environment service evaluation

from ajet.task_judge.base_judge import BaseJudge
from ajet.workflow import WorkflowOutput, WorkflowTask

class EnvServiceJudge(BaseJudge):
    def __init__(self, configuration):
        self.configuration = configuration

    def compute_reward(self, task: WorkflowTask, output: WorkflowOutput) -> tuple:
        # Initialize base reward value
        base_score = 0.0
        environment = task.gym_env

        # Evaluate the episode with dense reward mode
        base_score = environment.evaluate(task.episode_uuid, params={"sparse": False})

        # Determine success status based on threshold
        if base_score >= 1.0:
            success_flag = True
        else:
            success_flag = False

        # Apply reward scaling with success bonus
        if success_flag:
            final_score = 1.0 + base_score * 0.5
        else:
            final_score = 0.0 + base_score * 0.5

        return final_score, success_flag

