# Implementation of MemcacheBackend for distributed KV storage using Ascend devices

from enum import Enum
import torch
from vllm.config import ParallelConfig
from vllm.logger import logger
from vllm_ascend.distributed.kv_transfer.kv_pool.ascend_store.backend.backend import Backend
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type

class TransferDirection(Enum):
    LOCAL_TO_GLOBAL = 0
    GLOBAL_TO_LOCAL = 1
    GLOBAL_TO_HOST = 2
    HOST_TO_GLOBAL = 3

class MemcacheStorage(Backend):
    def __init__(self, parallel_config: ParallelConfig):
        try:
            from memcache_hybrid import DistributedObjectStore  # type: ignore
        except ImportError as e:
            raise ImportError(
                "Please install memcache by following the instructions at "
                "https://gitee.com/ascend/memfabric_hybrid "  # noqa: E501
                "to run vLLM with MemcacheConnector."
            ) from e

        try:
            device_version = get_ascend_device_type()
            if device_version == AscendDeviceType.A2:
                # Initialize distributed environment for A2 platform
                world_group = torch.distributed.group.WORLD
                local_rank = torch.npu.current_device()
                tmp_tensor = torch.zeros(1, device="npu")
                gathered_tensors = [
                    torch.empty_like(tmp_tensor) 
                    for _ in range(torch.distributed.get_world_size())
                ]
                torch.distributed.all_gather(
                    gathered_tensors, 
                    tmp_tensor, 
                    group=world_group.device_group
                )
                self.local_rank = parallel_config.rank
                self.storage_backend = DistributedObjectStore()
                initialization_result = self.storage_backend.init(self.local_rank)
                assert initialization_result == 0, "Failed to initialize storage backend"
            else:
                # Fallback initialization for other platforms
                self.local_rank = parallel_config.rank
                self.storage_backend = DistributedObjectStore()
                initialization_result = self.storage_backend.init(self.local_rank)
                assert initialization_result == 0, "Failed to initialize storage backend"
        except ValueError as ve:
            logger.error("Configuration error during initialization: %s", ve)
            raise
        except Exception as ex:
            logger.error("Unexpected error during configuration setup: %s", ex)
            raise

    def configure_device(self):
        current_device = torch.device(f"npu:{self.local_rank}")
        torch.npu.set_device(current_device)

    def attach_buffers(self, memory_addresses: list[int], buffer_sizes: list[int]):
        device_type = get_ascend_device_type()
        if device_type == AscendDeviceType.A2:
            for address, size in zip(memory_addresses, buffer_sizes):
                self.storage_backend.register_buffer(address, size)

    def check_keys(self, identifiers: list[str]) -> list[int]:
        return self.storage_backend.batch_is_exist(identifiers)

    def fetch_data(self, keys: list[str], destinations: list[list[int]], lengths: list[list[int]]):
        try:
            results = self.storage_backend.batch_get_into_layers(
                keys, 
                destinations, 
                lengths, 
                TransferDirection.GLOBAL_TO_LOCAL.value
            )
            for status_code in results:
                if status_code != 0:
                    logger.error(f"Data retrieval failed for keys {keys}, status: {results}")
        except Exception as err:
            logger.error(f"Exception during data retrieval for keys {keys}: {err}")

    def store_data(self, keys: list[str], sources: list[list[int]], lengths: list[list[int]]):
        try:
            results = self.storage_backend.batch_put_from_layers(
                keys, 
                sources, 
                lengths, 
                TransferDirection.LOCAL_TO_GLOBAL.value
            )
            for status_code in results:
                if status_code != 0:
                    logger.error(f"Data storage failed for keys {keys}, status: {results}")
        except Exception as err:
            logger.error(f"Exception during data storage for keys {keys}: {err}")

# Alternative implementation of the log viewer server with modified logic and structure

import errno
import json
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse
from klaude_code.const import DEFAULT_DEBUG_LOG_DIR

VIEWER_HTML_FILE = Path(__file__).parent / "log_viewer.html"
DEFAULT_PORT = 8765

class LogRequestHandler(BaseHTTPRequestHandler):
    """Custom handler to serve log viewing interface and data."""

    def do_GET(self):
        request_path = urlparse(self.path).path

        if request_path in ('/', ''):
            self._send_html_page()
        elif request_path == '/api/log':
            self._handle_log_request()
        elif request_path == '/api/logs':
            self._send_available_logs()
        else:
            self._send_error_response(404, 'Resource not found')

    def _send_html_page(self):
        html_content = VIEWER_HTML_FILE.read_bytes()
        self._send_response(200, 'text/html; charset=utf-8', html_content)

    def _handle_log_request(self):
        query_params = parse_qs(urlparse(self.path).query)
        requested_paths = query_params.get('path', [])

        if not requested_paths:
            self._send_error_response(400, 'Missing required path parameter')
            return

        target_path = Path(requested_paths[0]).resolve()
        base_dir = DEFAULT_DEBUG_LOG_DIR.resolve()

        if not self._is_safe_path(target_path, base_dir):
            self._send_error_response(403, 'Access denied: path outside allowed directory')
            return

        if not target_path.is_file():
            self._send_error_response(404, 'Log file does not exist')
            return

        log_content = target_path.read_bytes()
        self._send_response(200, 'text/plain; charset=utf-8', log_content)

    def _send_available_logs(self):
        available_logs = self._collect_log_files(DEFAULT_DEBUG_LOG_DIR.resolve())
        response_body = json.dumps(available_logs).encode()
        self._send_response(200, 'application/json; charset=utf-8', response_body)

    def _send_error_response(self, status_code: int, message: str):
        body = message.encode()
        self._send_response(status_code, 'text/plain', body)

    def _send_response(self, code: int, content_type: str, data: bytes):
        self.send_response(code)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, format_str: str, *args) -> None:
        # Suppress default logging
        pass

    def _is_safe_path(self, candidate: Path, root: Path) -> bool:
        try:
            candidate.relative_to(root)
            return True
        except ValueError:
            return False

    def _collect_log_files(self, directory: Path) -> list[dict]:
        if not directory.exists():
            return []

        log_entries = []
        processed_paths = set()

        for log_file in directory.rglob('*.log'):
            if not log_file.is_file():
                continue

            try:
                file_stat = log_file.stat()
                absolute_path = log_file.resolve()
                relative_path = str(absolute_path.relative_to(directory))

                if absolute_path in processed_paths:
                    continue

                processed_paths.add(absolute_path)

                log_entries.append({
                    'timestamp': file_stat.st_mtime,
                    'info': {
                        'full_path': str(absolute_path),
                        'relative_path': relative_path,
                        'size_in_bytes': file_stat.st_size,
                        'last_modified': file_stat.st_mtime
                    }
                })
            except (OSError, ValueError):
                continue

        # Sort by modification time descending
        log_entries.sort(key=lambda x: x['timestamp'], reverse=True)
        return [entry['info'] for entry in log_entries]

def _find_free_port(starting_port: int) -> tuple[HTTPServer, int]:
    for port_candidate in range(starting_port, 65536):
        try:
            server_instance = HTTPServer(('127.0.0.1', port_candidate), LogRequestHandler)
            return server_instance, port_candidate
        except OSError as error:
            if error.errno == errno.EADDRINUSE:
                continue
            raise

    raise RuntimeError(f'Unable to find an available port between {starting_port} and 65535')

def launch_log_viewer(log_file_path: Path) -> str:
    """Initialize the log viewer service on a background thread and open browser.
    Returns the complete URL for accessing the viewer.
    """
    server, selected_port = _find_free_port(DEFAULT_PORT)

    server_thread = threading.Thread(
        target=server.serve_forever,
        daemon=True
    )
    server_thread.start()

    full_url = f'http://127.0.0.1:{selected_port}/?log={log_file_path}'
    webbrowser.open(full_url)

    return full_url

class LongInt(int):
    """BSON int64 type representation.
    Ensures that integer values are always encoded as 64-bit integers in BSON,
    unlike regular Python ints which may be encoded as 32-bit integers by default.
    :Parameters:
      - `value`: the numeric value to represent
    """
