# Custom logging handler for QTextEdit with color-coded messages

from PySide6.QtCore import Signal, QObject
import logging


class LogOutputHandler(logging.Handler, QObject):
    message_ready = Signal(str, str)

    def __init__(self, text_edit_widget):
        super().__init__()
        QObject.__init__(self)
        self.text_area = text_edit_widget
        self.message_ready.connect(self.display_message)

    def emit(self, log_record):
        formatted_message = self.format(log_record)
        self.message_ready.emit(log_record.levelname, formatted_message)

    def display_message(self, severity, content):
        background_color = "#E0E0E0"

        if severity == "INFO":
            background_color = "#58D68D"
        elif severity == "WARNING":
            background_color = "#F4D03F"
        elif severity == "ERROR":
            background_color = "#EC7063"
        elif severity == "DEBUG":
            background_color = "#888888"

        scrollbar = self.text_area.verticalScrollBar()
        near_bottom = scrollbar.value() >= (scrollbar.maximum() - 10)

        self.text_area.append(
            f'<span style="color:{background_color}; font-family:Consolas; font-size:10pt;">{content}</span>'
        )

        if near_bottom:
            scrollbar.setValue(scrollbar.maximum())

