from typing import IO, Dict, List, Mapping, Optional, Tuple, Union, cast

# Type definitions for file handling, adapted from httpx's type system
# Reference: https://github.com/encode/httpx/blob/master/httpx/_types.py
FileData = Union[IO[bytes], bytes, str]
UploadedFile = Union[
    # raw file-like object or content
    FileData,
    # (filename, file-like object or content)
    Tuple[Optional[str], FileData],
    # (filename, file-like object or content, MIME type)
    Tuple[Optional[str], FileData, Optional[str]],
    # (filename, file-like object or content, MIME type, additional headers)
    Tuple[
        Optional[str],
        FileData,
        Optional[str],
        Mapping[str, str],
    ],
]

def transform_file_mapping_to_httpx_format(
    file_map: Dict[str, Union[UploadedFile, List[UploadedFile]]],
) -> List[Tuple[str, UploadedFile]]:
    """
    Converts a dictionary mapping field names to files into a list of tuples.
    This format is required by HTTPX when uploading multiple files per field.
    See: https://github.com/encode/httpx/pull/1032
    """
    result = []
    for field_name, file_obj in file_map.items():
        if isinstance(file_obj, list):
            for item in file_obj:
                result.append((field_name, item))
        else:
            result.append((field_name, file_obj))
    return result

def ensure_content_type(
    *,
    file_data: UploadedFile,
    fallback_content_type: str,
) -> UploadedFile:
    """
    Ensures the file has an associated content type. If not explicitly provided,
    falls back to the specified default content type.
    """
    if isinstance(file_data, tuple):
        length = len(file_data)
        if length == 2:
            filename, data = cast(Tuple[Optional[str], FileData], file_data)  # type: ignore
            return (filename, data, fallback_content_type)
        elif length == 3:
            filename, data, declared_type = cast(Tuple[Optional[str], FileData, Optional[str]], file_data)  # type: ignore
            final_type = declared_type if declared_type else fallback_content_type
            return (filename, data, final_type)
        elif length == 4:
            filename, data, declared_type, extra_headers = cast(  # type: ignore
                Tuple[Optional[str], FileData, Optional[str], Mapping[str, str]], file_data
            )
            final_type = declared_type if declared_type else fallback_content_type
            return (filename, data, final_type, extra_headers)
        else:
            raise ValueError(f"Invalid tuple structure: expected 2-4 elements, got {length}")

    # For non-tuple inputs, wrap with None filename and default content type
    return (None, file_data, fallback_content_type)

