# Health graph implementation using LangGraph with state management

from typing import TypedDict
from langgraph.graph import END, START, StateGraph

class HealthState(TypedDict):
    score: int

def increment_score(state: HealthState) -> HealthState:
    current = state.get("score", 0)
    return {"score": current + 1}

def double_score(state: HealthState) -> HealthState:
    current = state.get("score", 0)
    return {"score": current * 2}

def reduce_score(state: HealthState) -> HealthState:
    current = state.get("score", 0)
    return {"score": current - 3}

def create_health_workflow():
    workflow_builder = StateGraph(HealthState)

    workflow_builder.add_node("increment", increment_score)
    workflow_builder.add_node("double", double_score)
    workflow_builder.add_node("decrement", reduce_score)

    workflow_builder.add_edge(START, "increment")
    workflow_builder.add_edge("increment", "double")
    workflow_builder.add_edge("double", "decrement")
    workflow_builder.add_edge("decrement", END)

    return workflow_builder.compile()

if __name__ == "__main__":
    health_graph = create_health_workflow()
    final_result = health_graph.invoke({"score": 5})
    print(f"Final health score: {final_result['score']} (expected 7)")

