import fitz  # PyMuPDF alias

def get_pdf_content(pdf_path, page_limit=None):
    try:
        document = fitz.open(pdf_path)
        full_text = ""
        for idx, page in enumerate(document):
            if page_limit is not None and idx >= int(page_limit):
                break
            full_text += page.get_text() + "\n"
        return full_text
    except Exception as error:
        return f"Error: {str(error)}"

def retrieve_pdf_info(pdf_path):
    try:
        document = fitz.open(pdf_path)
        return document.metadata
    except Exception as error:
        return {"error": str(error)}

