    parser.add_argument("action", choices=["extract", "metadata"])
    parser.add_argument("source_file")
    parser.add_argument("--limit_pages", type=int, default=None)

    arguments = parser.parse_args()

    if arguments.action == "extract":
        print(get_pdf_content(arguments.source_file, arguments.limit_pages))
    elif arguments.action == "metadata":
        print(json.dumps(retrieve_pdf_info(arguments.source_file), indent=2))

import mlx.core as mx
import math

def softmax(x: mx.array, axis: int) -> mx.array:
    # Manual implementation using log-sum-exp trick for numerical stability
    x_max = mx.max(x, axis=axis, keepdims=True)
    exp_x = mx.exp(x - x_max)
    return exp_x / mx.sum(exp_x, axis=axis, keepdims=True)

def linear(
    x: mx.array,
    w: mx.array,
    bias: mx.array | None = None,
) -> mx.array:
    result = mx.matmul(x, w.T)
    if bias is not None:
        result = result + bias
    return result

def silu(x: mx.array) -> mx.array:
    # Alternative formulation: x * sigmoid(x)
    sigmoid_x = 1.0 / (1.0 + mx.exp(-x))
    return x * sigmoid_x

# Type III clone: Refactored version with equivalent functionality but different structure and implementation details

import time
import torch
from torch.distributed.tensor import DTensor, Replicate
from typing import Dict, Any, List, Tuple

# Helper functions for device handling
def _get_target_device(device_spec=None):
    """Convert various device specifications to a torch.device object."""
    if device_spec is None:
        return torch.empty(()).device
    return torch.empty((), device=device_spec).device

def _apply_module_transform(module, transform_fn, recurse=True):
    """Apply transformation function to module's parameters/buffers without unnecessary copies."""
    target_device = _get_target_device()
    return module._apply(
        lambda tensor: transform_fn(tensor, target_device),
        recurse=recurse
    )

def move_parameters_to_empty(model, device=None, recurse=True):
    """Move model parameters and buffers to specified device using empty tensors when needed."""
    def transform(tensor, device):
        return torch.empty_like(tensor, device=device) if tensor.device != device else tensor

    return _apply_module_transform(model, transform, recurse)

def convert_tensor_to_dtensor(local_tensor: torch.Tensor, device_mesh, placements):
    """Convert a local tensor to a distributed DTensor with specified placements."""
    # Create replicate placements for all dimensions of the mesh
    replicate_placements = [Replicate() for _ in range(device_mesh.ndim)]

    # First create a replicated DTensor from local tensor
    original_dtensor = DTensor.from_local(
        local_tensor=local_tensor,
        device_mesh=device_mesh,
        placements=replicate_placements
    )

    # Then redistribute to desired placements
    return original_dtensor.redistribute(
        device_mesh=device_mesh,
        placements=placements
    )

def initialize_model_weights(model):
    """Initialize model weights while preserving DTensor structure for special modules."""
    # Track modules requiring post-initialization processing
    delayed_initialization_list: List[Tuple[str, object, List[Replicate]]] = []

    def prepare_modules():
        # Mark all modules as not initialized and handle special cases
        for module_name, submodule in model.named_modules():
            setattr(submodule, "_is_initialized", False)

            # Clear HF initialization flag if present
            if getattr(submodule, "_is_hf_initialized", False):
                setattr(submodule, "_is_hf_initialized", False)

            # Handle Embedding layers with padding_idx specially
            if isinstance(submodule, torch.nn.Embedding) and submodule.padding_idx is not None:
                # Store metadata for later re-conversion to DTensor
                delayed_initialization_list.append([
                    module_name,
                    submodule.weight.data.device_mesh,
                    submodule.weight.data.placements
                ])

                # Replace weight with regular tensor temporarily
                new_weight = torch.empty(
                    submodule.weight.shape, 
                    device=submodule.weight.device
                )
                submodule.weight = torch.nn.Parameter(
                    new_weight, 
                    requires_grad=submodule.weight.requires_grad
                )

    def finalize_modules():
        # Restore DTensor structure for special modules after initialization
        if not delayed_initialization_list:
            return

        for target_name, mesh, placements in delayed_initialization_list:
            for name, module in model.named_modules():
                if name != target_name:
                    continue

                if isinstance(module, torch.nn.Embedding) and module.padding_idx is not None:
                    # Convert back to DTensor using stored mesh/placements
                    dtensor_weight = convert_tensor_to_dtensor(
                        module.weight.data, 
                        mesh, 
                        placements
                    )
                    module.weight = torch.nn.Parameter(
                        dtensor_weight,
                        requires_grad=module.weight.requires_grad
                    )

    # Execute initialization sequence
    prepare_modules()
    model.init_weights()
    finalize_modules()

def transfer_batch_to_device(batch: Dict[str, Any], float_dtype: str = None):
    """Transfer batch data to appropriate device with optional dtype conversion."""
    result_batch = {}

    for key, value in batch.items():
        # Handle special token count constants
        if key in ["avg_per_step_token_num", "global_step_token_num"]:
            result_batch[key] = value.to(device=torch.device("cuda" if torch.cuda.is_available() else "cpu"))

        # Handle tensor types
        elif isinstance(value, torch.Tensor):
            dtype = None
            if float_dtype and torch.is_floating_point(value):
                dtype = getattr(torch, float_dtype)
            result_batch[key] = value.to(
                device=torch.device("cuda" if torch.cuda.is_available() else "cpu"),
                dtype=dtype
            )

        # Handle list of tensors
        elif isinstance(value, list) and all(isinstance(item, torch.Tensor) for item in value):
            dtype = None
            if float_dtype:
                # Only apply dtype if any tensor in list is floating point
                if any(torch.is_floating_point(t) for t in value):
                    dtype = getattr(torch, float_dtype)

            result_batch[key] = [
                item.to(
                    device=torch.device("cuda" if torch.cuda.is_available() else "cpu"),
                    dtype=dtype
                ) for item in value
            ]
        else:
            # Keep other values unchanged
            result_batch[key] = value

    return result_batch

def get_timestamp_with_barrier(barrier=False):
    """Get current timestamp optionally synchronized across processes."""
    if barrier and torch.distributed.is_initialized():
        torch.distributed.barrier()

    # Synchronize device for accurate timing
    if torch.cuda.is_available():
        torch.cuda.synchronize()
    elif hasattr(torch, 'npu') and torch.npu.is_available():
        torch.npu.synchronize()

    return time.time()

def check_npu_support():
    """Check if NPU (Ascend) hardware is available."""
    try:
        import torch_npu
        return torch_npu.npu.is_available()
    except ImportError:
        return False

class SingletonMeta(type):
    """Metaclass implementing singleton pattern for classes."""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

