def perform_operation(x, y, symbol):
    """Perform arithmetic operations based on the given symbol"""
    if symbol == "+":
        return float(x) + float(y)
    elif symbol == "-":
        return float(x) - float(y)
    elif symbol == "*":
        return float(x) * float(y)
    elif symbol == "/":
        return float(x) / float(y)
    else:
        raise ValueError(f"Unsupported operation: {symbol}")

