import json
from pathlib import Path

def load_golden_dataset(directory: Path | str) -> list[dict]:
    """Loads all test cases from .json files in a specific golden dataset directory."""
    directory = Path(directory)
    results = []

    # Skip if directory doesn't exist or isn't actually a directory
    if not directory.exists() or not directory.is_dir():
        return results

    # Iterate through all JSON files in the directory
    for file_path in directory.glob("*.json"):
        try:
            with open(file_path, encoding="utf-8") as file:
                content = json.load(file)

                # Handle different data structures
                if isinstance(content, dict):
                    if "test_cases" in content and isinstance(content["test_cases"], list):
                        results.extend(content["test_cases"])
                    else:
                        results.append(content)
                elif isinstance(content, list):
                    results.extend(content)
                else:
                    results.append(content)

        except Exception as error:
            print(f"Failed to process {file_path}: {error}")

    return results

