from typing import List, TypeVar, Generic
T = TypeVar("T")

class Stack(Generic[T]):
    """A small shim over builtin list."""

    def __init__(self) -> None:
        self._items: List[T] = []

    @property
    def top(self) -> T:
        """Get top of stack."""
        if not self._items:
            raise IndexError("Stack is empty")
        return self._items[-1]

    def push(self, item: T) -> None:
        """Push an item on to the stack (append in stack nomenclature)."""
        self._items.append(item)

    def __len__(self) -> int:
        """Return the number of items in the stack."""
        return len(self._items)

    def __bool__(self) -> bool:
        """Return True if stack is not empty."""
        return bool(self._items)

import frida
import sys
import time
import os
from ipc import NamedPipeServer

# Configuration constants
TARGET_EXECUTABLE = "GrilsFrontLine.exe"
IPC_PIPE_IDENTIFIER = "MaaLunaPipe"
HOOK_SCRIPT_FILE = os.path.join(os.path.dirname(__file__), "hook.js")

active_script = None


def log_event(level: str, message: str):
    """Unified logging utility."""
    prefix = {"INFO": "[*]", "WARN": "[!]", "DEBUG": "[IPC DEBUG]"}
    print(f"{prefix.get(level, '[?]')} {message}")


def handle_frida_message(message, data):
    """Callback for Frida messages."""
    if message['type'] == 'send':
        payload = message.get('payload')
        if isinstance(payload, dict) and payload.get('type') == 'error':
            log_event("WARN", f"Hook Error: {payload.get('stack')}")
        else:
            log_event("INFO", f"Frida: {payload}")
    elif message['type'] == 'error':
        log_event("WARN", f"Frida Error: {message['stack']}")


def parse_command(raw_input: str):
    """
    Parses input into structured command.
    Returns tuple: (command_name, args_dict) or raises ValueError on failure.
    """
    tokens = raw_input.strip().split()
    if not tokens:
        raise ValueError("Empty command")
    cmd = tokens[0].upper()

    if cmd == 'MOVE' and len(tokens) == 3:
        try:
            x, y = map(int, tokens[1:])
            return 'MOVE', {'x': x, 'y': y}
        except ValueError:
            raise ValueError("Invalid coordinates in MOVE")
    elif cmd == 'WHEEL' and len(tokens) >= 4:
        try:
            delta = int(tokens[1])
            x, y = map(int, tokens[2:4])
            return 'WHEEL', {'delta': delta, 'x': x, 'y': y}
        except ValueError:
            raise ValueError("Invalid parameters in WHEEL")
    raise ValueError("Unknown or malformed command")


def process_ipc_request(request: str):
    """
    Handles incoming IPC requests and dispatches actions to Frida script.
    """
    global active_script

    log_event("DEBUG", f"Received raw message: '{request}'")

    if not active_script:
        log_event("WARN", "Global script is not loaded!")
        return "ERR_NO_SCRIPT"

    try:
        cmd_type, params = parse_command(request)

        if cmd_type == 'MOVE':
            active_script.post({'type': 'UPDATE_POS', **params})
            return "OK"

        elif cmd_type == 'WHEEL':
            # Update position first, then simulate wheel
            active_script.post({'type': 'UPDATE_POS', 'x': params['x'], 'y': params['y']})
            active_script.post({'type': 'SIMULATE_WHEEL', 'delta': params['delta']})
            return "OK"

        else:
            log_event("WARN", f"Unrecognized command: {cmd_type}")
            return "ERR_INVALID_CMD"

    except Exception as exc:
        log_event("WARN", f"Command processing failed: {exc}")
        return "ERR_EXCEPTION"


def establish_frida_session(target_name: str):
    """Attach to target process with retry logic."""
    session = None
    while session is None:
        try:
            session = frida.attach(target_name)
            log_event("INFO", f"Attached to {target_name}")
        except Exception as err:
            log_event("INFO", f"Waiting for process... ({err})")
            time.sleep(2)
    return session


def load_hook_script(session, script_path: str):
    """Load and initialize Frida hook script."""
    try:
        with open(script_path, encoding='utf-8') as fp:
            js_code = fp.read()
        script_obj = session.create_script(js_code)
        script_obj.on('message', handle_frida_message)
        script_obj.load()
        return script_obj
    except Exception as e:
        raise RuntimeError(f"Failed to load hook script: {e}")


def main():
    global active_script

    log_event("INFO", "Luna Service Starting...")
    log_event("INFO", f"Target Process: {TARGET_EXECUTABLE}")

    # Initialize IPC server
    pipe_server = NamedPipeServer(IPC_PIPE_IDENTIFIER, process_ipc_request)
    pipe_server.start()

    # Attach to target
    session = establish_frida_session(TARGET_EXECUTABLE)

    try:
        active_script = load_hook_script(session, HOOK_SCRIPT_FILE)
        log_event("INFO", f"Hook loaded. Pipe '\\\\.\\pipe\\{IPC_PIPE_IDENTIFIER}' ready.")

        # Block main thread until user interrupt
        sys.stdin.read()

    except KeyboardInterrupt:
        log_event("INFO", "Stopping...")
    except Exception as error:
        log_event("WARN", f"Unexpected error: {error}")
    finally:
        if session:
            session.detach()
        # Server thread will terminate automatically when process exits


if __name__ == '__main__':
    main()

