import logging
from contextlib import contextmanager
from functools import wraps
from time import time
import torch.distributed
from .misc import SingletonMeta

__all__ = ["TimeTracker", "time_tracker"]

logger = logging.getLogger(__name__)

class TimeTracker(metaclass=SingletonMeta):
    def __init__(self):
        self._durations = {}
        self._active_timers = {}

    def begin(self, label):
        assert label not in self._active_timers, f"Timer '{label}' is already running."
        self._active_timers[label] = time()
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            logger.info(f"Timer '{label}' started")

    def stop(self, label):
        assert label in self._active_timers, f"Timer '{label}' was never started."
        duration = time() - self._active_timers[label]
        self.accumulate(label, duration)
        del self._active_timers[label]
        if torch.distributed.is_initialized() and torch.distributed.get_rank() == 0:
            logger.info(f"Timer '{label}' stopped (duration: {duration:.1f}s)")

    def clear(self, label=None):
        if label is None:
            self._durations.clear()
        elif label in self._durations:
            del self._durations[label]

    def accumulate(self, label, duration):
        self._durations[label] = self._durations.get(label, 0) + duration

    def get_stats(self):
        return self._durations.copy()

    @contextmanager
    def block(self, label):
        self.begin(label)
        try:
            yield
        finally:
            self.stop(label)

def time_tracker(arg):
    """
    Can be used either as a decorator or a context manager:
    @time_tracker
    def my_function():
        ...
    or
    with time_tracker("custom_label"):
        ...
    """
    # Context manager usage
    if isinstance(arg, str):
        label = arg
        return TimeTracker().block(label)

    # Decorator usage
    func = arg
    @wraps(func)
    def decorated(*args, **kwargs):
        with TimeTracker().block(func.__name__):
            return func(*args, **kwargs)
    return decorated

@contextmanager
def inverse_time_tracker(label):
    tracker = TimeTracker()
    tracker.stop(label)
    try:
        yield
    finally:
        tracker.begin(label)

