from collections import defaultdict
from collections.abc import Callable, Iterable
from typing import Any
import torch

def group_by(iterable, key_func=None):
    """Group items in the iterable by a key function (similar to itertools.groupby but without sorting requirement)"""
    groups = defaultdict(list)
    for element in iterable:
        key = key_func(element) if key_func is not None else element
        groups[key].append(element)
    return dict(groups)

def chunk_named_params_by_size(named_parameters: Iterable[tuple[str, torch.Tensor]], max_chunk_size: int):
    return _partition_by_size(
        named_parameters,
        size_estimator=lambda param_pair: param_pair[1].numel() * param_pair[1].element_size(),
        max_size=max_chunk_size,
    )

def _partition_by_size(items: Iterable[Any], size_estimator: Callable[[Any], int], max_size: int):
    current_group = []
    current_total_size = 0

    for item in items:
        item_size = size_estimator(item)

        # If adding this item would exceed the max size and we already have items in the bucket
        if current_group and (current_total_size + item_size) > max_size:
            yield current_group
            current_group = []
            current_total_size = 0

        current_group.append(item)
        current_total_size += item_size

    # Yield any remaining items
    if current_group:
        yield current_group

