)

DEPLOYMENT_ENVIRONMENTS = ["prod", "dev", "stg"]

@contextlib.contextmanager
def open_auth(credential_path: Optional[Any], file_mode: str):
    if credential_path is None:
        logger.info(f"No credential path specified: {credential_path}")
        yield None
        return

    # Extract base name without extension
    filename_parts = credential_path.split("/")
    base_name = filename_parts[-1].split(".")[0] if filename_parts else ""

    if not base_name:
        raise ValueError(f"Unable to extract environment variable name from: {credential_path}")

    env_var_name = f"PROD_{base_name.upper()}"

    # Check if we're in a deployment environment and the credential exists in env
    if CRED_ENVS.APP_ENV in DEPLOYMENT_ENVIRONMENTS and env_var_name in CRED_ENVS_DICT:
        config = fetch_credentials_from_environment(env_var_name)
        logger.info(f"Loading credentials for {env_var_name} from environment variables")
        yield config
    else:
        logger.info(f"Reading credentials from file: {credential_path}")
        with open(credential_path, file_mode) as file_handle:
            yield file_handle

def fetch_credentials_from_environment(env_name: str) -> dict[str, str]:
    try:
        credentials = CRED_ENVS_DICT[env_name]
    except KeyError:
        raise ValueError(f"Environment variable {env_name} not found in CRED_ENVS")

    # Identify missing (empty) required fields
    missing_keys = {
        key.upper() 
        for key in credentials 
        if credentials[key] == ""
    }

    if missing_keys:
        raise ValueError(
            f"Missing or empty required environment variables for {env_name}",
            missing_keys,
        )

    return credentials

def load_json_from_file_or_none(file_obj):
    if CRED_ENVS.APP_ENV in DEPLOYMENT_ENVIRONMENTS:
        return file_obj if file_obj else {}
    else:
        return json.load(file_obj)

# Filter out None values from a dictionary

def clean_dict(input_map: Mapping[str, Optional[Any]]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    for key in input_map:
        val = input_map[key]
        if val is not None:
            result[key] = val
    return result

