def report_exception(exc: Exception, cmd_name: str, silent: bool) -> None:
    """Log and display an exception using Rich formatting."""
    # Store full error details for later inspection
    _error_log.append({
        "command": cmd_name,
        "exception_class": exc.__class__.__name__,
        "message": str(exc),
        "stack_trace": "".join(
            traceback.format_exception(type(exc), exc, exc.__traceback__)
        ),
    })

    if not silent:
        console.print(f"[error]Issue in '{cmd_name}' command:[/error]", style="error")

        if isinstance(exc, FileNotFoundError):
            console.print(f"  [error]Missing file:[/error] {exc}", style="error")
        elif isinstance(exc, ValueError):
            console.print(f"  [error]Invalid input:[/error] {exc}", style="error")
        elif isinstance(exc, IOError):
            console.print(f"  [error]I/O issue:[/error] {exc}", style="error")
        elif isinstance(exc, click.UsageError):
            console.print(f"  [error]Command usage problem:[/error] {exc}", style="error")
            raise exc
        elif isinstance(exc, MarkupError):
            console.print("  [error]Formatting issue:[/error] Malformed Rich markup detected.", style="error")
            console.print(escape(str(exc)))
        else:
            console.print(f"  [error]Unexpected failure:[/error] {exc}", style="error")

    # Check for strict exit mode via environment variable
    strict_mode = os.getenv("PDD_STRICT_EXIT", "").strip().lower() in {"1", "true", "yes", "on"}
    if strict_mode:
        sys.exit(1)
    # Do NOT re-raise here; allow caller to handle control flow

