from django.conf import settings

class CallbackRegistry:
    """Registry for managing NATS callback functions"""
    def __init__(self):
        self._registry = {}

    def register(self, name=None, func=None, **options):
        # Direct function registration: register(func, name='...', ...)
        if func is not None:
            return self._add_function(func, name, **options)

        # Decorator without parentheses: @register
        if callable(name) and func is None:
            return self._add_function(name, **options)

        # Decorator with arguments: @register(...)
        def decorator(func):
            return self.register(name, func, **options)
        return decorator

    def _add_function(self, func, name=None, **options):
        namespace = options.get('namespace', getattr(settings, 'NATS_NAMESPACE', 'default'))
        function_name = name or getattr(func, '_decorated_function', func).__name__
        is_js = options.get('js', False)

        identifier = f'{namespace}.js.{function_name}' if is_js else f'{namespace}.{function_name}'

        if identifier in self._registry:
            raise ValueError(f'Duplicate NATS function identifier `{identifier}`.')

        self._registry[identifier] = {
            'function': func,
            'namespace': namespace,
            'function_name': function_name,
            'is_js': is_js,
        }
        return func

# Global registry instance and access point
_global_registry = CallbackRegistry()
register = _global_registry.register

import time
import uuid
import torch.distributed as dist
from torch.distributed.distributed_c10d import _get_default_store

class DistributedMutex:
    def __init__(self, lock_name, retry_delay=0.05, group_suffix=None):
        if not dist.is_available() or not dist.is_initialized():
            raise RuntimeError("Distributed backend not active")

        self.backend = _get_default_store()
        suffix = group_suffix or f"group{dist.get_world_size()}"
        self.prefix = f"distributed_mutex/{suffix}/{lock_name}"
        self.counter_key = f"{self.prefix}/seq"
        self.owner_key = f"{self.prefix}/holder"
        self.retry_interval = retry_delay
        self.my_id = None

        # Initialize counter atomically if not present
        try:
            self.backend.add(self.counter_key, 0)
        except RuntimeError:
            # Counter already exists; ignore error
            pass

    def acquire(self, max_wait=None):
        begin_time = time.perf_counter()
        current_delay = self.retry_interval
        my_identifier = f"{dist.get_rank()}:{uuid.uuid4()}".encode()

        while True:
            try:
                # Atomically increment and get previous value
                prev_count = self.backend.add(self.counter_key, 1)

                if prev_count == 0:
                    # First in line: claim the lock
                    self._assign_owner(my_identifier)
                    self.my_id = my_identifier
                    return True

                # Not first: decrement counter to release our spot
                self._decrement_counter()

            except RuntimeError:
                # Handle contention or network issues gracefully
                pass

            # Check timeout condition
            if max_wait is not None and (time.perf_counter() - begin_time) > max_wait:
                return False

            # Exponential backoff with cap
            time.sleep(current_delay)
            current_delay = min(current_delay * 1.5, 0.5)

    def release(self):
        if self.my_id is None:
            raise RuntimeError("No lock held by this process")

        current_holder = self._retrieve_owner()
        if current_holder is not None and current_holder != self.my_id:
            raise RuntimeError("Lock ownership conflict detected")

        self._remove_owner()
        self._decrement_counter()
        self.my_id = None

    def _decrement_counter(self):
        wait_time = self.retry_interval
        while True:
            try:
                self.backend.add(self.counter_key, -1)
                return
            except RuntimeError:
                time.sleep(wait_time)
                wait_time = min(wait_time * 1.5, 0.5)

    def _assign_owner(self, identifier: bytes):
        try:
            self.backend.set(self.owner_key, identifier)
        except RuntimeError as e:
            self._decrement_counter()
            raise RuntimeError("Unable to register lock holder") from e

    def _retrieve_owner(self) -> bytes | None:
        try:
            result = self.backend.get(self.owner_key)
            return result if result else None
        except RuntimeError:
            return None

    def _remove_owner(self):
        try:
            self.backend.set(self.owner_key, b"")
        except RuntimeError:
            pass

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.release()
        return False

