class SequentialAgentConfig:
    @classmethod
    def from_components(cls, components, name="agent", step_names=None):
        return cls(components, name, step_names)

    def __init__(self, components, name, step_names):
        self.components = components
        self.name = name
        self.step_names = step_names or [f"step_{i}" for i in range(len(components))]

    def build_agent(self):
        return SequentialAgent(self.components, self.name, self.step_names)

class SequentialAgent:
    def __init__(self, chains, name, step_names):
        self.chains = chains
        self.name = name
        self.step_names = step_names

    def run(self, inputs: dict) -> dict:
        result = {}
        task = inputs.get("task_description", "")

        # Process through each chain sequentially
        for i, chain in enumerate(self.chains):
            step_input = {"task_description": task}
            step_result = chain.invoke(step_input)

            # Store intermediate results and update task description for next step
            result[self.step_names[i]] = step_result["output"]
            task = step_result["output"]

        # Generate final plan from last step output
        result["plan"] = f"Final Plan:\n1. {result.get(self.step_names[-1], '')}"
        return result

