from typing import List, Optional
from enum import Enum

class DimensionStrategy(Enum):
    APPLICATION = "application_first"
    INFRASTRUCTURE = "infrastructure_first"
    INSTANCE = "instance_first"
    CUSTOM = "custom"

class DimensionSelector:
    DEFAULT_DIMENSIONS = {
        DimensionStrategy.APPLICATION: ["service"],
        DimensionStrategy.INFRASTRUCTURE: ["location"],
        DimensionStrategy.INSTANCE: ["resource_name"],
    }
    PRIORITY_SEQUENCE = [
        DimensionStrategy.APPLICATION,
        DimensionStrategy.INFRASTRUCTURE,
        DimensionStrategy.INSTANCE,
    ]

    @classmethod
    def get_dimensions_for_priority(
        cls,
        strategy: str,
        user_defined_fields: Optional[List[str]] = None,
    ) -> List[List[str]]:
        if strategy == DimensionStrategy.CUSTOM.value or strategy == "custom":
            return [user_defined_fields] if user_defined_fields else [["event_id"]]

        try:
            selected_strategy = DimensionStrategy(strategy)
        except ValueError:
            selected_strategy = DimensionStrategy.INSTANCE

        start_position = cls.PRIORITY_SEQUENCE.index(selected_strategy)
        output = []

        for priority in cls.PRIORITY_SEQUENCE[start_position:]:
            output.append(cls.DEFAULT_DIMENSIONS[priority])

        output.append(["event_id"])
        return output

